      function setStartupTab(value){
        const next=cleanStartupTab(value);
        try{localStorage.setItem(startupTabStorageKey(),next)}catch(_){}
        updateStartupTabSetting();
        if(currentActor)markUiPreferencesChanged({startupTab:next,syncSchemaVersion:10});
        try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
      }
      function requestedInitialTab(){
        const route=routeFromLocation();
        return requestedAppTab||(route.tab!=='home'?route.tab:currentStartupTab());
      }


      function routeFromLocation(){
        try{
          const params=new URLSearchParams(window.location.search);
          const rawTab=String(params.get('tab')||'home').trim();
          const tab=rawTab==='saves'?'dates':rawTab;
          if(rawTab!=='home'&&!APP_TABS.includes(tab)){
            const clean=new URL(window.location.href);
            clean.searchParams.delete('tab');
            clean.searchParams.delete('message');
            clean.searchParams.delete('fresh');
            history.replaceState(history.state||null,'',clean.pathname+(clean.search||'')+(clean.hash||''));
          }
          return {
            tab:APP_TABS.includes(tab)?tab:'home',
            item:String(params.get('item')||'').trim()
          };
        }catch(_){return {tab:'home',item:''}}
      }

      function routeFreshRequested(){
        try{return new URLSearchParams(window.location.search).get('fresh')==='1'}catch(_){return false}
      }

      function clearRouteFreshFlag(){
        try{
          const url=new URL(window.location.href);
          if(!url.searchParams.has('fresh')) return;
          url.searchParams.delete('fresh');
          history.replaceState(history.state||null,'',url.pathname+(url.search||'')+(url.hash||''));
        }catch(_){}
      }

      function updateAppRoute(tab,{item='',replace=false}={}){
        try{
          const next=APP_TABS.includes(tab)?tab:'home';
          const url=new URL(window.location.href);
          if(next==='home') url.searchParams.delete('tab');
          else url.searchParams.set('tab',next);
          if(item&&['home','wishlist','products','dates','for-di','schedule','score','smart-saves'].includes(next)) url.searchParams.set('item',String(item));
          else url.searchParams.delete('item');
          const target=url.pathname+(url.search||'')+(url.hash||'');
          const current=window.location.pathname+window.location.search+window.location.hash;
          if(target===current) return;
          history[replace?'replaceState':'pushState']({rudiTab:next,rudiItem:item||''},'',target);
        }catch(_){}
      }

      function focusDeepLinkedItem(tab,item){
        const id=String(item||'').trim();
        if(!id) return;

        const homeSelectors={
          partner:'[data-home-tile="partner"]',
          lulu:'#homeLuluTile',
          'daily-question':'#dailyQuestionTile',
          'smart-home':'#smartHomeTile',
          priority:'[data-home-tile="priority"]',
          rustam:'#homeRustamTile',
          diana:'#homeDianaTile'
        };
        const scheduleSelectors={
          cycle:'#dianaCycleCard'
        };

        const tryFocus=(attempt=0)=>{
          let target=null;
          if(tab==='home'){
            const selector=homeSelectors[id];
            if(selector) target=document.querySelector(selector);
          }else if(tab==='schedule'){
            const selector=scheduleSelectors[id];
            if(selector) target=document.querySelector(selector);
          }else if(['wishlist','products','dates','for-di','smart-saves'].includes(tab)){
            target=[...document.querySelectorAll('[data-rudi-item-id]')]
              .find(node=>String(node.dataset.rudiItemId||'')===id)||null;
          }
          if(!target){
            if(attempt<12) setTimeout(()=>tryFocus(attempt+1),140);
            return;
          }

          if(target.classList.contains('is-collapsed')){
            const toggle=target.querySelector('.block-collapse-button,[aria-expanded="false"]');
            try{toggle?.click?.()}catch(_){}
          }
          target.classList.add('rudi-deep-link-target');
          target.scrollIntoView({behavior:'smooth',block:'center',inline:'nearest'});
          setTimeout(()=>target.classList.remove('rudi-deep-link-target'),2200);
          if(id==='partner') try{markPartnerMessageSeen()}catch(_){}
        };

        requestAnimationFrame(()=>requestAnimationFrame(()=>tryFocus(0)));
      }


