      function financeMoscowParts(date=new Date()){
        const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);
        return Object.fromEntries(parts.map(part=>[part.type,part.value]));
      }
      function financeNowDateTimeInputs(){
        const p=financeMoscowParts();
        return {date:p.year+'-'+p.month+'-'+p.day,time:p.hour+':'+p.minute};
      }
      function financeTemporalDisplayValue(input){
        const value=String(input?.value||'').trim();
        if(!value)return '—';
        if(input?.type==='date'){
          const match=value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
          if(!match)return value;
          const date=new Date(Date.UTC(Number(match[1]),Number(match[2])-1,Number(match[3]),12));
          if(Number.isNaN(date.getTime()))return value;
          return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(date);
        }
        return value;
      }
      function syncFinanceTemporalControl(inputOrId){
        const input=typeof inputOrId==='string'?document.getElementById(inputOrId):inputOrId;
        if(!input)return;
        const display=document.getElementById(input.id+'Display');
        if(display)display.textContent=financeTemporalDisplayValue(input);
      }
      function bindFinanceTemporalControls(){
        document.querySelectorAll('.finance-temporal-native').forEach(input=>{
          if(input.dataset.temporalBound==='1'){syncFinanceTemporalControl(input);return}
          input.dataset.temporalBound='1';
          const sync=()=>syncFinanceTemporalControl(input);
          input.addEventListener('input',sync);
          input.addEventListener('change',sync);
          input.addEventListener('blur',sync);
          sync();
        });
      }
      let financeMonthPickerState=null;
      function ensureFinanceMonthPicker(){
        let root=document.getElementById('financeMonthPickerDialog');
        if(root)return root;
        root=document.createElement('div');
        root.id='financeMonthPickerDialog';
        root.className='finance-month-dialog';
        root.hidden=true;
        root.setAttribute('aria-hidden','true');
        root.innerHTML=''
          +'<button class="finance-month-dialog-backdrop" type="button" aria-label="Закрыть выбор месяца" data-finance-month-close></button>'
          +'<section class="finance-month-dialog-sheet" role="dialog" aria-modal="true" aria-labelledby="financeMonthDialogTitle">'
          +'<div class="finance-month-dialog-head">'
          +'<div><span>Месяц</span><strong id="financeMonthDialogTitle">Выбери месяц</strong></div>'
          +'<button class="finance-month-dialog-close" type="button" aria-label="Закрыть" data-finance-month-close>×</button>'
          +'</div>'
          +'<div class="finance-month-year-row">'
          +'<button type="button" aria-label="Предыдущий год" data-finance-month-year="-1">‹</button>'
          +'<strong id="financeMonthPickerYear">—</strong>'
          +'<button type="button" aria-label="Следующий год" data-finance-month-year="1">›</button>'
          +'</div>'
          +'<div class="finance-month-grid" role="group" aria-label="Месяцы">'
          +['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'].map((label,index)=>'<button type="button" data-finance-month="'+String(index+1)+'">'+label+'</button>').join('')
          +'</div>'
          +'<button class="finance-month-current-button" type="button" data-finance-month-current>Текущий месяц</button>'
          +'</section>';
        document.body.append(root);
        root.querySelectorAll('[data-finance-month-close]').forEach(button=>button.addEventListener('click',closeFinanceMonthPicker));
        root.addEventListener('click',event=>{
          const yearButton=event.target.closest?.('[data-finance-month-year]');
          if(yearButton&&financeMonthPickerState){
            financeMonthPickerState.year=Math.min(2100,Math.max(2000,financeMonthPickerState.year+Number(yearButton.dataset.financeMonthYear||0)));
            renderFinanceMonthPicker();
            return;
          }
          const monthButton=event.target.closest?.('[data-finance-month]');
          if(monthButton&&financeMonthPickerState){
            selectFinanceMonthPickerMonth(Number(monthButton.dataset.financeMonth||0));
            return;
          }
          if(event.target.closest?.('[data-finance-month-current]')&&financeMonthPickerState){
            const current=financeCurrentMonthKey().match(/^(\d{4})-(\d{2})$/);
            if(current){
              financeMonthPickerState.year=Number(current[1]);
              selectFinanceMonthPickerMonth(Number(current[2]));
            }
          }
        });
        if(!window.__rudiFinanceMonthPickerKeyBound){
          window.__rudiFinanceMonthPickerKeyBound=true;
          document.addEventListener('keydown',event=>{
            if(event.key==='Escape'&&financeMonthPickerState)closeFinanceMonthPicker();
          });
        }
        return root;
      }
      function renderFinanceMonthPicker(){
        const state=financeMonthPickerState,root=document.getElementById('financeMonthPickerDialog');
        if(!state||!root)return;
        const yearLabel=root.querySelector('#financeMonthPickerYear');
        if(yearLabel)yearLabel.textContent=String(state.year);
        const current=financeCurrentMonthKey();
        root.querySelectorAll('[data-finance-month]').forEach(button=>{
          const month=Number(button.dataset.financeMonth||0);
          const key=String(state.year)+'-'+String(month).padStart(2,'0');
          const selected=state.selectedKey===key;
          button.classList.toggle('is-selected',selected);
          button.classList.toggle('is-current',current===key);
          button.setAttribute('aria-pressed',selected?'true':'false');
        });
      }
      function openFinanceMonthPicker(input){
        if(!input)return;
        const key=String(input.value||financeCurrentMonthKey());
        const match=key.match(/^(\d{4})-(\d{2})$/);
        const fallback=financeCurrentMonthKey().match(/^(\d{4})-(\d{2})$/);
        const year=Number(match?.[1]||fallback?.[1]||new Date().getFullYear());
        const selectedMonth=Number(match?.[2]||fallback?.[2]||1);
        financeMonthPickerState={
          input,
          year,
          selectedKey:String(year)+'-'+String(selectedMonth).padStart(2,'0'),
          returnFocus:document.activeElement
        };
        const root=ensureFinanceMonthPicker();
        root.hidden=false;
        root.setAttribute('aria-hidden','false');
        document.body.classList.add('finance-month-dialog-open');
        renderFinanceMonthPicker();
        requestAnimationFrame(()=>{
          root.classList.add('is-open');
          const selected=root.querySelector('[data-finance-month].is-selected');
          (selected||root.querySelector('[data-finance-month]'))?.focus?.({preventScroll:true});
        });
      }
      function closeFinanceMonthPicker(){
        const state=financeMonthPickerState,root=document.getElementById('financeMonthPickerDialog');
        financeMonthPickerState=null;
        if(root){
          root.classList.remove('is-open');
          root.hidden=true;
          root.setAttribute('aria-hidden','true');
        }
        document.body.classList.remove('finance-month-dialog-open');
        const returnFocus=state?.returnFocus;
        requestAnimationFrame(()=>{try{returnFocus?.focus?.({preventScroll:true})}catch(_){}});
      }
      function selectFinanceMonthPickerMonth(month){
        const state=financeMonthPickerState;
        if(!state||month<1||month>12)return;
        const next=String(state.year)+'-'+String(month).padStart(2,'0');
        state.input.value=next;
        state.input.dispatchEvent(new Event('input',{bubbles:true}));
        state.input.dispatchEvent(new Event('change',{bubbles:true}));
        closeFinanceMonthPicker();
        try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
      }
      function bindFinanceMonthPicker(container,input){
        if(!container||!input||container.dataset.monthPickerBound==='1')return;
        container.dataset.monthPickerBound='1';
        container.setAttribute('tabindex','0');
        container.setAttribute('role','button');
        container.setAttribute('aria-haspopup','dialog');
        container.setAttribute('aria-label',input.getAttribute('aria-label')||'Выбрать месяц');
        input.tabIndex=-1;
        input.setAttribute('aria-hidden','true');
        const open=event=>{
          event?.preventDefault?.();
          event?.stopPropagation?.();
          openFinanceMonthPicker(input);
        };
        container.addEventListener('click',open);
        container.addEventListener('keydown',event=>{
          if(event.key!=='Enter'&&event.key!==' ')return;
          open(event);
        });
      }

      function rudiTemporalDisplayValue(input){
        return financeTemporalDisplayValue(input);
      }
      function syncRudiTemporalControl(inputOrId){
        const input=typeof inputOrId==='string'?document.getElementById(inputOrId):inputOrId;
        if(!input)return;
        const wrapper=input.closest?.('.rudi-temporal-control');
        const display=wrapper?.querySelector?.('.rudi-temporal-value');
        if(display)display.textContent=rudiTemporalDisplayValue(input);
      }
      function enhanceRudiTemporalInput(input){
        if(!input||!['date','time'].includes(String(input.type||'')))return;
        if(input.matches?.('.finance-temporal-native,.finance-balance-month-input,.personal-habits-date-input'))return;
        if(input.dataset.rudiTemporalEnhanced==='1'||input.closest?.('.rudi-temporal-control')){syncRudiTemporalControl(input);return}
        const parent=input.parentNode;if(!parent)return;
        const wrapper=document.createElement('div');wrapper.className='rudi-temporal-control is-'+input.type;
        const display=document.createElement('span');display.className='rudi-temporal-value';
        const icon=document.createElement('span');icon.className='rudi-temporal-icon';icon.setAttribute('aria-hidden','true');
        icon.innerHTML=input.type==='date'
          ?'<svg viewBox="0 0 24 24" fill="none"><rect x="4" y="5.5" width="16" height="14" rx="3"/><path d="M8 3.5v4M16 3.5v4M4 10h16"/></svg>'
          :'<svg viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>';
        parent.insertBefore(wrapper,input);
        wrapper.append(display,icon,input);
        input.classList.add('rudi-temporal-native');
        input.dataset.rudiTemporalEnhanced='1';
        const sync=()=>syncRudiTemporalControl(input);
        input.addEventListener('input',sync);
        input.addEventListener('change',sync);
        input.addEventListener('blur',sync);
        sync();
      }
      function setupRudiTemporalControls(){
        const scan=root=>{
          if(root?.matches?.('input[type="date"],input[type="time"]'))enhanceRudiTemporalInput(root);
          root?.querySelectorAll?.('input[type="date"],input[type="time"]').forEach(enhanceRudiTemporalInput);
        };
        scan(document);
        if(!window.__rudiTemporalObserver&&document.body){
          window.__rudiTemporalObserver=new MutationObserver(mutations=>{
            for(const mutation of mutations)for(const node of mutation.addedNodes)if(node?.nodeType===1)scan(node);
          });
          window.__rudiTemporalObserver.observe(document.body,{childList:true,subtree:true});
        }
      }
      window.syncRudiTemporalControl=syncRudiTemporalControl;
      window.enhanceRudiTemporalInput=enhanceRudiTemporalInput;

      function ensureCurrentDateTimeInputs(dateId,timeId){
        const now=financeNowDateTimeInputs();
        const dateInput=document.getElementById(dateId),timeInput=document.getElementById(timeId);
        if(dateInput&&!String(dateInput.value||'').trim())dateInput.value=now.date;
        if(timeInput&&!String(timeInput.value||'').trim())timeInput.value=now.time;
        return {
          date:String(dateInput?.value||now.date).trim()||now.date,
          time:String(timeInput?.value||now.time).trim()||now.time
        };
      }
      function financeOccurredAtFromInputs(){
        const {date,time}=ensureCurrentDateTimeInputs('financeExpenseComposerDate','financeExpenseComposerTime');
        const value=new Date(date+'T'+time+':00+03:00');
        return Number.isNaN(value.getTime())?new Date().toISOString():value.toISOString();
      }
      function financeDateTimeLabel(value){
        const date=new Date(value||Date.now());
        if(Number.isNaN(date.getTime()))return {day:'Без даты',time:'—',key:''};
        const key=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
        const day=new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'long',year:'numeric'}).format(date);
        const time=new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}).format(date);
        return {day:day.charAt(0).toUpperCase()+day.slice(1),time,key};
      }
      function financePercent(value){
        const number=Math.abs(Number(value)||0);
        return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1,minimumFractionDigits:number<10&&Math.abs(number-Math.round(number))>.01?1:0}).format(number)+'%';
      }
      function financeMonthTitle(value){
        const month=String(value||'');
        if(!/^\d{4}-\d{2}$/.test(month))return '—';
        const date=new Date(month+'-01T12:00:00Z');
        if(Number.isNaN(date.getTime()))return month;
        const text=new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'}).format(date);
        return text.charAt(0).toUpperCase()+text.slice(1);
      }
      function financeNormalizeSharedItems(items){
        const out=[],seen=new Set();
        for(const raw of Array.isArray(items)?items:[]){
          const title=String(raw?.title||'').trim().replace(/\s+/g,' ').slice(0,60);
          const id=String(raw?.id||'').trim().slice(0,100);
          const amount=Math.max(0,Number(raw?.amount)||0);
          if(!title||!id||seen.has(id))continue;
          seen.add(id);out.push({id,title,amount:Math.round(amount*100)/100});
          if(out.length>=24)break;
        }
        return out;
      }
      function financeSplit(rent,utilities,items=[]){
        const extras=financeNormalizeSharedItems(items).reduce((sum,row)=>sum+Number(row.amount||0),0);
        const total=Math.round((Math.max(0,Number(rent)||0)+Math.max(0,Number(utilities)||0)+extras)*100)/100;
        const diana=Math.round(total*40)/100;
        const rustam=Math.round((total-diana)*100)/100;
        return {total,diana,rustam};
      }
      function financeSharedItemsFromInputs(){
        return financeNormalizeSharedItems([...document.querySelectorAll('#financeSharedExtraList [data-finance-shared-item]')].map(row=>({
          id:row.dataset.financeSharedItem,
          title:row.querySelector('.finance-shared-extra-title')?.value||row.dataset.financeSharedTitle||'',
          amount:Number(row.querySelector('.finance-shared-extra-amount')?.value||0)
        })));
      }
      function financeSharedItemsEqual(left,right){
        const a=financeNormalizeSharedItems(left),b=financeNormalizeSharedItems(right);
        return a.length===b.length&&a.every((row,index)=>row.id===b[index].id&&row.title===b[index].title&&Number(row.amount||0)===Number(b[index].amount||0));
      }
      function financeSharedSummaryText(rent,utilities,items=[]){
        return ['Квартира '+financeMoney(rent),'ЖКУ '+financeMoney(utilities),...financeNormalizeSharedItems(items).map(row=>row.title+' '+financeMoney(row.amount))].join(' · ');
      }
      function refreshFinanceSharedDraft(){
        const month=document.getElementById('financeMonthInput')?.value||financeCurrentMonthKey();
        renderFinanceSummary(document.getElementById('financeRentInput')?.value||0,document.getElementById('financeUtilitiesInput')?.value||0,month,financeSharedItemsFromInputs());
        syncFinanceSaveButton();
      }
      function renderFinanceSharedItems(items=[]){
        const host=document.getElementById('financeSharedExtraList');if(!host)return;
        host.replaceChildren();
        const canEdit=currentActor==='Рустам';
        for(const item of financeNormalizeSharedItems(items)){
          const field=document.createElement('div');field.className='finance-input-field finance-shared-extra-field';field.dataset.financeSharedItem=item.id;field.dataset.financeSharedTitle=item.title;
          const head=document.createElement('div');head.className='finance-shared-extra-head';
          if(canEdit){
            const title=document.createElement('input');title.type='text';title.className='finance-shared-extra-title';title.maxLength=60;title.value=item.title;title.setAttribute('aria-label','Название совместного расхода');title.addEventListener('input',()=>{field.dataset.financeSharedTitle=title.value;refreshFinanceSharedDraft()});
            const remove=document.createElement('button');remove.type='button';remove.className='finance-shared-extra-remove';remove.setAttribute('aria-label','Удалить '+item.title);remove.textContent='×';remove.addEventListener('click',()=>{field.remove();refreshFinanceSharedDraft()});
            head.append(title,remove);
          }else{
            const title=document.createElement('span');title.className='finance-shared-extra-title-view';title.textContent=item.title;head.append(title);
          }
          const money=document.createElement('div');money.className='finance-money-input';
          const amount=document.createElement('input');amount.type='number';amount.min='0';amount.max='10000000';amount.step='1';amount.inputMode='decimal';amount.placeholder='0';amount.value=item.amount>0?String(item.amount):'';amount.disabled=!canEdit;amount.className='finance-shared-extra-amount';amount.setAttribute('aria-label','Сумма '+item.title);amount.addEventListener('input',refreshFinanceSharedDraft);
          const currency=document.createElement('b');currency.textContent='₽';money.append(amount,currency);field.append(head,money);host.append(field);
        }
      }
      function financeDebounce(key,fn,delay=650){
        const old=financeSaveTimers.get(key);if(old)clearTimeout(old);
        financeSaveTimers.set(key,setTimeout(()=>{financeSaveTimers.delete(key);Promise.resolve(fn()).catch(()=>{})},delay));
      }
      async function financeRequest(operation='list',payload={}){
        const response=await fetch('/api/finances',{
          method:'POST',headers:{'Content-Type':'application/json'},
          body:JSON.stringify({initData:tg?.initData||'',operation,...payload}),cache:'no-store'
        });
        const data=await response.json().catch(()=>({}));
        if(!response.ok||!data.ok){const error=new Error(data.error||'finance-request-failed');error.status=response.status;throw error}
        if(data.score) renderScoreStickers(data.score);
        return data;
      }
      function financeRowForMonth(month){return (financeState.months||[]).find(row=>String(row?.month||'')===String(month||''))||null}
      function financePersonalRowForMonth(month){return (financeState.personalMonths||[]).find(row=>String(row?.month||'')===String(month||''))||null}
      function financeExpensesForMonth(month){
        return (financeState.personalExpenses||[]).filter(row=>String(row?.month||'')===String(month||''));
      }
      function financeExpenseTotal(month){
        return Math.round(financeExpensesForMonth(month).reduce((sum,row)=>sum+Number(row.rubAmount||row.amount||0),0)*100)/100;
      }
      function financeCategorySpent(categoryId,month){
        return Math.round(financeExpensesForMonth(month).filter(row=>row.categoryId===categoryId).reduce((sum,row)=>sum+Number(row.rubAmount??row.amount??0),0)*100)/100;
      }
      function financeCategoryMonthTrend(categoryId,month){
        const previousMonth=financePreviousMonthKey(month);
        const current=financeCategorySpent(categoryId,month);
        const previous=previousMonth?financeCategorySpent(categoryId,previousMonth):0;
        if(!previousMonth)return {direction:'flat',text:'—',previousMonth:''};
        if(previous<=0){
          if(current<=0)return {direction:'flat',text:'0%',previousMonth};
          return {direction:'up',text:'↑ новое',previousMonth};
        }
        const delta=(current-previous)/previous*100;
        if(Math.abs(delta)<.5)return {direction:'flat',text:'0%',previousMonth};
        return {direction:delta>0?'up':'down',text:(delta>0?'↑ ':'↓ ')+financePercent(delta),previousMonth};
      }
      function financeCategoryById(id){return (financeState.categories||[]).find(row=>row.id===id)||null}
      function financeAllCategoryById(id){return [...(financeState.categories||[]),...(financeState.archivedCategories||[])].find(row=>row.id===id)||null}
      function financeWalletById(id){return (financeState.wallets||[]).find(row=>row.id===id)||null}

      function financeAllOperations(){
        const rows=[];
        for(const row of financeState.personalExpenses||[]){
          if(row?.manualAdjustment)continue;
          rows.push({kind:'expense',occurredAt:row.occurredAt||row.createdAt,row});
        }
        for(const row of financeState.walletIncomes||[])rows.push({kind:'income',occurredAt:row.occurredAt||row.createdAt,row});
        for(const row of financeState.walletTransfers||[])rows.push({kind:'transfer',occurredAt:row.occurredAt||row.createdAt,row});
        return rows.sort((a,b)=>String(b.occurredAt||'').localeCompare(String(a.occurredAt||'')));
      }
      function financeOperationSearchText(entry){
        const row=entry.row||{};
        if(entry.kind==='expense'){
          const category=financeAllCategoryById(row.categoryId),wallet=financeWalletById(row.walletId);
          return [category?.name,row.label,row.note,wallet?.name,row.sourceCurrency,row.targetCurrency].filter(Boolean).join(' ').toLocaleLowerCase('ru-RU');
        }
        if(entry.kind==='income'){
          const wallet=financeWalletById(row.walletId);
          return ['доход',wallet?.name,row.note,row.currency].filter(Boolean).join(' ').toLocaleLowerCase('ru-RU');
        }
        const from=financeWalletById(row.fromWalletId),to=financeWalletById(row.toWalletId);
        return ['перевод',from?.name,to?.name,row.note,row.sourceCurrency,row.targetCurrency].filter(Boolean).join(' ').toLocaleLowerCase('ru-RU');
      }
      function renderFinanceOperationFilters(){
        const walletSelect=document.getElementById('financeOperationWallet');
        const categorySelect=document.getElementById('financeOperationCategory');
        const labelSelect=document.getElementById('financeOperationLabel');
        if(walletSelect){
          const value=walletSelect.value;
          walletSelect.innerHTML='<option value="">Все кошельки</option>';
          for(const wallet of financeState.wallets||[]){const o=document.createElement('option');o.value=wallet.id;o.textContent=wallet.name;walletSelect.append(o)}
          if([...walletSelect.options].some(o=>o.value===value))walletSelect.value=value;
        }
        if(categorySelect){
          const value=categorySelect.value;
          categorySelect.innerHTML='<option value="">Все категории</option>';
          for(const category of [...(financeState.categories||[]),...(financeState.archivedCategories||[])]){const o=document.createElement('option');o.value=category.id;o.textContent=category.name;categorySelect.append(o)}
          if([...categorySelect.options].some(o=>o.value===value))categorySelect.value=value;
        }
        if(labelSelect){
          const value=labelSelect.value;
          labelSelect.innerHTML='<option value="">Все метки</option>';
          const labels=[...new Set((financeState.personalExpenses||[])
            .filter(row=>!row?.manualAdjustment&&String(row?.label||'').trim())
            .map(row=>String(row.label).trim()))]
            .sort((a,b)=>a.localeCompare(b,'ru'));
          for(const label of labels){const o=document.createElement('option');o.value=label;o.textContent=label;labelSelect.append(o)}
          if([...labelSelect.options].some(o=>o.value===value))labelSelect.value=value;
        }
      }
      function financeOperationDayTitle(dateKey,todayKey,yesterdayKey,currentMonth){
        if(dateKey===todayKey)return 'Сегодня';
        if(dateKey===yesterdayKey)return 'Вчера';
        const match=String(dateKey||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);
        if(!match)return dateKey||'Без даты';
        const date=new Date(Date.UTC(Number(match[1]),Number(match[2])-1,Number(match[3]),12));
        if(Number.isNaN(date.getTime()))return dateKey;
        const options=dateKey.startsWith(currentMonth+'-')
          ?{day:'numeric',month:'long',timeZone:'UTC'}
          :{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'};
        const value=new Intl.DateTimeFormat('ru-RU',options).format(date);
        return value.charAt(0).toUpperCase()+value.slice(1);
      }
      function financeSelectedPersonalMonth(){
        return String(document.getElementById('financePersonalMonthInput')?.value||financeCurrentMonthKey());
      }
      function financePreviewExpense(payload){
        const category=financeAllCategoryById(payload.categoryId);
        const wallet=payload.walletId?financeWalletById(payload.walletId):null;
        if(!category||(payload.walletId&&!wallet))return null;
        const sourceCurrency=String(wallet?.currency||category.currency||'RUB').toUpperCase();
        const targetCurrency=String(category.currency||'RUB').toUpperCase();
        const inputCurrency=String(payload.inputCurrency||sourceCurrency).toUpperCase();
        if(inputCurrency!==sourceCurrency&&inputCurrency!==targetCurrency)return null;
        const rates=financeWalletRubRates();
        const sourceRate=Number(rates[sourceCurrency]||0);
        const targetRate=Number(rates[targetCurrency]||0);
        if(sourceRate<=0||targetRate<=0)return null;
        const roundMoney=value=>Math.round(Number(value)*100)/100;
        const roundAsset=value=>Math.round(Number(value)*100000000)/100000000;
        const input=Number(payload.amount);
        let amount,sourceAmount,rubAmount;
        if(inputCurrency===targetCurrency&&targetCurrency!==sourceCurrency){
          amount=roundMoney(input);
          rubAmount=roundMoney(amount*targetRate);
          sourceAmount=roundAsset(rubAmount/sourceRate);
        }else{
          sourceAmount=roundAsset(input);
          rubAmount=roundMoney(sourceAmount*sourceRate);
          amount=roundMoney(rubAmount/targetRate);
        }
        if(!Number.isFinite(amount)||!Number.isFinite(sourceAmount)||rubAmount<=0||sourceAmount<=0)return null;
        return {id:'pending-expense-'+Date.now(),actor:currentActor,month:payload.month,
          categoryId:payload.categoryId,walletId:payload.walletId||'',note:payload.note||'',
          label:payload.label||'',sourceCurrency,targetCurrency,sourceAmount,amount,rubAmount,
          exchangeRate:roundAsset(amount/sourceAmount),occurredAt:payload.occurredAt,
          createdAt:new Date().toISOString(),optimistic:true};
      }
      function financeRenderExpensePreview(month){
        renderFinancePersonalMonth(month);
        renderFinanceWallets();
        renderFinanceOperations();
        renderFinanceAnalytics();
        renderFinanceCapitalHistory();
        if(financeCategoryHistoryId)renderFinanceCategoryHistory();
      }
      function financeApplyExpensePreview(row,remove=false){
        const isExternal=String(row.importKey||'').startsWith('ozon:');
        const change=(remove?1:-1)*Number(row.sourceAmount||0);
        const wallets=!isExternal&&row.walletId&&Number.isFinite(change)
          ?financeState.wallets.map(wallet=>wallet.id===row.walletId
            ?{...wallet,balance:Math.round((Number(wallet.balance||0)+change)*100000000)/100000000}
            :wallet)
          :financeState.wallets;
        const personalExpenses=remove
          ?financeState.personalExpenses.filter(item=>item.id!==row.id&&
            !(item.manualAdjustment&&item.month===row.month&&item.categoryId===row.categoryId))
          :[row,...financeState.personalExpenses];
        financeState={...financeState,personalExpenses,wallets};
        financeRenderExpensePreview(row.month);
      }
      function financeExpenseSaveError(error){
        const code=String(error?.message||'');
        return code.includes('wallet-insufficient')?'Превышен кредитный лимит'
          :code.includes('currency')||code.includes('rate')?'Не удалось получить курс валют'
          :'Не удалось сохранить расход';
      }
      function financeExpenseAlert(message){
        try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
        try{if(tg?.showAlert){tg.showAlert(message);return}}catch(_){}
        window.alert(message);
      }
      function renderFinanceOperations(){
        const list=document.getElementById('financeOperationList');
        const empty=document.getElementById('financeOperationEmpty');
        const count=document.getElementById('financeOperationCount');
        const summary=document.getElementById('financeOperationSummary');
        if(!list)return;
        renderFinanceOperationFilters();
        const selectedMonth=financeSelectedPersonalMonth();
        const q=String(document.getElementById('financeOperationSearch')?.value||'').trim().toLocaleLowerCase('ru-RU');
        const walletId=String(document.getElementById('financeOperationWallet')?.value||'');
        const categoryId=String(document.getElementById('financeOperationCategory')?.value||'');
        const label=String(document.getElementById('financeOperationLabel')?.value||'');
        const from=String(document.getElementById('financeOperationFrom')?.value||'');
        const to=String(document.getElementById('financeOperationTo')?.value||'');
        const explicitDateRange=Boolean(from||to);
        const rows=(financeState.personalExpenses||[])
          .filter(row=>{
            if(row?.manualAdjustment)return false;
            const date=financeDateTimeLabel(row.occurredAt||row.createdAt).key;
            if(!explicitDateRange&&String(row.month||'')!==selectedMonth)return false;
            if(from&&date<from)return false;
            if(to&&date>to)return false;
            if(walletId&&String(row.walletId||'')!==walletId)return false;
            if(categoryId&&String(row.categoryId||'')!==categoryId)return false;
            if(label&&String(row.label||'')!==label)return false;
            if(q&&!financeOperationSearchText({kind:'expense',row}).includes(q))return false;
            return true;
          })
          .sort((a,b)=>String(b.occurredAt||b.createdAt||'').localeCompare(String(a.occurredAt||a.createdAt||'')))
          .slice(0,500);
        list.replaceChildren();
        const total=rows.reduce((sum,row)=>sum+Number(row.rubAmount||row.amount||0),0);
        if(count)count.textContent=String(rows.length);
        if(summary)summary.textContent='Фактические расходы '+financeMoney(total)+' · '+rows.length+' операций';
        const totalHost=document.getElementById('financeExpenseHistoryTotal');
        if(totalHost)totalHost.textContent=financeMoney(total);
        const monthHost=document.getElementById('financeExpenseHistoryMonth');
        if(monthHost)monthHost.textContent=explicitDateRange?'Выбранный период':financeMonthTitle(selectedMonth);
        if(empty){
          empty.hidden=rows.length>0;
          empty.textContent='Расходов по выбранным фильтрам нет';
        }
        const now=financeMoscowParts();
        const todayKey=now.year+'-'+now.month+'-'+now.day;
        const yesterdayKey=financeDateTimeLabel(new Date(new Date(todayKey+'T12:00:00+03:00').getTime()-86400000)).key;
        const groups=new Map();
        for(const row of rows){
          const meta=financeDateTimeLabel(row.occurredAt||row.createdAt),key=meta.key||'unknown';
          if(!groups.has(key))groups.set(key,[]);
          groups.get(key).push({row,meta});
        }
        for(const [dateKey,entries] of groups){
          const group=document.createElement('section');group.className='finance-operation-day';
          const head=document.createElement('div');head.className='finance-operation-day-head';
          const title=document.createElement('strong');title.textContent=financeOperationDayTitle(dateKey,todayKey,yesterdayKey,selectedMonth);
          const dayTotal=document.createElement('b');dayTotal.className='finance-operation-day-total';
          dayTotal.textContent='−'+financeMoney(entries.reduce((sum,{row})=>sum+Number(row.rubAmount||row.amount||0),0));
          const daySummary=document.createElement('div');daySummary.className='finance-operation-day-summary';
          const dayCount=document.createElement('span');dayCount.textContent=String(entries.length);
          daySummary.append(dayTotal,dayCount);head.append(title,daySummary);group.append(head);
          const rowsHost=document.createElement('div');rowsHost.className='finance-operation-day-list';
          for(const {row,meta} of entries){
            const item=document.createElement('div');item.className='finance-operation-row is-expense';
            const icon=document.createElement('span');icon.className='finance-operation-icon';icon.textContent='−';
            const copy=document.createElement('div');copy.className='finance-operation-copy';
            const rowTitle=document.createElement('strong'),detail=document.createElement('small'),value=document.createElement('b');
            const category=financeAllCategoryById(row.categoryId),wallet=financeWalletById(row.walletId);
            rowTitle.textContent=(category?.name||'Расход')+(row.label?' · '+row.label:'');
            detail.textContent=[wallet?.name,row.note,meta.time].filter(Boolean).join(' · ');
            value.textContent='−'+financeMoney(row.rubAmount||row.amount);
            if(row.optimistic){item.classList.add('is-pending');detail.textContent=[wallet?.name,row.note,'Сохраняется…'].filter(Boolean).join(' · ')}
            const del=document.createElement('button');del.type='button';del.className='finance-operation-delete';
            del.textContent='×';del.setAttribute('aria-label','Удалить расход: '+(category?.name||'Расход'));
            del.addEventListener('click',async event=>{
              event.stopPropagation();
              if(financeExpenseMutationInFlight)return;
              const approved=await smartSaveConfirm('Удалить расход «'+(category?.name||'Расход')+'» на '+financeMoney(row.rubAmount||row.amount)+'?');
              if(!approved||financeExpenseMutationInFlight)return;
              financeExpenseMutationInFlight=true;
              const previousState=financeState,previousMonth=financeSelectedPersonalMonth();
              del.disabled=true;
              financeApplyExpensePreview(row,true);
              try{
                const data=await financeRequest('delete-expense',{id:row.id});
                renderFinanceState(data,{personalMonth:previousMonth,preserveIncome:true,preservePlan:true});
                refreshFinanceInsight(true).catch(()=>{});
                try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
              }catch(error){
                financeState=previousState;
                financeRenderExpensePreview(previousMonth);
                financeExpenseAlert('Не удалось удалить расход. Баланс восстановлен.');
                loadFinances({silent:true}).catch(()=>{});
              }finally{financeExpenseMutationInFlight=false;del.disabled=false}
            });
            copy.append(rowTitle,detail);item.append(icon,copy,value,del);rowsHost.append(item);
          }
          group.append(rowsHost);list.append(group);
        }
        animateRudiCollection(list,'.finance-operation-day',10);
      }
