      function closeFinanceLedgerPage(){
        const page=document.getElementById('financePage');
        page?.classList.remove('is-expense-history','is-income-history','is-capital-history');
        const expense=document.getElementById('financeExpenseHistoryPage');
        const income=document.getElementById('financeIncomeHistoryPage');
        const capital=document.getElementById('financeCapitalHistoryPage');
        if(expense){expense.hidden=true;expense.setAttribute('aria-hidden','true')}
        if(income){income.hidden=true;income.setAttribute('aria-hidden','true')}
        if(capital){capital.hidden=true;capital.setAttribute('aria-hidden','true')}
        const restoreY=Math.max(0,Number(financeLedgerReturnScrollY||0));
        requestAnimationFrame(()=>window.scrollTo({top:restoreY,behavior:'auto'}));
      }
      function openFinanceLedgerPage(kind){
        const page=document.getElementById('financePage');
        if(!page)return;
        financeLedgerReturnScrollY=Math.max(0,Number(window.scrollY||document.scrollingElement?.scrollTop||0));
        const expense=document.getElementById('financeExpenseHistoryPage');
        const income=document.getElementById('financeIncomeHistoryPage');
        const capital=document.getElementById('financeCapitalHistoryPage');
        const isExpense=kind==='expense';
        const isIncome=kind==='income';
        const isCapital=kind==='capital';
        page.classList.toggle('is-expense-history',isExpense);
        page.classList.toggle('is-income-history',isIncome);
        page.classList.toggle('is-capital-history',isCapital);
        if(expense){expense.hidden=!isExpense;expense.setAttribute('aria-hidden',isExpense?'false':'true')}
        if(income){income.hidden=!isIncome;income.setAttribute('aria-hidden',isIncome?'false':'true')}
        if(capital){capital.hidden=!isCapital;capital.setAttribute('aria-hidden',isCapital?'false':'true')}
        if(isExpense)renderFinanceOperations();
        else if(isIncome)renderFinanceIncomeHistory();
        else if(isCapital){renderFinanceCapitalHistory();recordFinanceCapitalSnapshot().catch(()=>{})}
        const opened=isExpense?expense:isIncome?income:capital;
        restartRudiMotion(opened,'finance-panel-enter',420);
        requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'auto'}));
      }

      function financeAnalyticsRange(period){
        const now=financeMoscowParts(),today=now.year+'-'+now.month+'-'+now.day;
        const selectedMonth=document.getElementById('financePersonalMonthInput')?.value||financeCurrentMonthKey();
        const date=new Date(today+'T12:00:00+03:00');
        let from=today,to=today,previousFrom='',previousTo='';
        if(period==='week'){
          const dow=(date.getDay()+6)%7;const start=new Date(date);start.setDate(date.getDate()-dow);const end=new Date(start);end.setDate(start.getDate()+6);
          from=financeDateTimeLabel(start).key;to=financeDateTimeLabel(end).key;
          const ps=new Date(start);ps.setDate(ps.getDate()-7);const pe=new Date(end);pe.setDate(pe.getDate()-7);previousFrom=financeDateTimeLabel(ps).key;previousTo=financeDateTimeLabel(pe).key;
        }else if(period==='month'){
          const [y,m]=selectedMonth.split('-').map(Number);from=selectedMonth+'-01';to=new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);
          const prev=financePreviousMonthKey(selectedMonth),[py,pm]=prev.split('-').map(Number);previousFrom=prev+'-01';previousTo=new Date(Date.UTC(py,pm,0)).toISOString().slice(0,10);
        }else if(period==='year'){
          const year=selectedMonth.slice(0,4);from=year+'-01-01';to=year+'-12-31';previousFrom=(Number(year)-1)+'-01-01';previousTo=(Number(year)-1)+'-12-31';
        }else if(period==='custom'){
          from=document.getElementById('financeAnalyticsFrom')?.value||today;to=document.getElementById('financeAnalyticsTo')?.value||today;
        }
        return {from,to,previousFrom,previousTo};
      }
      function renderFinanceAnalytics(){
        const period=String(document.getElementById('financeAnalyticsPeriod')?.value||'month');
        const custom=document.getElementById('financeAnalyticsCustom');if(custom)custom.hidden=period!=='custom';
        const range=financeAnalyticsRange(period);
        const rows=financeAllOperations().filter(entry=>{const d=financeDateTimeLabel(entry.occurredAt).key;return d>=range.from&&d<=range.to});
        const cashflowRows=rows.filter(entry=>entry.kind==='expense'||entry.kind==='income');
        let expenses=0,income=0;const byCategory=new Map();
        for(const entry of rows){
          if(entry.kind==='expense'){const amount=Number(entry.row.rubAmount||entry.row.amount||0);expenses+=amount;byCategory.set(entry.row.categoryId,(byCategory.get(entry.row.categoryId)||0)+amount)}
          if(entry.kind==='income')income+=Number(entry.row.rubAmount||0);
        }
        const set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};
        set('financeAnalyticsExpenses',financeMoney(expenses));set('financeAnalyticsIncome',financeMoney(income));set('financeAnalyticsNet',financeMoney(income-expenses));set('financeAnalyticsCount',String(cashflowRows.length));
        const compare=document.getElementById('financeAnalyticsCompare');
        if(compare){
          if(range.previousFrom&&range.previousTo){
            const prev=financeAllOperations().filter(entry=>entry.kind==='expense').filter(entry=>{const d=financeDateTimeLabel(entry.occurredAt).key;return d>=range.previousFrom&&d<=range.previousTo}).reduce((sum,e)=>sum+Number(e.row.rubAmount||e.row.amount||0),0);
            if(prev>0){const delta=(expenses-prev)/prev*100;compare.textContent=(delta>=0?'Расходы выше на ':'Расходы ниже на ')+financePercent(delta)+' к предыдущему периоду';compare.dataset.direction=delta>=0?'up':'down'}
            else{compare.textContent='Нет расходов в предыдущем периоде';compare.dataset.direction='none'}
          }else{compare.textContent='Свой период: сравнение отключено';compare.dataset.direction='none'}
        }
        const host=document.getElementById('financeAnalyticsCategories');
        if(host){
          host.replaceChildren();
          const total=Math.max(1,expenses);
          [...byCategory.entries()].sort((a,b)=>b[1]-a[1]).slice(0,8).forEach(([id,amount])=>{
            const category=financeAllCategoryById(id);const row=document.createElement('div');row.className='finance-analytics-category';
            row.innerHTML='<div><span>'+(category?.icon||'💳')+'</span><strong></strong><b></b></div><div class="finance-analytics-bar"><i></i></div>';
            row.querySelector('strong').textContent=category?.name||'Категория';row.querySelector('b').textContent=financeMoney(amount);row.querySelector('i').style.width=Math.min(100,amount/total*100)+'%';host.append(row);
          });
        }
      }
      function financeTodayObligationCount(){
        const now=financeMoscowParts();
        const month=now.year+'-'+now.month;
        const day=Number(now.day||0);
        const obligations=Array.isArray(financeState.plan?.obligations)?financeState.plan.obligations:[];
        return obligations.filter(row=>{
          if(row?.active===false)return false;
          if(Number(row?.day||0)!==day)return false;
          return !(Array.isArray(row?.paidMonths)&&row.paidMonths.includes(month));
        }).length;
      }
      function syncFinanceObligationAttention(){
        const count=financeTodayObligationCount();
        const badge=document.getElementById('financeProfileBadge');
        if(badge){
          badge.textContent=count>99?'99+':String(count);
          badge.hidden=count<=0;
          badge.setAttribute('aria-label',count>0?('Обязательных расходов сегодня: '+count):'');
        }
        document.documentElement.dataset.financeObligationCount=String(count);
        queueAppIconBadgeSync();
        return count;
      }
      // Same net wallet balance as "Общий баланс": includes credit balances and FX conversion.
      // Compare against unpaid obligations for the CURRENT month even when history is selected.
      function renderFinanceObligationCoverage(){
        const view=document.getElementById('financeObligationCoverage');
        if(!view)return;
        const month=financeCurrentMonthKey();
        const obligations=(Array.isArray(financeState.plan?.obligations)?financeState.plan.obligations:[])
          .filter(row=>row&&row.active!==false);
        const due=Math.round(obligations.reduce((sum,row)=>{
          const alreadyPaid=Array.isArray(row.paidMonths)&&row.paidMonths.includes(month);
          return sum+(alreadyPaid?0:Math.max(0,Number(row.amount)||0));
        },0)*100)/100;
        view.dataset.state='neutral';
        if(!obligations.length){
          view.textContent='Проверка баланса: добавь ежемесячные платежи';
          return;
        }
        if(due<=0){
          view.dataset.state='enough';
          view.textContent='Все ежемесячные платежи этого месяца оплачены';
          return;
        }
        const wallets=Array.isArray(financeState.wallets)?financeState.wallets:[];
        if(!wallets.length){
          view.textContent='Хватит ли денег: добавь баланс кошелька';
          return;
        }
        const rates=financeWalletRubRates();
        let available=0;
        for(const wallet of wallets){
          const balance=Number(wallet?.balance||0);
          if(!Number.isFinite(balance)){view.textContent='Невозможно проверить баланс кошельков';return}
          if(Math.abs(balance)<1e-12)continue;
          const rate=Number(rates[String(wallet?.currency||'RUB').toUpperCase()]||0);
          if(rate<=0){view.textContent='Для проверки баланса нужен актуальный курс валют';return}
          available+=balance*rate;
        }
        if(financeBalanceHidden){
          view.textContent='Хватит ли денег: баланс скрыт';
          return;
        }
        if(financeOverviewDisplayCurrency==='USD'&&financeOverviewUsdRate()<=0){
          view.textContent='Для расчёта в долларах нужен курс USD';
          return;
        }
        const difference=Math.round((available-due)*100)/100;
        view.dataset.state=difference>=0?'enough':'short';
        view.textContent=difference>=0
          ?'На платежи этого месяца хватит · останется '+financeOverviewMoney(difference)
          :'На платежи этого месяца не хватит '+financeOverviewMoney(-difference);
      }
      function renderFinanceObligations(){
        syncFinanceObligationAttention();
        const list=document.getElementById('financeObligationList'),forecast=document.getElementById('financeObligationForecast');if(!list||!forecast)return;
        list.replaceChildren();
        const month=document.getElementById('financePersonalMonthInput')?.value||financeCurrentMonthKey();
        const obligations=(Array.isArray(financeState.plan?.obligations)?financeState.plan.obligations:[])
          .slice()
          .sort((a,b)=>Number(a?.day||0)-Number(b?.day||0)||String(a?.title||'').localeCompare(String(b?.title||''),'ru'));
        let pending=0;
        for(const row of obligations){
          if(row.active===false)continue;
          const paid=Array.isArray(row.paidMonths)&&row.paidMonths.includes(month);
          if(!paid)pending+=Number(row.amount||0);
          const item=document.createElement('div');item.className='finance-obligation-row'+(paid?' is-paid':'');
          const toggle=document.createElement('button');toggle.type='button';toggle.className='finance-obligation-toggle';toggle.textContent=paid?'✓':'○';toggle.title=paid?'Отметить как неоплаченный':'Отметить оплаченным';
          const copy=document.createElement('button');copy.type='button';copy.className='finance-obligation-copy';copy.innerHTML='<strong></strong><small></small>';copy.querySelector('strong').textContent=row.title;copy.querySelector('small').textContent=financeOverviewMoney(row.amount)+' · '+row.day+' числа';
          const del=document.createElement('button');del.type='button';del.className='finance-obligation-delete';del.textContent='×';
          toggle.addEventListener('click',()=>toggleFinanceObligationPaid(row.id,!paid));copy.addEventListener('click',()=>openFinanceObligationComposer(row.id));del.addEventListener('click',()=>deleteFinanceObligation(row.id));
          item.append(toggle,copy,del);list.append(item);
        }
        forecast.textContent=obligations.length?'До конца месяца: '+financeOverviewMoney(pending):'Запланированных ежемесячных расходов нет';
        renderFinanceObligationCoverage();
        animateRudiCollection(list,'.finance-obligation-row',10);
      }
