      function renderFinancePulse(month){
        const row=financePersonalRowForMonth(month)||{};
        const income=Math.max(0,Number(row.income||0));
        const plannedLimit=(Array.isArray(financeState.categories)?financeState.categories:[])
          .reduce((sum,category)=>sum+Math.max(0,Number(category?.monthlyLimit||0)),0);
        const actualSpent=financeExpenseTotal(month);
        const plannedRemaining=Math.round((plannedLimit-actualSpent)*100)/100;
        const coinIncome=document.getElementById('financeCoinIncomeValue');
        const plannedTotal=document.getElementById('financePlannedMonthTotal');
        const yesterdayTotal=document.getElementById('financeYesterdayExpenseTotal');
        const todayTotal=document.getElementById('financeTodayExpenseTotal');
        if(coinIncome)coinIncome.textContent=financeBalanceHidden?'••••':financeOverviewMoney(income);
        if(plannedTotal){
          plannedTotal.textContent=financeBalanceHidden?'••••':financeOverviewMoney(plannedRemaining);
          plannedTotal.classList.toggle('is-over-limit',plannedRemaining<0);
          plannedTotal.title='Сумма всех лимитов категорий минус расходы за '+financeMonthTitle(month);
        }
        const progressBar=document.getElementById('financeBalanceProgressBar');
        const progressPercent=document.getElementById('financeBalanceProgressPercent');
        const spentPercent=plannedLimit>0?Math.max(0,actualSpent/plannedLimit*100):(actualSpent>0?100:0);
        if(progressBar)progressBar.style.width=Math.min(100,spentPercent)+'%';
        if(progressPercent)progressPercent.textContent=financePercent(spentPercent);
        document.querySelector('.finance-balance-progress')?.classList.toggle('is-over',spentPercent>100);
        if(yesterdayTotal||todayTotal){
          const now=financeMoscowParts();
          const todayKey=now.year+'-'+now.month+'-'+now.day;
          const yesterdayKey=financeDateTimeLabel(new Date(new Date(todayKey+'T12:00:00+03:00').getTime()-86400000)).key;
          const dailySpent=dateKey=>Math.round((financeState.personalExpenses||[])
            .filter(row=>!row?.manualAdjustment&&financeDateTimeLabel(row.occurredAt||row.createdAt).key===dateKey)
            .reduce((sum,row)=>sum+Number(row.rubAmount||row.amount||0),0)*100)/100;
          if(yesterdayTotal)yesterdayTotal.textContent=financeBalanceHidden?'••••':financeOverviewMoney(dailySpent(yesterdayKey));
          if(todayTotal)todayTotal.textContent=financeBalanceHidden?'••••':financeOverviewMoney(dailySpent(todayKey));
        }
        syncFinanceOverviewCurrencyButton();
        renderFinanceObligations();
      }
      function renderFinancePlan({preserveInputs=false}={}){
        const plan=financeState.plan||{},title=document.getElementById('financeGoalTitleInput'),current=document.getElementById('financeGoalCurrentInput'),target=document.getElementById('financeGoalTargetInput');
        if(!preserveInputs){
          if(title)title.value=String(plan.goalTitle||'');
          if(current)current.value=Number(plan.goalCurrent||0)>0?String(plan.goalCurrent):'';
          if(target)target.value=Number(plan.goalTarget||0)>0?String(plan.goalTarget):'';
        }
        const currentValue=Math.max(0,Number(current?.value||plan.goalCurrent||0)),targetValue=Math.max(0,Number(target?.value||plan.goalTarget||0));
        const pct=targetValue>0?Math.max(0,Math.min(100,currentValue/targetValue*100)):0;
        const bar=document.getElementById('financeGoalProgressBar'),text=document.getElementById('financeGoalProgressText');
        if(bar)bar.style.width=pct+'%';
        if(text)text.textContent=targetValue>0?(String(title?.value||plan.goalTitle||'Цель')+': '+financeMoney(currentValue)+' из '+financeMoney(targetValue)+' · '+financePercent(pct)):'Добавь цель, чтобы видеть прогресс';
      }
