      async function saveFinanceCategoryOrder(){
        const ids=[...document.querySelectorAll('#financeCategoryList .finance-category-coin-item')].map(node=>String(node.dataset.categoryId||'')).filter(Boolean);
        if(!ids.length)return;
        try{
          const month=document.getElementById('financePersonalMonthInput')?.value||financeCurrentMonthKey();
          const data=await financeRequest('reorder-categories',{ids});
          renderFinanceState(data,{personalMonth:month,preserveIncome:true,preservePlan:true});
          setFinanceCategoryEditMode(true);
        }catch(_){}
      }

      function financeCategoryMoveByPointer(list,item,clientX,clientY){
        const items=[...list.querySelectorAll('.finance-category-coin-item')].filter(node=>node!==item);
        if(!items.length)return;
        const measured=items.map(node=>{
          const rect=node.getBoundingClientRect();
          return {node,rect,cx:rect.left+rect.width/2,cy:rect.top+rect.height/2};
        }).sort((a,b)=>a.cy-b.cy||a.cx-b.cx);

        const rows=[];
        for(const info of measured){
          let row=rows.find(group=>Math.abs(group.cy-info.cy)<=Math.max(18,info.rect.height*.45));
          if(!row){
            row={cy:info.cy,items:[]};
            rows.push(row);
          }
          row.items.push(info);
          row.cy=row.items.reduce((sum,current)=>sum+current.cy,0)/row.items.length;
        }
        rows.sort((a,b)=>a.cy-b.cy);
        rows.forEach(row=>row.items.sort((a,b)=>a.cx-b.cx));

        let row=rows[0];
        let best=Math.abs(clientY-row.cy);
        for(const candidate of rows.slice(1)){
          const distance=Math.abs(clientY-candidate.cy);
          if(distance<best){row=candidate;best=distance}
        }

        const before=row.items.find(info=>clientX<info.cx);
        if(before){
          list.insertBefore(item,before.node);
          return;
        }

        const rowIndex=rows.indexOf(row);
        const nextRow=rows[rowIndex+1];
        if(nextRow?.items?.length){
          list.insertBefore(item,nextRow.items[0].node);
          return;
        }
        const add=list.querySelector('.finance-add-category-item');
        if(add)list.insertBefore(item,add);
        else list.appendChild(item);
      }

      function bindFinanceCategoryInteractions(item,list,category){
        let gesture=null;

        const cleanupGesture=()=>{
          if(!gesture)return;
          if(gesture.timer)clearTimeout(gesture.timer);
          document.removeEventListener('pointermove',gesture.onMove,true);
          document.removeEventListener('pointerup',gesture.onEnd,true);
          document.removeEventListener('pointercancel',gesture.onEnd,true);
          gesture=null;
        };

        const beginReorder=(event,{fromLongPress=false,startX=event.clientX,startY=event.clientY}={})=>{
          financeCategoryReorder={
            pointerId:event.pointerId,item,startX,startY,
            moved:false,startedByLongPress:fromLongPress
          };
          try{item.setPointerCapture?.(event.pointerId)}catch(_){}
        };

        item.addEventListener('pointerdown',event=>{
          if(event.button!==undefined&&event.button!==0)return;
          if(event.target.closest?.('.finance-category-delete-badge'))return;
          cleanupGesture();

          const onMove=moveEvent=>{
            if(!gesture||moveEvent.pointerId!==gesture.pointerId)return;

            if(!financeCategoryEditMode&&!gesture.longPressed){
              const distance=Math.hypot(moveEvent.clientX-gesture.startX,moveEvent.clientY-gesture.startY);
              if(distance>10){
                if(gesture.timer){clearTimeout(gesture.timer);gesture.timer=0}
                return;
              }
            }

            const drag=financeCategoryReorder;
            if(!drag||drag.item!==item||drag.pointerId!==moveEvent.pointerId)return;
            const distance=Math.hypot(moveEvent.clientX-drag.startX,moveEvent.clientY-drag.startY);
            if(!drag.moved&&distance<4)return;

            drag.moved=true;
            item.classList.add('is-reordering');
            if(moveEvent.cancelable)moveEvent.preventDefault();

            const before=[...list.querySelectorAll('.finance-category-coin-item')]
              .map(node=>node.dataset.categoryId).join('|');
            financeCategoryMoveByPointer(list,item,moveEvent.clientX,moveEvent.clientY);
            const after=[...list.querySelectorAll('.finance-category-coin-item')]
              .map(node=>node.dataset.categoryId).join('|');
            if(before!==after)try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
          };

          const onEnd=endEvent=>{
            if(!gesture||endEvent.pointerId!==gesture.pointerId)return;
            const drag=financeCategoryReorder;
            const moved=Boolean(drag&&drag.item===item&&drag.pointerId===endEvent.pointerId&&drag.moved);
            const startedByLongPress=Boolean(drag?.startedByLongPress);
            financeCategoryReorder=null;
            financeCategoryLongPress=null;
            item.classList.remove('is-reordering');
            try{item.releasePointerCapture?.(endEvent.pointerId)}catch(_){}
            cleanupGesture();

            if(moved){
              item.dataset.suppressClick='1';
              saveFinanceCategoryOrder();
            }else if(startedByLongPress){
              item.dataset.suppressClick='1';
            }
          };

          gesture={
            pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,
            longPressed:false,timer:0,onMove,onEnd
          };
          document.addEventListener('pointermove',onMove,{capture:true,passive:false});
          document.addEventListener('pointerup',onEnd,true);
          document.addEventListener('pointercancel',onEnd,true);

          if(financeCategoryEditMode){
            beginReorder(event,{fromLongPress:false});
            if(event.cancelable)event.preventDefault();
            return;
          }

          const state={
            pointerId:event.pointerId,item,startX:event.clientX,startY:event.clientY,
            entered:false,timer:0
          };
          state.timer=setTimeout(()=>{
            if(!gesture||gesture.pointerId!==event.pointerId)return;
            state.entered=true;
            gesture.longPressed=true;
            item.dataset.suppressClick='1';
            financeCategoryLongPress=null;
            setFinanceCategoryEditMode(true);
            beginReorder(event,{fromLongPress:true,startX:state.startX,startY:state.startY});
            try{tg?.HapticFeedback?.impactOccurred?.('medium')}catch(_){}
          },560);
          gesture.timer=state.timer;
          financeCategoryLongPress=state;
        });

        item.addEventListener('click',event=>{
          if(item.dataset.suppressClick==='1'){
            delete item.dataset.suppressClick;
            event.preventDefault();
            return;
          }
          if(financeCategoryEditMode){
            event.preventDefault();
            openFinanceCategoryComposer(category.id);
            return;
          }
          openFinanceCategoryHistory(category.id);
        });

        item.addEventListener('keydown',event=>{
          if(financeCategoryEditMode)return;
          if(event.key==='Enter'||event.key===' '){
            event.preventDefault();
            openFinanceCategoryHistory(category.id);
          }
        });
      }

      function renderFinanceCategories(month){
        const list=document.getElementById('financeCategoryList'),empty=document.getElementById('financeCategoryEmpty'),count=document.getElementById('financeCategoryCount'),totalHost=document.getElementById('financeExpenseMonthTotal');
        if(!list)return;
        const categories=Array.isArray(financeState.categories)?financeState.categories:[];
        const expenses=financeExpensesForMonth(month);
        if(count)count.textContent=String(categories.length);
        if(empty)empty.hidden=categories.length>0;
        if(totalHost)totalHost.textContent=financeBalanceHidden?'••••':financeOverviewMoney(financeExpenseTotal(month));
        list.replaceChildren();

        const palette=['#34c99a','#ffb52b','#6b9cff','#f27372','#9b7cff','#2fc7c9','#f28f44','#8dbf45','#d96daf','#5ba8d8'];
        categories.forEach((category,index)=>{
          const spent=financeCategorySpent(category.id,month);
          const item=document.createElement('div');item.className='finance-coin-item finance-category-coin-item';item.dataset.categoryId=category.id;item.style.setProperty('--finance-coin-color',palette[index%palette.length]);
          item.setAttribute('role','button');item.tabIndex=0;
          const remove=document.createElement('button');remove.type='button';remove.className='finance-category-delete-badge';remove.textContent='×';remove.setAttribute('aria-label','Удалить '+String(category.name||'категорию'));
          remove.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();openFinanceCategoryDeleteChooser(category.id)});
          const label=document.createElement('span');label.className='finance-coin-label';label.textContent=category.name||'Категория';
          const coin=document.createElement('span');coin.className='finance-coin finance-category-coin';coin.textContent=category.icon||'💳';
          const limitValue=Math.max(0,Number(category.monthlyLimit||0));
          const limitRub=financeAmountToRub(limitValue,category.currency||'RUB');
          const amount=document.createElement('span');amount.className='finance-coin-amount';amount.textContent=financeBalanceHidden?'••••':financeOverviewMoney(spent);
          if(limitValue>0&&Number.isFinite(limitRub)&&spent>limitRub)amount.classList.add('is-over-limit');
          const limit=document.createElement('span');limit.className='finance-coin-limit';
          limit.textContent=limitValue>0?(financeBalanceHidden?'••••':financeDisplayMoney(limitValue,category.currency||'RUB')):'';
          if(limitValue>0){
            const usage=Number.isFinite(limitRub)&&limitRub>0?Math.max(0,spent/limitRub):0;
            const usagePercent=Math.min(100,usage*100);
            coin.classList.add('has-budget');
            coin.style.setProperty('--finance-budget-progress',usagePercent+'%');
            coin.classList.toggle('is-budget-low',usage<.5);
            coin.classList.toggle('is-budget-mid',usage>=.5&&usage<1);
            coin.classList.toggle('is-budget-full',usage>=1);
            amount.classList.toggle('is-budget-low',usage<.5);
            amount.classList.toggle('is-budget-mid',usage>=.5&&usage<1);
            amount.classList.toggle('is-budget-full',usage>=1);
          }
          const monthTrend=financeCategoryMonthTrend(category.id,month);
          const trend=document.createElement('span');trend.className='finance-category-trend is-'+monthTrend.direction;trend.textContent=monthTrend.text;
          if(monthTrend.previousMonth)trend.title='К '+financeMonthTitle(monthTrend.previousMonth);
          item.append(remove,label,coin,amount);
          if(limitValue>0)item.append(limit);
          item.append(trend);
          bindFinanceCategoryInteractions(item,list,category);
          list.append(item);
        });

        const add=document.createElement('button');add.type='button';add.className='finance-coin-item finance-add-category-item';
        const addLabel=document.createElement('span');addLabel.className='finance-coin-label';addLabel.textContent='Категория';
        const addCoin=document.createElement('span');addCoin.className='finance-coin finance-add-category-coin';addCoin.textContent='+';
        const addText=document.createElement('span');addText.className='finance-coin-amount';addText.textContent='Добавить';
        add.append(addLabel,addCoin,addText);add.addEventListener('click',()=>{setFinanceCategoryEditMode(false);openFinanceCategoryComposer()});list.append(add);
        list.classList.toggle('is-editing',financeCategoryEditMode);
        if(!financeCategoryEditMode)animateRudiCollection(list,'.finance-coin-item',10);
        bindFinanceIncomeDrag();
      }

      function financeCsvEscape(value){
        const text=String(value??'');
        return /[;"\n\r]/.test(text)?'"'+text.replace(/"/g,'""')+'"':text;
      }
      function financeSpreadsheetXmlEscape(value){
        return String(value??'').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'')
          .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
          .replace(/"/g,'&quot;').replace(/'/g,'&apos;');
      }
      function financeSpreadsheetZip(entries){
        // Store-only ZIP: valid XLSX without external scripts or downloads.
        const encoder=new TextEncoder(),output=[],directory=[];
        const table=new Uint32Array(256);
        for(let k=0;k<256;k++){let c=k;for(let j=0;j<8;j++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;table[k]=c>>>0}
        let offset=0;
        const crc32=bytes=>{
          let c=0xffffffff;
          for(let k=0;k<bytes.length;k++)c=table[(c^bytes[k])&255]^(c>>>8);
          return (c^0xffffffff)>>>0;
        };
        for(const [filename,content] of entries){
          const name=encoder.encode(filename),data=encoder.encode(content),crc=crc32(data);
          const local=new Uint8Array(30+name.length),lv=new DataView(local.buffer);
          lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);
          lv.setUint16(6,0x0800,true);lv.setUint32(14,crc,true);
          lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);
          lv.setUint16(26,name.length,true);local.set(name,30);
          output.push(local,data);
          const central=new Uint8Array(46+name.length),cv=new DataView(central.buffer);
          cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);
          cv.setUint16(8,0x0800,true);cv.setUint32(16,crc,true);
          cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);
          cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);
          central.set(name,46);directory.push(central);
          offset+=local.length+data.length;
        }
        const dirSize=directory.reduce((sum,item)=>sum+item.length,0);
        const end=new Uint8Array(22),view=new DataView(end.buffer);
        view.setUint32(0,0x06054b50,true);view.setUint16(8,entries.length,true);
        view.setUint16(10,entries.length,true);view.setUint32(12,dirSize,true);
        view.setUint32(16,offset,true);
        return new Blob([...output,...directory,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
      }
      function exportFinanceSpreadsheet(){
        const rows=[['Дата','Время','Тип','Категория / кошелёк','Сумма ₽','Кошелёк','Исходная сумма','Валюта','Курс ₽','Комментарий']];
        const operations=[];
        for(const row of financeState.personalExpenses||[])operations.push({kind:'Расход',occurredAt:row.occurredAt||row.createdAt,row});
        for(const row of financeState.walletIncomes||[])operations.push({kind:'Доход',occurredAt:row.occurredAt||row.createdAt,row});
        operations.sort((a,b)=>String(a.occurredAt||'').localeCompare(String(b.occurredAt||'')));
        for(const entry of operations){
          const row=entry.row,meta=financeDateTimeLabel(entry.occurredAt);
          if(entry.kind==='Доход'){
            const wallet=financeWalletById(row.walletId);
            rows.push([meta.key,meta.time,'Доход',wallet?.name||'Кошелёк',Number(row.rubAmount||0),
              wallet?.name||'',Number(row.amount||0),row.currency||wallet?.currency||'RUB',
              Number(row.exchangeRate||1),row.note||'']);
          }else{
            const category=financeAllCategoryById(row.categoryId),wallet=financeWalletById(row.walletId);
            rows.push([meta.key,meta.time,'Расход',category?.name||'Удалённая категория',
              Number(row.rubAmount||row.amount||0),wallet?.name||'',
              Number(row.sourceAmount||row.amount||0),row.sourceCurrency||'RUB',
              Number(row.exchangeRate||1),row.note||'']);
          }
        }
        const escape=financeSpreadsheetXmlEscape;
        const colName=n=>{let value=n+1,name='';while(value){name=String.fromCharCode(65+(value-1)%26)+name;value=Math.floor((value-1)/26)}return name};
        const rowXml=rows.map((row,index)=>{
          const cells=row.map((value,col)=>{
            const ref=colName(col)+(index+1);
            if(index>0&&[4,6,8].includes(col)&&Number.isFinite(Number(value))){
              return '<c r="'+ref+'" s="2"><v>'+Number(value)+'</v></c>';
            }
            return '<c r="'+ref+'" t="inlineStr"'+(index===0?' s="1"':'')+'><is><t xml:space="preserve">'+escape(value)+'</t></is></c>';
          }).join('');
          return '<row r="'+(index+1)+'"'+(index===0?' ht="29" customHeight="1"':'')+'>'+cells+'</row>';
        }).join('');
        const lastRow=rows.length;
        const sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          +'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
          +'<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>'
          +'<sheetFormatPr defaultRowHeight="21"/><cols>'
          +[17,11,14,29,17,25,20,12,16,50].map((width,k)=>'<col min="'+(k+1)+'" max="'+(k+1)+'" width="'+width+'" customWidth="1"/>').join('')
          +'</cols><sheetData>'+rowXml+'</sheetData><autoFilter ref="A1:J'+lastRow+'"/></worksheet>';
        const styles='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          +'<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
          +'<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font></fonts>'
          +'<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF26354A"/><bgColor indexed="64"/></patternFill></fill></fills>'
          +'<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>'
          +'<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
          +'<cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>'
          +'<xf numFmtId="0" fontId="1" fillId="1" borderId="0" xfId="0" applyFill="1" applyFont="1"/>'
          +'<xf numFmtId="4" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs>'
          +'</styleSheet>';
        const files=[
          ['[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>'],
          ['_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],
          ['xl/workbook.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Операции" sheetId="1" r:id="rId1"/></sheets></workbook>'],
          ['xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'],
          ['xl/worksheets/sheet1.xml',sheet],['xl/styles.xml',styles],
        ];
        const blob=financeSpreadsheetZip(files),url=URL.createObjectURL(blob);
        const link=document.createElement('a');link.href=url;
        link.download='rudi-finances-'+new Date().toISOString().slice(0,10)+'.xlsx';
        document.body.append(link);link.click();link.remove();
        setTimeout(()=>URL.revokeObjectURL(url),1500);
      }

      function parseFinanceCsv(text,{keepEmpty=false}={}){
        let source=String(text||'').replace(/^\uFEFF/,'');
        let delimiter=',';
        const sep=source.match(/^sep=(.)\r?\n/i);
        if(sep){delimiter=sep[1];source=source.slice(sep[0].length)}
        else{
          const first=(source.split(/\r?\n/,1)[0]||'');
          delimiter=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?';':',';
        }
        const rows=[];let row=[],field='',quoted=false;
        for(let i=0;i<source.length;i++){
          const ch=source[i];
          if(quoted){
            if(ch==='"'&&source[i+1]==='"'){field+='"';i++}
            else if(ch==='"')quoted=false;
            else field+=ch;
          }else if(ch==='"')quoted=true;
          else if(ch===delimiter){row.push(field);field=''}
          else if(ch==='\n'){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field=''}
          else field+=ch;
        }
        if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row)}
        return keepEmpty?rows:rows.filter(row=>row.some(cell=>String(cell||'').trim()));
      }

      function financeHeaderKey(value){
        return String(value||'').trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е').replace(/[._-]+/g,' ').replace(/\s+/g,' ');
      }
      function financeCsvHash(value){
        let h=2166136261;const text=String(value||'');
        for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}
        return (h>>>0).toString(36);
      }
      function financeParseImportedDate(value){
        const raw=String(value||'').trim();
        if(!raw)return null;
        const ru=raw.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{2,4})(?:[ T]+(\d{1,2}):(\d{2}))?/);
        if(ru){
          const year=ru[3].length===2?'20'+ru[3]:ru[3],month=String(Number(ru[2])).padStart(2,'0'),day=String(Number(ru[1])).padStart(2,'0');
          const hour=String(Number(ru[4]||12)).padStart(2,'0'),minute=String(Number(ru[5]||0)).padStart(2,'0');
          const date=new Date(year+'-'+month+'-'+day+'T'+hour+':'+minute+':00+03:00');
          return Number.isNaN(date.getTime())?null:date;
        }
        const parsed=new Date(raw);
        return Number.isNaN(parsed.getTime())?null:parsed;
      }
      function financeParseNumber(value){
        const cleaned=String(value||'').replace(/\s/g,'').replace(/[^0-9,.-]/g,'').replace(/,(?=\d{1,2}$)/,'.').replace(/,/g,'');
        const num=Math.abs(Number(cleaned));return Number.isFinite(num)?num:0;
      }
      function coinKeeperCsvSections(text){
        const raw=parseFinanceCsv(text,{keepEmpty:true}),sections=[];let section=[];
        const flush=()=>{if(section.some(row=>row.some(cell=>String(cell||'').trim())))sections.push(section.filter(row=>row.some(cell=>String(cell||'').trim())));section=[]};
        for(const row of raw){
          if(row.some(cell=>String(cell||'').trim()))section.push(row);
          else flush();
        }
        flush();return sections;
      }
      function coinKeeperReferenceEntities(sections,transactionSectionIndex,parseCurrency){
        let accountsDetected=false,categoriesDetected=false;
        const currentWallets=[],currentCategories=[];
        const walletKeys=new Set(),categoryKeys=new Set();
        const findHeader=(section,matcher)=>{
          for(let i=0;i<Math.min(section.length,5);i++){
            const keys=section[i].map(financeHeaderKey);
            if(matcher(keys))return {index:i,keys};
          }
          return null;
        };
        const indexOfAlias=(keys,aliases)=>keys.findIndex(key=>aliases.some(alias=>key===alias||key.includes(alias)));
        for(let s=0;s<sections.length;s++){
          if(s===transactionSectionIndex)continue;
          const section=sections[s];
          const descriptor=section.slice(0,4).flat().map(financeHeaderKey).join(' ');
          const accountLike=/(account|wallet|счет|кошел)/i.test(descriptor);
          const expenseCategoryLike=/(expense.{0,20}categor|categor.{0,20}expense|категор.{0,20}расход|расход.{0,20}категор)/i.test(descriptor);
          if(accountLike){
            accountsDetected=true;
            const header=findHeader(section,keys=>{
              const joined=keys.join(' ');
              return /(name|назван|account|wallet|счет|кошел)/i.test(joined)&&/(balance|остат|currency|валют)/i.test(joined);
            });
            let nameI=0,balanceI=1,currencyI=2,start=1;
            if(header){
              nameI=indexOfAlias(header.keys,['name','название','account','wallet','счет','кошелек']);
              balanceI=indexOfAlias(header.keys,['balance','остаток','amount','сумма']);
              currencyI=indexOfAlias(header.keys,['currency','валюта']);
              start=header.index+1;
            }
            if(nameI<0)nameI=0;
            for(let i=start;i<section.length;i++){
              const row=section[i],name=String(row[nameI]||'').trim();
              if(!name||/(account|wallet|счет|кошел|name|назван)/i.test(financeHeaderKey(name)))continue;
              const currency=parseCurrency(currencyI>=0?row[currencyI]:'',row[balanceI]||'');
              const balance=balanceI>=0?financeParseNumber(row[balanceI]):0;
              const key=financeHeaderKey(name)+'|'+currency;
              if(walletKeys.has(key))continue;
              walletKeys.add(key);currentWallets.push({name:name.slice(0,48),currency,balance});
            }
          }
          if(expenseCategoryLike){
            categoriesDetected=true;
            const header=findHeader(section,keys=>keys.some(key=>/(category|категор|name|назван)/i.test(key)));
            let nameI=0,start=1;
            if(header){
              nameI=indexOfAlias(header.keys,['category','категория','name','название']);
              start=header.index+1;
            }
            if(nameI<0)nameI=0;
            for(let i=start;i<section.length;i++){
              const name=String(section[i][nameI]||'').trim();
              if(!name||/(expense|расход|category|категор|name|назван)/i.test(financeHeaderKey(name)))continue;
              const key=financeHeaderKey(name);if(categoryKeys.has(key))continue;
              categoryKeys.add(key);currentCategories.push(name.slice(0,48));
            }
          }
        }
        return {
          currentWallets:accountsDetected?currentWallets:undefined,
          currentCategories:categoriesDetected?currentCategories:undefined,
          accountsDetected,categoriesDetected,
        };
      }
      function coinKeeperRowsFromCsv(text){
        const sections=coinKeeperCsvSections(text);if(!sections.length)throw new Error('csv-empty');
        let transactionSectionIndex=-1,table=null,headers=null;
        for(let i=0;i<sections.length;i++){
          const candidate=sections[i],keys=candidate[0]?.map(financeHeaderKey)||[];
          if(keys.some(key=>key==='data'||key==='date'||key==='дата')&&keys.some(key=>key.includes('amount')||key.includes('сумма'))){
            transactionSectionIndex=i;table=candidate;headers=keys;break;
          }
        }
        if(!table||table.length<2)throw new Error('csv-columns');
        const find=(aliases)=>headers.findIndex(h=>aliases.some(alias=>h===alias||h.includes(alias)));
        const dateI=find(['data','date','дата']),typeI=find(['type','тип']),fromI=find(['from','откуда','счет']),toI=find(['to','куда','категор']),tagsI=find(['tags','теги']);
        const amountI=find(['amount','сумма']),noteI=find(['note','comment','комментар','замет']),currencyI=find(['currency','валюта']);
        const convertedAmountI=find(['amount converted','converted amount','сумма конверт']),conversionCurrencyI=find(['currency of conversion','conversion currency','валюта конверт']);
        if(dateI<0||amountI<0)throw new Error('csv-columns');
        const parseCurrency=(value,amountCell='')=>{
          const raw=(String(value||'')+' '+String(amountCell||'')).toUpperCase();
          if(raw.includes('USDT'))return 'USDT';
          if(raw.includes('BTC')||raw.includes('₿'))return 'BTC';
          if(raw.includes('ETH')||raw.includes('Ξ'))return 'ETH';
          if(raw.includes('USD')||raw.includes('$'))return 'USD';
          if(raw.includes('EUR')||raw.includes('€'))return 'EUR';
          if(raw.includes('RUB')||raw.includes('RUR')||raw.includes('₽')||raw.includes('РУБ'))return 'RUB';
          return 'RUB';
        };
        const refs=coinKeeperReferenceEntities(sections,transactionSectionIndex,parseCurrency);
        const result=[];let skipped=0;
        for(let index=1;index<table.length;index++){
          const row=table[index],type=String(row[typeI]||'').trim(),lower=type.toLocaleLowerCase('ru-RU');
          if(/income|доход|transfer|перевод/.test(lower)){skipped++;continue}
          const sourceAmount=financeParseNumber(row[amountI]);if(!(sourceAmount>0)){skipped++;continue}
          const date=financeParseImportedDate(row[dateI]);if(!date){skipped++;continue}
          let category=String(row[toI]||'').trim();
          if(!category)category=String(row[tagsI]||'').split(/[,;]/)[0].trim();
          if(!category)category='Без категории';
          const note=String(row[noteI]||'').trim().slice(0,120);
          const sourceCurrency=parseCurrency(row[currencyI],row[amountI]);
          const convertedAmount=convertedAmountI>=0?financeParseNumber(row[convertedAmountI]):0;
          const convertedCurrency=conversionCurrencyI>=0?parseCurrency(row[conversionCurrencyI],row[convertedAmountI]):'';
          let amount=sourceAmount;
          if(sourceCurrency!=='RUB'){
            if(convertedCurrency==='RUB'&&convertedAmount>0)amount=convertedAmount;
            else{skipped++;continue}
          }
          const exchangeRate=sourceAmount>0?Math.round((amount/sourceAmount)*100000000)/100000000:1;
          const meta=financeMoscowParts(date),month=meta.year+'-'+meta.month;
          const canonical=[row[dateI],type,row[fromI]||'',row[toI]||'',row[tagsI]||'',row[amountI],row[currencyI]||'',row[convertedAmountI]||'',row[conversionCurrencyI]||'',row[noteI]||''].join('|');
          result.push({
            categoryName:category.slice(0,48),amount,sourceAmount,sourceCurrency,currency:'RUB',
            exchangeRate,month,occurredAt:date.toISOString(),note,
            importKey:'coinkeeper:'+financeCsvHash(canonical)
          });
        }
        return {rows:result,skipped,...refs};
      }

      async function importFinanceCsvFile(file){
        const status=document.getElementById('financeTransferStatus');
        if(status)status.textContent='Читаю файл…';
        const parsed=coinKeeperRowsFromCsv(await file.text());
        if(!parsed.rows.length&&parsed.currentWallets===undefined&&parsed.currentCategories===undefined)throw new Error('csv-no-expenses');
        let imported=0,duplicates=0,skipped=parsed.skipped,created=new Set(),createdWallets=new Set(),last=null;
        const chunks=parsed.rows.length?Math.ceil(parsed.rows.length/350):1;
        for(let chunk=0;chunk<chunks;chunk++){
          const i=chunk*350;
          if(status&&parsed.rows.length)status.textContent='Импортирую '+Math.min(i+350,parsed.rows.length)+' из '+parsed.rows.length+'…';
          const payload={rows:parsed.rows.slice(i,i+350)};
          if(parsed.currentCategories!==undefined)payload.currentCategories=parsed.currentCategories;
          if(parsed.currentWallets!==undefined)payload.currentWallets=parsed.currentWallets;
          const data=await financeRequest('import-expenses',payload);
          last=data;imported+=Number(data.importResult?.imported||0);duplicates+=Number(data.importResult?.duplicates||0);skipped+=Number(data.importResult?.skipped||0);
          for(const name of data.importResult?.createdCategories||[])created.add(name);
          for(const name of data.importResult?.createdWallets||[])createdWallets.add(name);
        }
        if(last)renderFinanceState(last,{personalMonth:document.getElementById('financePersonalMonthInput')?.value||financeCurrentMonthKey(),preserveIncome:true,preservePlan:true});
        if(status)status.textContent='Готово: '+imported+' расходов · актуальных кошельков '+(parsed.currentWallets?.length??0)+' · новых категорий '+created.size+(createdWallets.size?' · новых кошельков '+createdWallets.size:'')+(duplicates?' · дублей пропущено '+duplicates:'')+(skipped?' · пропущено '+skipped:'');
        refreshFinanceInsight(true).catch(()=>{});
      }

      function financeDebtDate(value){
        const date=new Date(value||Date.now());
        if(Number.isNaN(date.getTime()))return '—';
        return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/Moscow'}).format(date);
      }
      function financeDebtWord(count){
        const n=Math.abs(Number(count)||0)%100,tail=n%10;
        if(n>=11&&n<=19)return 'долгов';
        if(tail===1)return 'долг';
        if(tail>=2&&tail<=4)return 'долга';
        return 'долгов';
      }
      function financeDebtRemaining(row){
        return Math.max(0,Number(row?.amount||0)-Number(row?.paidAmount||0));
      }
      function openFinanceDebtDetail(id){
        const row=(financeState.debts||[]).find(item=>item.id===id);if(!row)return;
        financeDebtSelectedId=row.id;
        const counterparty=document.getElementById('financeDebtDetailCounterparty');
        const type=document.getElementById('financeDebtDetailType');
        const amount=document.getElementById('financeDebtDetailAmount');
        const note=document.getElementById('financeDebtDetailNote');
        const paid=document.getElementById('financeDebtDetailPaid');
        const remaining=document.getElementById('financeDebtDetailRemaining');
        const date=document.getElementById('financeDebtDetailDate');
        const direction=document.getElementById('financeDebtDetailDirection');
        const paymentBlock=document.getElementById('financeDebtPaymentBlock');
        const paymentHistory=document.getElementById('financeDebtPaymentHistory');
        const paymentAmount=document.getElementById('financeDebtPaymentAmount');
        const status=document.getElementById('financeDebtDetailStatus');
        if(counterparty)counterparty.value=row.counterparty||'';
        if(type)type.value=row.direction||'owe';
        if(amount)amount.value=Number(row.amount||0)||'';
        if(note)note.value=row.note||'';
        if(paid)paid.textContent=financeMoney(row.paidAmount||0);
        if(remaining)remaining.textContent=financeMoney(financeDebtRemaining(row));
        if(date)date.textContent=financeDebtDate(row.createdAt);
        if(direction)direction.textContent=row.direction==='owed'?'Мне должны':'Я должен';
        if(paymentBlock)paymentBlock.hidden=Boolean(row.paid);
        if(paymentAmount)paymentAmount.value='';
        if(status)status.textContent='';
        if(paymentHistory){
          paymentHistory.replaceChildren();
          const payments=[...(Array.isArray(row.payments)?row.payments:[])].sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
          if(payments.length){
            const title=document.createElement('div');title.className='finance-debt-payment-history-title';title.textContent='История платежей';paymentHistory.append(title);
            for(const item of payments){
              const line=document.createElement('div');line.className='finance-debt-payment-history-row';
              const when=document.createElement('span');when.textContent=financeDebtDate(item.createdAt);
              const value=document.createElement('strong');value.textContent=financeMoney(item.amount);
              line.append(when,value);paymentHistory.append(line);
            }
          }
        }
        mountFinanceCoinModal(document.getElementById('financeDebtDetailComposer'),counterparty);
      }
      async function financeDebtRefreshAfter(operation,payload={}){
        const data=await financeRequest(operation,payload);
        renderFinanceState(data,{personalMonth:document.getElementById('financePersonalMonthInput')?.value||financeCurrentMonthKey(),preserveIncome:true,preservePlan:true});
        return data;
      }
      function renderFinanceDebts(){
        const list=document.getElementById('financeDebtList'),empty=document.getElementById('financeDebtEmpty');
        const history=document.getElementById('financeDebtHistory'),historyToggle=document.getElementById('financeDebtHistoryToggle');
        const oweTotal=document.getElementById('financeDebtOweTotal'),owedTotal=document.getElementById('financeDebtOwedTotal');
        if(!list)return;
        const rows=Array.isArray(financeState.debts)?financeState.debts:[];
        const active=rows.filter(row=>!row.paid),paidRows=rows.filter(row=>row.paid);
        const oweRows=active.filter(row=>row.direction==='owe'),owedRows=active.filter(row=>row.direction==='owed');
        const owe=oweRows.reduce((sum,row)=>sum+financeDebtRemaining(row),0),owed=owedRows.reduce((sum,row)=>sum+financeDebtRemaining(row),0);
        if(oweTotal)oweTotal.textContent=financeMoney(owe);if(owedTotal)owedTotal.textContent=financeMoney(owed);
        const counts={all:active.length,owe:oweRows.length,owed:owedRows.length};
        for(const [key,value] of Object.entries(counts)){
          const host=document.getElementById(key==='all'?'financeDebtFilterAllCount':key==='owe'?'financeDebtFilterOweCount':'financeDebtFilterOwedCount');
          if(host)host.textContent=String(value);
        }
        document.querySelectorAll('[data-debt-filter]').forEach(button=>button.classList.toggle('is-active',button.dataset.debtFilter===financeDebtFilter));
        const visible=active.filter(row=>financeDebtFilter==='all'||row.direction===financeDebtFilter);
        list.replaceChildren();if(empty)empty.hidden=visible.length>0;
        for(const row of visible){
          const card=document.createElement('article');card.className='finance-debt-row';card.tabIndex=0;card.setAttribute('role','button');
          const main=document.createElement('div');main.className='finance-debt-row-main';
          const title=document.createElement('strong');title.textContent=String(row.counterparty||'');
          const note=document.createElement('span');note.textContent=row.note||'Без комментария';
          const meta=document.createElement('div');meta.className='finance-debt-row-meta';
          const badge=document.createElement('span');badge.className='finance-debt-badge '+(row.direction==='owed'?'is-owed':'is-owe');badge.textContent=row.direction==='owed'?'Мне должны':'Я должен';
          const date=document.createElement('span');date.textContent=financeDebtDate(row.createdAt);
          meta.append(badge,date);main.append(title,note,meta);
          const side=document.createElement('div');side.className='finance-debt-row-side';
          const amount=document.createElement('strong');amount.textContent=financeMoney(financeDebtRemaining(row));
          const paidAmount=Number(row.paidAmount||0);
          const paidMeta=document.createElement('span');paidMeta.className='finance-debt-progress-copy';
          paidMeta.textContent=paidAmount>0?'Погашено '+financeMoney(paidAmount)+' из '+financeMoney(row.amount):'Осталось';
          const pay=document.createElement('button');pay.type='button';pay.className='finance-debt-toggle';pay.textContent='Погасить';
          pay.addEventListener('click',event=>{event.stopPropagation();openFinanceDebtDetail(row.id)});
          side.append(amount,paidMeta,pay);
          card.append(main,side);
          card.addEventListener('click',()=>openFinanceDebtDetail(row.id));
          card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openFinanceDebtDetail(row.id)}});
          list.appendChild(card);
        }
        if(historyToggle){
          historyToggle.hidden=!paidRows.length;
          historyToggle.textContent='История · '+paidRows.length;
          historyToggle.classList.toggle('is-open',financeDebtHistoryOpen);
        }
        if(history){
          history.hidden=!financeDebtHistoryOpen||!paidRows.length;
          history.replaceChildren();
          if(financeDebtHistoryOpen){
            for(const row of paidRows){
              const item=document.createElement('button');item.type='button';item.className='finance-debt-history-row';
              const copy=document.createElement('span');copy.innerHTML='<strong></strong><small></small>';
              copy.querySelector('strong').textContent=row.counterparty||'Долг';
              copy.querySelector('small').textContent=(row.direction==='owed'?'Мне должны':'Я должен')+' · '+financeDebtDate(row.updatedAt||row.createdAt);
              const value=document.createElement('strong');value.textContent=financeMoney(row.amount);
              item.append(copy,value);item.addEventListener('click',()=>openFinanceDebtDetail(row.id));history.append(item);
            }
          }
        }
        animateRudiCollection(list,'.finance-debt-row',10);
        if(history&&!history.hidden)animateRudiCollection(history,'.finance-debt-history-row',10);
      }

      function appendFinanceLiteracyInline(host,text){
        const value=String(text||'').replace(/\r/g,'');
        const bold=/\*\*([^*\n]+?)\*\*/g;
        let pos=0,match;
        while((match=bold.exec(value))){
          if(match.index>pos)host.appendChild(document.createTextNode(value.slice(pos,match.index)));
          const strong=document.createElement('strong');strong.textContent=match[1];host.appendChild(strong);
          pos=bold.lastIndex;
        }
        if(pos<value.length)host.appendChild(document.createTextNode(value.slice(pos)));
      }
      function appendFinanceLiteracyParagraph(host,text,tag='p'){
        const node=document.createElement(tag);
        appendFinanceLiteracyInline(node,text);
        host.append(node);
        return node;
      }
      function appendFinanceLiteracyListItem(host,text){
        const li=document.createElement('li'),value=String(text||'').trim();
        const firstStep=/(?:^|\s)([a-zа-я])\)\s+/i.exec(value);
        if(firstStep){
          const lead=value.slice(0,firstStep.index).trim();
          if(lead)appendFinanceLiteracyParagraph(li,lead);
          const steps=value.slice(firstStep.index).trim().split(/\s+(?=[a-zа-я]\)\s+)/i).filter(Boolean);
          const sub=document.createElement('ol');sub.className='finance-literacy-substeps';
          for(const step of steps){
            const subitem=document.createElement('li');
            appendFinanceLiteracyInline(subitem,step.replace(/^[a-zа-я]\)\s+/i,''));
            sub.append(subitem);
          }
          li.append(sub);
        }else appendFinanceLiteracyInline(li,value);
        host.append(li);
      }
      function renderFinanceLiteracy(article){
        const title=document.getElementById('financeLiteracyTitle'),body=document.getElementById('financeLiteracyBody'),source=document.getElementById('financeLiteracySource'),status=document.getElementById('financeLiteracyStatus');
        if(!article||!body)return;
        if(title)title.textContent=String(article.title||'Финансовая грамотность');
        body.replaceChildren();
        const raw=String(article.body||'').replace(/\r\n?/g,'\n').trim();
        const chunks=raw.split(/\n{2,}/).flatMap(block=>block.split(/\n(?=\s*\d+[.)]\s+)/)).map(text=>text.trim()).filter(Boolean);
        let lastList=null,lastListType='',hasLead=false;
        for(const text of chunks){
          const lines=text.split(/\n/).map(line=>line.trim()).filter(Boolean);
          const numbered=/^\d+[.)]\s+/.test(text);
          const bullets=lines.length>0&&lines.every(line=>/^[-•*—]\s+/.test(line));
          const numberedLines=lines.length>1&&lines.every(line=>/^\d+[.)]\s+/.test(line));
          if(numbered||numberedLines||bullets){
            const kind=bullets?'ul':'ol';
            if(!lastList||lastListType!==kind){
              lastList=document.createElement(kind);body.append(lastList);lastListType=kind;
            }
            for(const line of (numberedLines||bullets?lines:[text])){
              appendFinanceLiteracyListItem(lastList,line.replace(kind==='ol'?/^\d+[.)]\s+/:/^[-•*—]\s+/,''));
            }
            continue;
          }
          lastList=null;lastListType='';
          const headingText=text.replace(/^#{1,4}\s*/,'').trim();
          const headingCandidate=/^#{1,4}\s+/.test(text)||(lines.length===1&&text.length<=72&&!/[.!?]$/.test(text)&&hasLead);
          if(headingCandidate){appendFinanceLiteracyParagraph(body,headingText,'h3');continue;}
          const node=appendFinanceLiteracyParagraph(body,text);
          if(!hasLead){node.classList.add('finance-literacy-lead');hasLead=true;}
        }
        const books=(Array.isArray(article.books)?article.books:[]).filter(Boolean);
        if(source){source.hidden=!books.length;source.textContent=books.length?'Идеи по мотивам: '+books.join(' · '):''}
        if(status)status.textContent='';
      }
            async function loadFinanceLiteracy({force=false}={}){
        if(financeLiteracyPromise&&!force)return financeLiteracyPromise;
        const status=document.getElementById('financeLiteracyStatus');if(status)status.textContent='Готовлю статью…';
        financeLiteracyPromise=financeRequest('literacy').then(data=>{renderFinanceLiteracy(data.article);return data.article}).catch(error=>{if(status)status.textContent='Сегодняшнюю статью пока не удалось загрузить';throw error}).finally(()=>{financeLiteracyPromise=null});
        return financeLiteracyPromise;
      }
      async function refreshFinanceInsight(force=false){
        const host=document.getElementById('financeAiInsightText');if(!host||!currentActor)return;
        const month=document.getElementById('financePersonalMonthInput')?.value||financeCurrentMonthKey();
        const key=month+':'+String(financeState.version||0);if(!force&&financeInsightKey===key)return;
        financeInsightKey=key;host.textContent='Анализирую месяц…';
        try{const data=await financeRequest('monthly-insight',{month});host.textContent=String(data?.insight?.text||'').trim()||'Добавь доход и расходы по категориям.'}
        catch(_){host.textContent='Добавь доход и расходы по категориям, чтобы получить короткий ИИ-разбор месяца.'}
      }
      function renderFinancialAnalyst(report){
        const host=document.getElementById('financeAnalystResult');if(!host||!report)return;
        host.replaceChildren();
        const summary=document.createElement('p');summary.className='finance-analyst-summary';summary.textContent=String(report.summary||'');
        host.append(summary);
        const groups=[
          ['Сильные стороны',Array.isArray(report.strengths)?report.strengths:[],'strengths'],
          ['Риски',Array.isArray(report.risks)?report.risks:[],'risks']
        ];
        for(const [title,items,tone] of groups){
          if(!items.length)continue;
          const section=document.createElement('section');section.className='finance-analyst-group is-'+tone;
          const h=document.createElement('h3');h.textContent=title;
          const list=document.createElement('ol');if(tone!=='actions')list.className='is-bullets';
          for(const text of items){const li=document.createElement('li');li.textContent=String(text||'');list.append(li)}
          section.append(h,list);host.append(section);
        }
        host.hidden=false;
      }
      function financeTodayKey(){
        const p=financeMoscowParts();return p.year+'-'+p.month+'-'+p.day;
      }
      function syncFinanceAnalystDailyState(){
        const button=document.getElementById('financeAnalystButton'),status=document.getElementById('financeAnalystStatus');
        const used=financeState.plan?.analystLastDate===financeTodayKey()&&Boolean(financeState.plan?.analystLastReport?.summary);
        if(used){
          if(button){button.disabled=true;button.textContent='Анализ за сегодня готов'}
          renderFinancialAnalyst(financeState.plan.analystLastReport);
          if(status)status.textContent='Следующий анализ будет доступен завтра';
        }else{
          if(button){button.disabled=false;button.textContent='Получить анализ'}
          if(status?.textContent==='Следующий анализ будет доступен завтра')status.textContent='';
        }
      }
      async function runFinancialAnalyst(){
        const button=document.getElementById('financeAnalystButton'),status=document.getElementById('financeAnalystStatus');
        const month=document.getElementById('financePersonalMonthInput')?.value||financeCurrentMonthKey();
        if(financeState.plan?.analystLastDate===financeTodayKey()&&financeState.plan?.analystLastReport?.summary){syncFinanceAnalystDailyState();return}
        if(button){button.disabled=true;button.textContent='Анализирую…'}
        if(status)status.textContent='Сопоставляю доходы, расходы и долги…';
        try{
          const data=await financeRequest('analyst',{month});
          financeState.plan={...(financeState.plan||{}),analystLastDate:data.analystDate||financeTodayKey(),analystLastReport:data.report};
          renderFinancialAnalyst(data.report);
          syncFinanceAnalystDailyState();
          try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
        }catch(_){
          if(status)status.textContent='Не удалось получить анализ. Попробуй ещё раз.';
          if(button){button.disabled=false;button.textContent='Получить анализ'}
        }
      }

      function setFinanceCardCollapsed(cardId,buttonId,collapsed){
        const card=document.getElementById(cardId),button=document.getElementById(buttonId);
        if(!card||!button)return;
        const next=Boolean(collapsed);
        card.classList.toggle('is-collapsed',next);
        button.setAttribute('aria-expanded',next?'false':'true');
        button.setAttribute('aria-label',next?'Развернуть блок':'Свернуть блок');
        card.querySelector('#financePlanningTitle[role="button"]')?.setAttribute('aria-expanded',next?'false':'true');
      }
      function bindFinanceCardCollapse(cardId,buttonId){
        const card=document.getElementById(cardId),button=document.getElementById(buttonId);
        if(!card||!button||button.dataset.bound==='1')return;
        button.dataset.bound='1';
        const details=card.querySelector('#financeObligationsDetails');
        if(details){
          const sync=()=>{
            const collapsed=!details.open;
            card.classList.toggle('is-collapsed',collapsed);
            button.setAttribute('aria-expanded',String(!collapsed));
            button.setAttribute('aria-label',collapsed?'Развернуть ежемесячные расходы':'Свернуть ежемесячные расходы');
          };
          button.addEventListener('click',event=>{
            event.preventDefault();
            event.stopPropagation();
            details.open=!details.open;
            sync();
          });
          details.addEventListener('toggle',sync);
          sync();
          return;
        }
        setFinanceCardCollapsed(cardId,buttonId,card.classList.contains('is-collapsed'));
        button.addEventListener('click',()=>{
          setFinanceCardCollapsed(cardId,buttonId,!card.classList.contains('is-collapsed'));
          try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
        });
        if(cardId==='financeGoalCard'){
          const title=card.querySelector('#financePlanningTitle');
          if(title){
            title.setAttribute('role','button');
            title.tabIndex=0;
            title.setAttribute('aria-controls',cardId);
            title.setAttribute('aria-expanded',button.getAttribute('aria-expanded'));
            title.addEventListener('click',()=>button.click());
            title.addEventListener('keydown',event=>{
              if(event.key!=='Enter'&&event.key!==' ')return;
              event.preventDefault();
              button.click();
            });
          }
        }
      }

