      function setProfileWorkStatus(person,text,state='neutral'){
        const node=profileStatusElement(person);
        if(!node) return;
        node.textContent=String(text||'');
        node.classList.toggle('is-working',state==='working');
        node.classList.toggle('is-off',state==='off');
        node.classList.toggle('is-neutral',state!=='working'&&state!=='off');
        node.hidden=!String(text||'').trim();
      }

      function dianaCycleStatus(modelOrPhase){
        const model=modelOrPhase&&typeof modelOrPhase==='object'
          ?modelOrPhase
          :{phase:String(modelOrPhase||'')};
        const phase=String(model.phase||'');
        const day=Number(model.cycleDay);
        const periodLength=Math.max(1,Number(model.periodLength)||5);
        const ovulationDay=Number(model.ovulationDay);
        const daysToNext=Number(model.daysToNext);
        const periodActive=Boolean(model.periodActive);

        const makeStatus=(label,advice)=>({
          label,
          advice:advice||'Ориентируйтесь на своё самочувствие и выбирайте комфортный для себя темп дня.'
        });

        if(phase==='Месячные'){
          return makeStatus(
            'Месячные',
            'Если чувствуете усталость, снизьте нагрузку и оставьте больше времени на отдых.'
          );
        }

        if(!periodActive&&Number.isFinite(daysToNext)&&daysToNext===0){
          return makeStatus(
            'Ожидаются сегодня',
            'Сегодня предполагаемая дата начала месячных. Если они начнутся, отметьте это в календаре.'
          );
        }

        if(!periodActive&&Number.isFinite(daysToNext)&&daysToNext<0){
          return makeStatus(
            'Прогнозная дата прошла',
            'Прогнозная дата прошла, но начало месячных пока не отмечено. Отметьте его, когда они начнутся.'
          );
        }

        if(phase==='Фолликулярная фаза'){
          if(Number.isFinite(day)&&day<=periodLength+2){
            return makeStatus(
              'Восстановление',
              'После месячных возвращайтесь к привычному темпу постепенно и ориентируйтесь на своё самочувствие.'
            );
          }
          return makeStatus(
            'Энергии больше',
            'Если чувствуете прилив сил, можете запланировать важные дела, прогулки и встречи.'
          );
        }

        if(phase==='Фертильное окно'){
          if(Number.isFinite(day)&&Number.isFinite(ovulationDay)&&day===ovulationDay){
            return makeStatus(
              'Овуляция',
              'Сегодня по прогнозу возможна овуляция. Прислушивайтесь к самочувствию: календарный прогноз приблизителен.'
            );
          }
          return makeStatus(
            'Фертильные дни',
            'Сейчас по календарю у вас могут быть фертильные дни. Даты приблизительны: этот прогноз нельзя использовать для контрацепции.'
          );
        }

        if(phase==='Лютеиновая фаза'){
          if(Number.isFinite(daysToNext)&&daysToNext<=5){
            return makeStatus(
              'Скоро месячные',
              'До ожидаемых месячных осталось немного времени. Оставьте запас сил и учитывайте, как меняется ваше самочувствие.'
            );
          }
          return makeStatus(
            'Восстановление',
            'Старайтесь сохранять ровный темп и не перегружать себя.'
          );
        }

        return {label:'',advice:''};
      }

      function dianaCycleMoodWord(modelOrPhase){
        return dianaCycleStatus(modelOrPhase).label;
      }

      function dianaCycleProfileStatus(modelOrPhase){
        const model=modelOrPhase&&typeof modelOrPhase==='object'?modelOrPhase:null;
        const periodEndUtc=Number.isFinite(model?.periodEnd)?Number(model.periodEnd):parseCycleDate(model?.periodEnd);
        if(model?.periodActive&&Number.isFinite(periodEndUtc)){
          return 'Месячные до '+cycleDateLabel(periodEndUtc+DAY);
        }
        return dianaCycleMoodWord(modelOrPhase);
      }

      function dianaCycleDailyAdvice(modelOrPhase){
        return dianaCycleStatus(modelOrPhase).advice;
      }

      function dianaCycleBrainNote(modelOrPhase){
        const model=modelOrPhase&&typeof modelOrPhase==='object'?modelOrPhase:{phase:String(modelOrPhase||'')};
        const phase=String(model.phase||'');
        const day=Number(model.cycleDay);
        const periodDay=Number(model.periodDay);
        const periodLength=Math.max(1,Number(model.periodLength)||5);
        const ovulationDay=Number(model.ovulationDay);
        const daysToNext=Number(model.daysToNext);

        if(phase==='Месячные'){
          if(Number.isFinite(periodDay)&&periodDay<=2){
            return '🧠 Мозг: в первые 1–2 дня месячных вы можете сильнее ощущать усталость, боль или снижение концентрации. Делайте короткие задачи и чаще отдыхайте.';
          }
          return '🧠 Мозг: ближе к окончанию месячных вам может становиться легче сосредоточиться. Наращивайте нагрузку постепенно, если чувствуете себя хорошо.';
        }

        if(phase==='Фолликулярная фаза'){
          if(Number.isFinite(day)&&day<=periodLength+2){
            return '🧠 Мозг: сейчас вы можете постепенно ощущать больше энергии и мотивации, хотя восстановление ещё продолжается. Не требуйте от себя максимума.';
          }
          if(Number.isFinite(day)&&Number.isFinite(ovulationDay)&&day<=ovulationDay-4){
            return '🧠 Мозг: в этот период вам может быть проще сосредоточиться, учиться и начинать новые задачи. Планируйте их с учётом своего самочувствия.';
          }
          return '🧠 Мозг: ближе к фертильным дням у вас могут повыситься энергия и желание общаться. Если чувствуете себя хорошо, используйте это время для встреч и важных дел.';
        }

        if(phase==='Фертильное окно'){
          if(Number.isFinite(day)&&Number.isFinite(ovulationDay)&&day===ovulationDay){
            return '🧠 Мозг: сегодня по прогнозу овуляция. Вы можете чувствовать больше энергии, но также возможны усталость или дискомфорт. Всё индивидуально.';
          }
          return '🧠 Мозг: в фертильные дни вам могут легче даваться общение и активные задачи. Это не гарантировано, поэтому ориентируйтесь прежде всего на свои ощущения.';
        }

        if(phase==='Лютеиновая фаза'){
          if(Number.isFinite(daysToNext)&&daysToNext<=2){
            return '🧠 Мозг: за 1–2 дня до месячных вы можете быстрее уставать или раздражаться. Оставьте запас времени и уменьшите количество переключений.';
          }
          if(Number.isFinite(daysToNext)&&daysToNext<=5){
            return '🧠 Мозг: перед месячными у вас может усилиться чувствительность к стрессу. Разбивайте сложные дела на небольшие этапы.';
          }
          if(Number.isFinite(daysToNext)&&daysToNext<=10){
            return '🧠 Мозг: в середине этой фазы вам может потребоваться больше сна и восстановления. Старайтесь поддерживать комфортный ритм.';
          }
          return '🧠 Мозг: после овуляции вы можете ощущать сонливость или более спокойный темп. Сейчас удобнее выполнять последовательные, привычные задачи.';
        }
        return '';
      }

      function dianaCycleAppetiteNote(modelOrPhase){
        const model=modelOrPhase&&typeof modelOrPhase==='object'?modelOrPhase:{phase:String(modelOrPhase||'')};
        const phase=String(model.phase||'');
        const day=Number(model.cycleDay);
        const periodDay=Number(model.periodDay);
        const periodLength=Math.max(1,Number(model.periodLength)||5);
        const ovulationDay=Number(model.ovulationDay);
        const daysToNext=Number(model.daysToNext);

        if(phase==='Месячные'){
          if(Number.isFinite(periodDay)&&periodDay<=2){
            return '🍽 Аппетит: в первые дни месячных у вас может меняться чувство голода и желание сладкого. Ешьте так, чтобы вам было комфортно.';
          }
          return '🍽 Аппетит: к концу месячных вы можете заметить, что тяга к перекусам ослабевает. Ориентируйтесь на свой голод.';
        }

        if(phase==='Фолликулярная фаза'){
          if(Number.isFinite(day)&&day<=periodLength+2){
            return '🍽 Аппетит: после месячных вам может быть проще придерживаться обычного режима питания. Не забывайте о регулярных приёмах пищи.';
          }
          if(Number.isFinite(day)&&Number.isFinite(ovulationDay)&&day<=ovulationDay-4){
            return '🍽 Аппетит: в середине этой фазы у вас может быть более ровный аппетит. Лучше ориентироваться на чувство голода, а не на календарь.';
          }
          return '🍽 Аппетит: ближе к овуляции вы можете замечать меньший голод. Даже если есть хочется меньше, старайтесь питаться регулярно.';
        }

        if(phase==='Фертильное окно'){
          if(Number.isFinite(day)&&Number.isFinite(ovulationDay)&&day===ovulationDay){
            return '🍽 Аппетит: около овуляции у вас может уменьшиться аппетит, но он также может остаться прежним. Ориентируйтесь на свои потребности.';
          }
          return '🍽 Аппетит: сейчас у вас может быть привычный или чуть меньший аппетит. После овуляции он иногда постепенно усиливается.';
        }

        if(phase==='Лютеиновая фаза'){
          if(Number.isFinite(daysToNext)&&daysToNext<=2){
            return '🍽 Аппетит: за 1–2 дня до месячных у вас может усилиться тяга к сладкому или сытной пище. Это возможно, но необязательно.';
          }
          if(Number.isFinite(daysToNext)&&daysToNext<=5){
            return '🍽 Аппетит: перед месячными вам может чаще хотеться перекусов. Попробуйте более сытные регулярные приёмы пищи.';
          }
          if(Number.isFinite(daysToNext)&&daysToNext<=10){
            return '🍽 Аппетит: в середине этой фазы вы можете замечать, что голод усиливается и хочется больше углеводной еды.';
          }
          return '🍽 Аппетит: после овуляции вы можете постепенно ощущать больше голода. Если ближе к месячным хочется сладкого, это тоже бывает.';
        }
        return '';
      }

      let dianaRhythmCycleModel=null;

      function setDianaCycleMood(modelOrPhase){
        dianaRhythmCycleModel=modelOrPhase&&typeof modelOrPhase==='object'?modelOrPhase:null;
        const node=document.getElementById('dianaCycleMood');
        if(node){
          const word=dianaCycleProfileStatus(modelOrPhase);
          node.textContent=word;
          node.hidden=!word;
          node.title=word?'Ориентировочный статус по календарю цикла':'';
        }
        syncDianaRhythmStatus(new Date(),dianaRhythmCycleModel);
      }

      function dianaRhythmBaseStatus(now=new Date()){
        const parts=Object.fromEntries(
          new Intl.DateTimeFormat('en-GB',{
            timeZone:TZ,
            hour:'2-digit',
            minute:'2-digit',
            hourCycle:'h23'
          }).formatToParts(now).filter(part=>part.type!=='literal').map(part=>[part.type,part.value])
        );
        const minutes=(Number(parts.hour)||0)*60+(Number(parts.minute)||0);
        if(minutes<8*60||minutes>=22*60) return 'Сон';
        if(minutes<9*60) return 'Старт';
        if(minutes<11*60) return 'Разгон';
        if(minutes<13*60+30) return 'Движ';
        if(minutes<14*60) return 'Пауза';
        if(minutes<17*60) return 'Пик';
        if(minutes<18*60) return 'Темп';
        if(minutes<18*60+30) return 'Спад';
        if(minutes<20*60) return 'Выдох';
        if(minutes<21*60+30) return 'Чилл';
        return 'Тише';
      }

      function dianaRhythmCycleAdjustment(model){
        if(!model||typeof model!=='object') return 'normal';
        const phase=String(model.phase||'');
        const cycleDay=Number(model.cycleDay);
        const periodLength=Math.max(1,Number(model.periodLength)||5);
        const daysToNext=Number(model.daysToNext);
        if(Boolean(model.periodActive)||phase==='Месячные') return 'gentle';
        if(phase==='Лютеиновая фаза'&&Number.isFinite(daysToNext)&&daysToNext>=0&&daysToNext<=5) return 'softer';
        if(phase==='Фолликулярная фаза'&&Number.isFinite(cycleDay)&&cycleDay>0&&cycleDay<=periodLength+2) return 'softer';
        return 'normal';
      }

      function dianaRhythmStatus(now=new Date(),model=dianaRhythmCycleModel){
        const base=dianaRhythmBaseStatus(now);
        const adjustment=dianaRhythmCycleAdjustment(model);
        const activeStates=['Разгон','Движ','Пик','Темп'];
        if(adjustment==='gentle'&&activeStates.includes(base)) return base+' · бережно';
        if(adjustment==='softer'&&activeStates.includes(base)) return base+' · мягче';
        return base;
      }

      function dianaRhythmRecommendation(now=new Date(),model=dianaRhythmCycleModel){
        const base=dianaRhythmBaseStatus(now);
        const adjustment=dianaRhythmCycleAdjustment(model);
        const regular={
          'Старт':'спокойно проснуться, позавтракать и войти в день',
          'Разгон':'делать обычные дела без максимальной нагрузки',
          'Движ':'подходящее окно для прогулки или физической активности',
          'Пауза':'поесть и дать себе около 30 минут на восстановление',
          'Пик':'лучшее окно для сложной работы и концентрации',
          'Темп':'закончить важные дела, не набирая лишнюю нагрузку',
          'Спад':'сделать перерыв и постепенно снижать темп',
          'Выдох':'оставить спокойные дела и переключиться на отдых',
          'Чилл':'отдыхать и не ставить сложные задачи',
          'Тише':'приглушить темп и готовиться ко сну',
          'Сон':'спать и восстанавливаться'
        }[base]||'';
        if(adjustment==='gentle'&&['Разгон','Движ','Пик','Темп'].includes(base)){
          if(base==='Пик') return 'это лучшее окно дня по её ритму, но во время месячных лучше выбрать одну важную задачу без перегруза';
          if(base==='Движ') return 'активность подходит по времени, но лучше оставить её лёгкой и ориентироваться на самочувствие';
          return regular+', но сегодня лучше оставить больше запаса по нагрузке';
        }
        if(adjustment==='softer'&&['Разгон','Движ','Пик','Темп'].includes(base)){
          return regular+', но лучше держать темп немного мягче обычного';
        }
        return regular;
      }

      function syncDianaRhythmStatus(now=new Date(),model=dianaRhythmCycleModel){
        const node=document.getElementById('dianaRhythmStatus');
        if(!node) return;
        const status=dianaRhythmStatus(now,model);
        node.textContent=status;
        node.hidden=!status;
        renderProfileEnergy('Диана',now);
        const recommendation=dianaRhythmRecommendation(now,model);
        node.title=recommendation?'Лучше сейчас: '+recommendation:'';
        const advice=document.getElementById('dianaRhythmAdvice');
        if(advice){
          advice.textContent=recommendation?'Лучше сейчас: '+recommendation:'';
          advice.hidden=!recommendation;
        }
      }

      function rustamWorkState(now=new Date()){
        const parts=Object.fromEntries(
          new Intl.DateTimeFormat('en-GB',{
            timeZone:TZ,
            weekday:'short',
            hour:'2-digit',
            minute:'2-digit',
            hourCycle:'h23'
          }).formatToParts(now).filter(part=>part.type!=='literal').map(part=>[part.type,part.value])
        );
        const workday=['Mon','Tue','Wed','Thu','Fri'].includes(String(parts.weekday||''));
        const minutes=(Number(parts.hour)||0)*60+(Number(parts.minute)||0);
        return workday&&minutes>=10*60&&minutes<18*60;
      }

      function rustamRhythmStatus(now=new Date()){
        const parts=Object.fromEntries(
          new Intl.DateTimeFormat('en-GB',{
            timeZone:TZ,
            hour:'2-digit',
            minute:'2-digit',
            hourCycle:'h23'
          }).formatToParts(now).filter(part=>part.type!=='literal').map(part=>[part.type,part.value])
        );
        const minutes=(Number(parts.hour)||0)*60+(Number(parts.minute)||0);
        if(minutes<6*60+30||minutes>=23*60) return 'Сон';
        if(minutes<7*60) return 'Старт';
        if(minutes<8*60) return 'Разгон';
        if(minutes<11*60+30) return 'Пик';
        if(minutes<12*60+30) return 'Пауза';
        if(minutes<15*60) return 'Темп';
        if(minutes<16*60) return 'Спад';
        if(minutes<18*60) return 'Движ';
        if(minutes<20*60) return 'Выдох';
        if(minutes<22*60+30) return 'Чилл';
        return 'Тише';
      }

      function rustamRhythmRecommendation(status){
        return {
          'Старт':'проснуться: свет, вода и немного движения',
          'Разгон':'позавтракать, пройтись и наметить главное',
          'Пик':'делать самую сложную работу и принимать решения',
          'Пауза':'поесть, пройтись и немного отвлечься',
          'Темп':'заниматься текущими задачами, встречами и ответами',
          'Спад':'переключиться на простые дела и сделать перерыв',
          'Движ':'тренироваться, гулять или решать дела вне дома',
          'Выдох':'поужинать, отдохнуть и пообщаться',
          'Чилл':'заниматься спокойными делами, читать или смотреть кино',
          'Тише':'приглушить свет, убрать сложную работу и готовиться ко сну',
          'Сон':'спать и восстанавливаться'
        }[String(status||'')]||'';
      }


      /* RUDI v4.104: illustrative daily energy curve based on existing rhythm statuses. */
      const PROFILE_ENERGY_VALUES=Object.freeze({
        'Сон':9,'Старт':25,'Разгон':52,'Пик':91,'Пауза':39,'Темп':69,
        'Спад':37,'Движ':76,'Выдох':34,'Чилл':21,'Тише':13
      });
      const profileEnergyCache=new Map();
      function profileEnergyScore(status){
        const label=String(status||'Сон').split(' · ')[0];
        let value=PROFILE_ENERGY_VALUES[label]??35;
        if(String(status).includes(' · бережно')&&['Разгон','Пик','Темп','Движ'].includes(label))value-=17;
        else if(String(status).includes(' · мягче')&&['Разгон','Пик','Темп','Движ'].includes(label))value-=9;
        return Math.max(6,Math.min(96,value));
      }
      function profileEnergyColor(value){
        const score=Number(value)||0;
        return score>=78?'#f6cb70':score>=47?'#55d8a6':'#8996ce';
      }
      function profileEnergyCurve(actor,now=new Date(),cycleModel=dianaRhythmCycleModel){
        const parts=getMoscowParts(now);
        const day=[parts.year,parts.month,parts.day].join('-');
        const adjustment=actor==='Диана'?dianaRhythmCycleAdjustment(cycleModel):'normal';
        const key=day+':'+adjustment;
        const cached=profileEnergyCache.get(actor);
        if(cached?.key===key)return cached;
        // Europe/Moscow uses UTC+3; generate date objects for the same Moscow day.
        const dayStart=Date.UTC(parts.year,parts.month-1,parts.day,-3,0);
        const raw=Array.from({length:97},(_,index)=>{
          const at=new Date(dayStart+index*15*60000);
          const status=actor==='Диана'?dianaRhythmStatus(at,cycleModel):rustamRhythmStatus(at);
          return profileEnergyScore(status);
        });
        // Weighted moving average softens discrete transitions without changing their timing.
        const scores=raw.map((_,index)=>{
          const weights=[1,2,3,2,1];
          let sum=0,total=0;
          for(let shift=-2;shift<=2;shift++){
            const target=Math.max(0,Math.min(raw.length-1,index+shift));
            sum+=raw[target]*weights[shift+2];
            total+=weights[shift+2];
          }
          return sum/total;
        });
        const points=scores.map((score,index)=>({
          x:Number((index*640/96).toFixed(2)),
          y:Number((35-score*.255).toFixed(2)),
          score
        }));
        let path='M '+points[0].x+' '+points[0].y;
        for(let index=1;index<points.length-1;index++){
          const at=points[index],next=points[index+1];
          path+=' Q '+at.x+' '+at.y+' '+((at.x+next.x)/2).toFixed(2)+' '+((at.y+next.y)/2).toFixed(2);
        }
        const last=points[points.length-1];
        path+=' L '+last.x+' '+last.y;
        const stops=Array.from({length:25},(_,index)=>{
          const sampled=scores[index*4];
          return '<stop offset="'+(index*100/24).toFixed(3)+'%" stop-color="'+profileEnergyColor(sampled)+'"/>';
        }).join('');
        const model={key,points,path,stops};
        profileEnergyCache.set(actor,model);
        return model;
      }
      function renderProfileEnergy(actor,now=new Date()){
        const card=document.getElementById(actor==='Диана'?'homeDianaTile':'homeRustamTile');
        const strip=card?.querySelector('.profile-energy-strip');
        if(!strip)return;
        const model=profileEnergyCurve(actor,now,dianaRhythmCycleModel);
        const svg=strip.querySelector('.profile-energy-svg');
        if(svg&&strip.dataset.energyCurveKey!==model.key){
          const id=actor==='Диана'?'rudi-energy-diana':'rudi-energy-rustam';
          svg.innerHTML='<defs><linearGradient id="'+id+'" x1="0" y1="0" x2="1" y2="0">'+model.stops+'</linearGradient></defs>'+
            '<path class="profile-energy-base" d="'+model.path+'"/>'+
            '<path class="profile-energy-glow" d="'+model.path+'" stroke="url(#'+id+')"/>'+
            '<path class="profile-energy-path" d="'+model.path+'" stroke="url(#'+id+')"/>';
          strip.dataset.energyCurveKey=model.key;
        }
        const parts=new Intl.DateTimeFormat('en-GB',{timeZone:TZ,hour:'2-digit',minute:'2-digit',hourCycle:'h23'})
          .formatToParts(now);
        const clock=Object.fromEntries(parts.filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
        const minutes=Math.min(1440,Math.max(0,(clock.hour||0)*60+(clock.minute||0)));
        const position=minutes/15;
        const index=Math.floor(position);
        const a=model.points[Math.min(96,index)],b=model.points[Math.min(96,index+1)];
        const fraction=position-index;
        const y=a.y+(b.y-a.y)*fraction;
        const score=a.score+(b.score-a.score)*fraction;
        const marker=strip.querySelector('.profile-energy-now');
        if(marker){
          marker.style.left=(minutes/1440*100)+'%';
          marker.style.top=(y/40*100)+'%';
          marker.style.setProperty('--profile-energy-current',profileEnergyColor(score));
        }
        const phase=actor==='Диана'?dianaRhythmStatus(now,dianaRhythmCycleModel):rustamRhythmStatus(now);
        const label=strip.querySelector('.profile-energy-phase');
        if(label)label.textContent=phase;
        strip.setAttribute('aria-label',actor+': ориентировочная энергия по распорядку на сутки. Сейчас: '+phase);
      }

