      function setupSettingsPanel(){
        const button=document.getElementById('homeSettingsButton');
        const panel=document.getElementById('homeSettingsPanel');
        const back=document.getElementById('settingsPageBack');
        if(!button||!panel) return;

        if(button.dataset.bound!=='1'){
          button.dataset.bound='1';
          button.addEventListener('click',event=>{
            event.preventDefault();
            event.stopPropagation();
            setSettingsOpen(true);
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
          });
        }

        if(back&&back.dataset.bound!=='1'){
          back.dataset.bound='1';
          back.addEventListener('click',()=>{
            navigateToAppTab('home',{scroll:true});
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
          });
        }

        const pwa=document.getElementById('settingsPwaInstall');
        if(pwa&&pwa.dataset.bound!=='1'){
          pwa.dataset.bound='1';
          pwa.addEventListener('click',installPwa);
        }
        const face=document.getElementById('settingsFaceIdConnect');
        if(face&&face.dataset.bound!=='1'){
          face.dataset.bound='1';
          face.addEventListener('click',connectFaceIdFromSettings);
        }
        if(document.documentElement.dataset.settingsEscapeBound!=='1'){
          document.documentElement.dataset.settingsEscapeBound='1';
          document.addEventListener('keydown',event=>{
            if(event.key==='Escape'&&currentAppTab==='settings') navigateToAppTab('home',{scroll:true});
          });
        }
        refreshSettingsPageUi();
      }

      function hideUndoSnackbar(){
        clearTimeout(undoSnackbarTimer);
        undoSnackbarTimer=0;
        undoSnackbarAction=null;
        const bar=document.getElementById('undoSnackbar');
        if(!bar) return;
        bar.classList.remove('is-open');
        setTimeout(()=>{if(!bar.classList.contains('is-open')) bar.hidden=true},190);
      }

      function showUndoSnackbar(text,undo,duration=6000){
        const bar=document.getElementById('undoSnackbar');
        const copy=document.getElementById('undoSnackbarText');
        if(!bar||typeof undo!=='function') return;
        clearTimeout(undoSnackbarTimer);
        undoSnackbarAction=undo;
        if(copy) copy.textContent=String(text||'Удалено');
        bar.hidden=false;
        requestAnimationFrame(()=>bar.classList.add('is-open'));
        const timeout=Math.max(1000,Math.min(12000,Number(duration)||6000));
        undoSnackbarTimer=setTimeout(hideUndoSnackbar,timeout);
      }

      function setupUndoSnackbar(){
        const button=document.getElementById('undoSnackbarButton');
        if(!button||button.dataset.bound==='1') return;
        button.dataset.bound='1';
        button.addEventListener('click',async()=>{
          const action=undoSnackbarAction;
          if(typeof action!=='function') return;
          button.disabled=true;
          clearTimeout(undoSnackbarTimer);
          let succeeded=false;
          try{
            await action();
            succeeded=true;
            try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
          }catch(error){
            console.warn('RUDI_UNDO_RETRY_AVAILABLE',String(error?.message||error));
            const copy=document.getElementById('undoSnackbarText');
            if(copy)copy.textContent='Не удалось отменить. Попробовать ещё раз';
            clearTimeout(undoSnackbarTimer);
            undoSnackbarTimer=setTimeout(hideUndoSnackbar,10000);
            try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
          }finally{
            button.disabled=false;
            if(succeeded)hideUndoSnackbar();
          }
        });
      }

      const ACTIVITY_NOTIFICATION_TYPES=new Set([
        'mood','partner-message','daily-question','wishlist','lulu-walk',
        'task-complete','checklist-complete','fasting-stop','like','photo','calendar'
      ]);
      function activityNotificationItem(item){
        const type=String(item?.type||'');
        const actor=String(item?.actor||'').trim();
        const visibleTo=String(item?.visibleTo||'').trim();
        const partnerActor=currentActor==='Диана'?'Рустам':'Диана';
        if(type==='reward-unlock'&&visibleTo===currentActor) return true;
        if(type==='photo'||type==='calendar') return true;
        return actor===partnerActor&&ACTIVITY_NOTIFICATION_TYPES.has(type);
      }
      function activityItemIsRead(item){
        const id=String(item?.id||'').trim();
        return !id||currentActivityReadIds().includes(id);
      }
      function activityNotificationItems(items=homeDashboardState.activity){
        return (Array.isArray(items)?items:[]).filter(activityNotificationItem);
      }
      function activityUnreadItems(items=homeDashboardState.activity){
        const read=new Set(currentActivityReadIds());
        return activityNotificationItems(items).filter(item=>!read.has(String(item?.id||'')));
      }
      function activityNotificationsHaveUnread(){return activityUnreadItems().length>0}
      function updateActivityNotificationBadge(){
        const unread=activityUnreadItems();
        const dot=document.getElementById('homeActivityNotificationDot');
        if(dot) dot.hidden=unread.length===0;
        const markAll=document.getElementById('homeActivityMarkAllButton');
        if(markAll) markAll.hidden=activityPanelMode!=='notifications'||unread.length===0;
        queueAppIconBadgeSync();
      }
      function markActivityItemsRead(items,{render=true}={}){
        const ids=(Array.isArray(items)?items:[items]).map(item=>String(item?.id||'').trim()).filter(Boolean);
        if(!ids.length){updateActivityNotificationBadge();return false}
        const previous=currentActivityReadIds();
        const next=mergeActivityReadIds(ids,previous);
        const changed=next.length!==previous.length||next.some((id,index)=>id!==previous[index]);
        if(changed){
          storeActivityReadIds(next);
          markUiPreferencesChanged({activityReadIds:next});
          flushUiPreferencesToServer().catch(()=>{});
        }
        if(render) renderActivityJournalItems(homeDashboardState.activity);
        updateActivityNotificationBadge();
        return changed;
      }
      function markActivityNotificationsSeen(){return markActivityItemsRead(activityNotificationItems())}

      let activityNotificationsCloseTimer=null;

      function activityFixedContainingBlockTop(panel){
        let node=panel?.parentElement||null;
        while(node&&node!==document.body&&node!==document.documentElement){
          try{
            const style=getComputedStyle(node);
            const createsFixedBlock=
              style.transform!=='none'||
              style.perspective!=='none'||
              style.filter!=='none'||
              style.backdropFilter!=='none'||
              style.webkitBackdropFilter!=='none'||
              String(style.contain||'').includes('paint');
            if(createsFixedBlock) return node.getBoundingClientRect().top||0;
          }catch(_){}
          node=node.parentElement;
        }
        return 0;
      }

      function positionActivityNotificationsPanel(){
        const panel=document.getElementById('homeActivityNotificationsPanel');
        const button=document.getElementById('homeActivityNotificationsButton');
        if(!panel||!button) return;
        if(window.matchMedia('(max-width:430px)').matches){
          const rect=button.getBoundingClientRect();
          const containingTop=activityFixedContainingBlockTop(panel);
          const top=Math.max(6,Math.round(rect.bottom+3-containingTop));
          panel.style.setProperty('--activity-panel-top',top+'px');
        }else{
          panel.style.removeProperty('--activity-panel-top');
        }
      }

      function setActivityNotificationsOpen(open){
        const panel=document.getElementById('homeActivityNotificationsPanel');
        const button=document.getElementById('homeActivityNotificationsButton');
        if(!panel||!button) return;
        const next=Boolean(open);
        const dashboard=document.getElementById('homeDashboard');
        clearTimeout(activityNotificationsCloseTimer);
        if(next){
          setSettingsOpen(false);
          activityJournalExpanded=false;
          positionActivityNotificationsPanel();
          panel.hidden=false;
          requestAnimationFrame(()=>panel.classList.add('is-open'));
        }else{
          panel.classList.remove('is-open');
          activityNotificationsCloseTimer=setTimeout(()=>{
            if(!panel.classList.contains('is-open')) panel.hidden=true;
          },230);
        }
        button.setAttribute('aria-expanded',next?'true':'false');
        dashboard?.classList.toggle('activity-notifications-open',next);
        if(next){
          renderActivityJournalItems(homeDashboardState.activity);
          syncUiPreferencesFromServer({force:true}).then(()=>{
            renderActivityJournalItems(homeDashboardState.activity);
            updateActivityNotificationBadge();
          }).catch(()=>{});
        }
      }

      function setupActivityNotifications(){
        const button=document.getElementById('homeActivityNotificationsButton');
        const panel=document.getElementById('homeActivityNotificationsPanel');
        if(!button||!panel||button.dataset.bound==='1') return;
        button.dataset.bound='1';
        document.querySelectorAll('[data-activity-mode]').forEach(modeButton=>{
          if(modeButton.dataset.bound==='1') return;
          modeButton.dataset.bound='1';
          modeButton.addEventListener('click',event=>{
            event.preventDefault();event.stopPropagation();
            activityPanelMode=modeButton.dataset.activityMode==='history'?'history':'notifications';
            activityJournalExpanded=false;renderActivityJournalItems(homeDashboardState.activity);
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
          });
        });
        const markAll=document.getElementById('homeActivityMarkAllButton');
        if(markAll&&markAll.dataset.bound!=='1'){
          markAll.dataset.bound='1';
          markAll.addEventListener('click',event=>{
            event.preventDefault();event.stopPropagation();
            const previous=currentActivityReadIds();
            const changed=markActivityNotificationsSeen();
            if(changed){
              showUndoSnackbar('Уведомления прочитаны',async()=>{
                storeActivityReadIds(previous);
                markUiPreferencesChanged({activityReadIds:previous});
                renderActivityJournalItems(homeDashboardState.activity);
                updateActivityNotificationBadge();
              },5000);
            }
            try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
          });
        }
        button.addEventListener('click',event=>{
          event.preventDefault();event.stopPropagation();
          setActivityNotificationsOpen(!panel.classList.contains('is-open'));
          try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
        });
        document.addEventListener('click',event=>{
          if(panel.hidden||!panel.classList.contains('is-open')) return;
          if(event.target.closest?.('#homeActivityNotifications')) return;
          setActivityNotificationsOpen(false);
        });
        document.addEventListener('keydown',event=>{if(event.key==='Escape') setActivityNotificationsOpen(false)});
        const reposition=()=>{if(!panel.hidden&&panel.classList.contains('is-open')) positionActivityNotificationsPanel()};
        window.addEventListener('resize',reposition,{passive:true});
        window.addEventListener('orientationchange',reposition,{passive:true});
        window.visualViewport?.addEventListener?.('resize',reposition,{passive:true});
        window.visualViewport?.addEventListener?.('scroll',reposition,{passive:true});
      }

      let activityJournalExpanded=false;
      let activityPanelMode='notifications';
      function activityMoodView(item){
        const emoji=normalizeLegacyMoodIcon(item?.icon||'🙂');
        const labels={'😢':'Грусть','🥱':'Скука','😐':'Нейтрально','😩':'Усталость','😡':'Злость','😄':'Радость','🥰':'Любовь'};
        return {emoji,label:labels[emoji]||'Настроение'};
      }

      function activityChangeCountLabel(count){
        const n=Math.max(0,Number(count)||0);
        const mod10=n%10,mod100=n%100;
        const word=mod100>=11&&mod100<=14?'изменений':mod10===1?'изменение':mod10>=2&&mod10<=4?'изменения':'изменений';
        return n+' '+word;
      }

      function compactActivityItems(items){
        const source=Array.isArray(items)?items:[];
        const moodGroups=new Map();
        const saveGroups=new Map();
        const eventGroups=new Map();
        const result=[];
        for(const item of source){
          const type=String(item?.type||'');
          const actor=String(item?.actor||'').trim()||(type==='mood'?'Настроение':'Сохранённое');
          const createdAt=String(item?.createdAt||'');
          const createdMs=Date.parse(createdAt)||0;
          const dateKey=sharedAlbumDateKey(new Date(createdAt));
          if(type!=='mood'&&type!=='smart-save'){
            const bucket=createdMs?Math.floor(createdMs/(20*60*1000)):0;
            const eventKey=[type,actor,String(item?.text||'').trim(),String(item?.targetTab||''),String(item?.targetItem||item?.itemId||''),bucket].join('|');
            const existing=eventGroups.get(eventKey);
            if(existing){
              existing.count+=1;
              existing.items.push(item);
              if((Date.parse(existing.latest?.createdAt||'')||0)<=createdMs) existing.latest=item;
            }else{
              const group={kind:'event-summary',count:1,items:[item],latest:item,item,createdAt};
              eventGroups.set(eventKey,group);
              result.push(group);
            }
            continue;
          }
          const key=actor+'|'+dateKey;
          const groups=type==='mood'?moodGroups:saveGroups;
          const existing=groups.get(key);
          if(existing){
            existing.count+=1;
            existing.items.push(item);
          }else{
            const group={kind:type==='mood'?'mood-summary':'smart-save-summary',actor,count:1,items:[item],latest:item,createdAt};
            groups.set(key,group);
            result.push(group);
          }
        }
        return result.sort((a,b)=>Date.parse(b.createdAt||0)-Date.parse(a.createdAt||0));
      }

      function activityEventView(item){
        const raw=String(item?.text||'').trim();
        const type=String(item?.type||'');
        if(type==='fasting'){
          const split=raw.match(/^(.+?):\s*(.+)$/u);
          if(split) return {title:split[1],detail:split[2]};
        }
        return {title:raw,detail:''};
      }

      function activityTargetTab(item){
        const type=String(item?.type||'');
        if(type==='reward-unlock') return '';
        const raw=String(item?.targetTab||'').trim();
        if(raw) return raw==='saves'?'dates':raw;
        if(type==='partner-message'||type==='like') return 'home';
        if(type==='photo') return 'photos';
        if(type==='calendar') return 'schedule';
        if(type==='wishlist') return 'wishlist';
        if(type==='saved-recipe') return 'products';
        if(type==='task-complete'||type==='checklist-complete'||type==='daily-question'||type==='lulu-walk'||type==='mood') return 'home';
        return '';
      }
      function activityTargetItem(item){
        const explicit=[item?.targetItem,item?.targetId,item?.itemId,item?.entityId]
          .find(value=>typeof value==='string'&&value.trim());
        if(explicit) return String(explicit).trim();
        const type=String(item?.type||'');
        if(type==='daily-question') return 'daily-question';
        if(type==='lulu-walk') return 'lulu';
        if(type==='mood') return String(item?.actor||'')==='Диана'?'diana':'rustam';
        if(type==='reward-unlock') return 'shop';
        if(type==='task-complete'||type==='checklist-complete') return 'priority';
        return '';
      }
      function openActivityTarget(item){
        const activityTab=activityTargetTab(item);if(!activityTab) return;
        const targetItem=activityTargetItem(item);
        setActivityNotificationsOpen(false);
        navigateToAppTab(activityTab,{scroll:true,item:targetItem});
        if(activityTab==='products'){
          loadProducts({silent:true});
          Promise.resolve(window.RUDI_SAVES?.load?.()).finally(()=>{
            if(item?.type==='saved-recipe') requestAnimationFrame(()=>requestAnimationFrame(()=>{
              setKitchenView('saves',{scroll:true});
            }));
          });
        }
        if(activityTab==='photos') loadSharedAlbum();
        if(activityTab==='schedule') loadWorkCalendar(currentWorkCalendarView,{silent:true});
        if(activityTab==='smart-saves') loadSmartSaves({silent:true});
      }
      function activityEntryItems(entry){
        if(Array.isArray(entry?.items)&&entry.items.length) return entry.items;
        return entry?.item?[entry.item]:[];
      }

      function renderActivityJournalItems(items){
        const list=document.getElementById('homeActivityList'),empty=document.getElementById('homeActivityEmpty');
        if(!list||!empty) return;
        const source=Array.isArray(items)?items:[];
        // Product list edits are intentionally kept out of the shared activity feed.
        // This also hides legacy records without deleting other historical activity.
        const withoutProductAdds=source.filter(item=>String(item?.type||'')!=='products');
        const filtered=activityPanelMode==='history'?withoutProductAdds:withoutProductAdds.filter(activityNotificationItem);
        const summaries=compactActivityItems(filtered);
        const visible=activityJournalExpanded?summaries:summaries.slice(0,5);
        const read=new Set(currentActivityReadIds());
        list.replaceChildren();empty.hidden=summaries.length>0;
        empty.textContent=activityPanelMode==='history'?'История пока пустая.':'Новых уведомлений пока нет.';
        const title=document.querySelector('.home-activity-notifications-title');
        if(title) title.textContent=activityPanelMode==='history'?'История активности':'Уведомления';
        document.querySelectorAll('[data-activity-mode]').forEach(button=>{
          const active=button.dataset.activityMode===activityPanelMode;
          button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',active?'true':'false');
        });
        for(const entry of visible){
          const item=(entry.kind==='mood-summary'||entry.kind==='event-summary')?entry.latest:entry.item;
          const entryItems=activityEntryItems(entry);
          const unread=activityPanelMode==='notifications'&&entryItems.some(row=>!read.has(String(row?.id||'')));
          const row=document.createElement('button');row.type='button';
          row.className='home-activity-row'+(entry.kind==='mood-summary'?' is-mood-summary':'')+(unread?' is-unread':'');
          const icon=document.createElement('span');icon.className='home-activity-icon';
          const copy=document.createElement('span');copy.className='home-activity-copy';
          const textNode=document.createElement('strong'),detail=document.createElement('time');
          if(entry.kind==='mood-summary'){
            const mood=activityMoodView(item);icon.textContent=mood.emoji;textNode.textContent=entry.actor+' · '+mood.label;
            detail.textContent=(entry.count>1?activityChangeCountLabel(entry.count)+' · ':'')+activityTimeLabel(item.createdAt);
          }else if(entry.kind==='smart-save-summary'){
            icon.textContent='🔖';textNode.textContent=entry.actor+' · '+(entry.count===1?'добавлено сохранение':'добавлено '+entry.count+' сохранения');detail.textContent=activityTimeLabel(item.createdAt);
          }else{
            const view=activityEventView(item);icon.textContent=String(item?.icon||'•');textNode.textContent=view.title;
            const grouped=entry.kind==='event-summary'&&Number(entry.count||0)>1?('×'+entry.count+' · '):'';
            detail.textContent=grouped+(view.detail?view.detail+' · ':'')+activityTimeLabel(item?.createdAt);
          }
          copy.append(textNode,detail);
          const arrow=document.createElement('span');arrow.className='home-activity-arrow';arrow.textContent=activityTargetTab(item)?'›':'';
          row.append(icon,copy,arrow);
          row.addEventListener('click',()=>{
            if(activityPanelMode==='notifications') markActivityItemsRead(entryItems,{render:false});
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
            if(activityTargetTab(item)) openActivityTarget(item);else renderActivityJournalItems(homeDashboardState.activity);
          });
          list.appendChild(row);
        }
        const hiddenCount=Math.max(0,summaries.length-5);
        if(hiddenCount>0){
          const more=document.createElement('button');more.type='button';more.className='home-activity-more';
          more.textContent=activityJournalExpanded?'Свернуть':'Показать ещё '+hiddenCount;
          more.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();activityJournalExpanded=!activityJournalExpanded;renderActivityJournalItems(homeDashboardState.activity)});
          list.appendChild(more);
        }
        animateRudiCollection(list,'.home-activity-row',8);updateActivityNotificationBadge();
      }

      function activityMoodLabel(icon){
        return {
          '😢':'Грусть',
          '🥱':'Скука',
          '😐':'Нейтрально',
          '😩':'Усталость',
          '😡':'Гнев',
          '😄':'Радость',
          '🥰':'Любовь'
        }[normalizeLegacyMoodIcon(icon||'')]||'Настроение';
      }

      function activityCountWord(value){
        const n=Math.abs(Number(value)||0),mod100=n%100,mod10=n%10;
        if(mod100>=11&&mod100<=14) return 'изменений';
        if(mod10===1) return 'изменение';
        if(mod10>=2&&mod10<=4) return 'изменения';
        return 'изменений';
      }

      function summarizeActivityItems(items){
        const source=Array.isArray(items)?items:[],groups=new Map(),summary=[];
        for(const item of source){
          const type=String(item?.type||''),actor=String(item?.actor||'').trim()||'Событие';
          const date=new Date(String(item?.createdAt||'')),dateKey=Number.isNaN(date.getTime())?'unknown':sharedAlbumDateKey(date);
          if(type==='mood'){
            const key='mood|'+actor+'|'+dateKey;let group=groups.get(key);
            if(!group){group={...item,_activityKind:'mood-summary',_moodCount:0,_moodIcons:[],_latestMoodIcon:normalizeLegacyMoodIcon(item?.icon||'🙂')};groups.set(key,group);summary.push(group)}
            group._moodCount+=1;group._moodIcons.push(normalizeLegacyMoodIcon(item?.icon||'🙂'));continue;
          }
          if(type==='smart-save'){
            const key='smart-save|'+actor+'|'+dateKey;let group=groups.get(key);
            if(!group){group={...item,_activityKind:'smart-save-summary',_saveCount:0};groups.set(key,group);summary.push(group)}
            group._saveCount+=1;continue;
          }
          summary.push({...item,_activityKind:'item'});
        }
        return summary;
      }

      function activityMoodDetail(item){
        const count=Math.max(1,Number(item?._moodCount)||1);if(count<=1)return'';
        const icons=Array.isArray(item?._moodIcons)?item._moodIcons.filter(Boolean):[],recent=icons.slice(0,4).reverse(),sequence=(icons.length>4?'… → ':'')+recent.join(' → ');
        return sequence+(sequence?' · ':'')+count+' '+activityCountWord(count);
      }

      function renderActivityJournal(payload){
        renderLulu(payload?.lulu);if(payload?.score)renderScoreStickers(payload.score);
        const items=(Array.isArray(payload?.items)?payload.items:[]).slice(0,80);
        homeDashboardState.activity=items;homeDashboardState.activityVersion=Math.max(0,Number(payload?.version||0));
        migrateLegacyActivitySeenMarker(items,homeDashboardState.activityVersion);
        migrateLegacyActivityReadState(items);
        renderActivityJournalItems(items);
      }

      async function loadActivityJournal({silent=false}={}){
        if(!currentActor) return null;
        try{
          const payload=await activityRequest();
          renderActivityJournal(payload);
          return payload;
        }catch(_){
          if(!silent){
            const empty=document.getElementById('homeActivityEmpty');
            if(empty&&!homeDashboardState.activity.length){
              empty.hidden=false;
              empty.textContent='Не удалось обновить события';
            }
          }
          return null;
        }
      }

      let smartSavesState=[],smartSavesLoadPromise=null,smartSavesFilter='all';
      async function smartSavesRequest(operation='list',payload={}){
        const response=await fetch('/api/partner-message?rudiAction=smart-saves',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({initData:tg?.initData||'',operation,...payload}),cache:'no-store'});
        const data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.error||'smart-saves-request-failed');return data;
      }
      function smartSaveStamp(value){const date=new Date(String(value||''));if(Number.isNaN(date.getTime()))return'';return new Intl.DateTimeFormat('ru-RU',{timeZone:TZ,day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(date).replace('.','')}
      function smartSaveConfirm(text){return new Promise(resolve=>{if(tg?.showConfirm){try{tg.showConfirm(text,value=>resolve(Boolean(value)));return}catch(_){}}resolve(window.confirm(text))})}

      // RUDI v4.88: iOS Telegram WebView may disallow modern clipboard permission.
      // Keep both legacy selection modes as fallbacks and avoid deleting user selection.
      function copySmartSaveSelection(text,mode){
        const value=String(text||'');
        const target=mode==='rich'?document.createElement('div'):document.createElement('textarea');
        if(mode==='rich'){
          target.contentEditable='true';
          target.textContent=value;
        }else{
          target.value=value;
          target.readOnly=true;
        }
        target.style.cssText='position:fixed;left:0;top:0;z-index:-1;opacity:.01;width:1px;height:1px;pointer-events:none;';
        document.body.appendChild(target);
        const previousFocus=document.activeElement;
        let copied=false;
        try{
          target.focus({preventScroll:true});
          if(mode==='rich'){
            const range=document.createRange();range.selectNodeContents(target);
            const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);
          }else{
            target.select();target.setSelectionRange(0,value.length);
          }
          copied=Boolean(document.execCommand('copy'));
        }catch(_){}
        finally{
          window.getSelection?.()?.removeAllRanges();
          target.remove();
          try{previousFocus?.focus?.({preventScroll:true})}catch(_){}
        }
        return copied;
      }
      async function copySmartSaveText(text){
        const value=String(text||'');
        if(!value.trim())return false;
        const ios=/iPad|iPhone|iPod/i.test(String(navigator.userAgent||''));
        if(ios){
          if(copySmartSaveSelection(value,'textarea'))return true;
          if(copySmartSaveSelection(value,'rich'))return true;
        }
        try{
          if(navigator.clipboard?.writeText){
            await navigator.clipboard.writeText(value);
            return true;
          }
        }catch(_){}
        if(!ios){
          if(copySmartSaveSelection(value,'textarea'))return true;
          if(copySmartSaveSelection(value,'rich'))return true;
        }
        return false;
      }

      function smartSaveCard(item,{compact=false}={}){
        const card=document.createElement('article');card.className='smart-save-card'+(compact?' is-compact':'');card.dataset.rudiItemId=String(item?.id||'');
        if(/^coffee\s*3$/iu.test(String(item?.title||'').trim())) card.classList.add('is-coffee3');
        if(item?.imageUrl){const img=document.createElement('img');img.className='smart-save-image';img.src=String(item.imageUrl);img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';img.addEventListener('error',()=>img.remove());card.appendChild(img)}
        const body=document.createElement('div');body.className='smart-save-body',meta=document.createElement('div');meta.className='smart-save-meta';
        const category=document.createElement('span');category.className='smart-save-category';category.textContent=String(item?.category||'Другое');
        const stamp=document.createElement('time');stamp.textContent=String(item?.actor||'')+' · '+smartSaveStamp(item?.createdAt);meta.append(category,stamp);
        const title=item?.url?document.createElement('a'):document.createElement('strong');title.className='smart-save-title';title.textContent=String(item?.title||'Сохранение');
        if(item?.url){title.href=String(item.url);title.target='_blank';title.rel='noopener noreferrer'}
        title.classList.add('smart-save-selectable');
        body.append(meta,title);
        if(!compact&&item?.description){
          let description=String(item.description).trim();
          if(/^coffee\s*3$/iu.test(String(item?.title||'').trim())){
            description=description
              .split(/\r?\n/u)
              .filter(line=>!/адрес[^\n]*восстан|восстан[^\n]*адрес|площад(?:ь|и)\s+восстания|(?:^|\s)восстания(?:\s|$)/iu.test(String(line||'').trim()))
              .join('\n')
              .trim();
          }
          if(description){
            const desc=document.createElement('p');
            desc.textContent=description;
            body.appendChild(desc);
          }
        }
        const itemUrl=String(item?.url||'').trim();
        if(itemUrl){
          const openUrl=()=>{try{if(tg?.openLink){tg.openLink(itemUrl);return}}catch(_){}window.open(itemUrl,'_blank','noopener,noreferrer')};
          card.classList.add('is-link');
          card.setAttribute('role','link');
          card.tabIndex=0;
          card.addEventListener('click',event=>{if(event.target.closest('a,button'))return;if(window.getSelection?.()?.toString())return;openUrl()});
          card.addEventListener('keydown',event=>{if(event.target!==card||!['Enter',' '].includes(event.key))return;event.preventDefault();openUrl()});
          const open=document.createElement('button');open.type='button';open.className='smart-save-open';open.innerHTML='<span>Перейти</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg>';
          open.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();openUrl()});
          body.appendChild(open);
        }else if(String(item?.rawText||'').trim()){
          const details=document.createElement('div');details.className='smart-save-raw';details.hidden=true;
          const raw=document.createElement('div');raw.className='smart-save-raw-text';raw.textContent=String(item.rawText);details.appendChild(raw);
          const toggle=document.createElement('button');toggle.type='button';toggle.className='smart-save-expand';toggle.setAttribute('aria-expanded','false');
          toggle.innerHTML='<span>Развернуть</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 10 4 4 4-4"/></svg>';
          const setExpanded=expanded=>{details.hidden=!expanded;toggle.setAttribute('aria-expanded',expanded?'true':'false');toggle.querySelector('span').textContent=expanded?'Свернуть':'Развернуть';card.classList.toggle('is-expanded',expanded)};
          toggle.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();setExpanded(toggle.getAttribute('aria-expanded')!=='true');try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}});
          card.classList.add('is-expandable');
          card.addEventListener('click',event=>{if(event.target.closest('a,button'))return;if(window.getSelection?.()?.toString())return;setExpanded(toggle.getAttribute('aria-expanded')!=='true')});
          body.append(toggle,details);
        }
        // Copy original saved text, not a truncated card preview.
        const saveCopyText=String(item?.rawText||'').trim()||[item?.title,item?.description,item?.url].map(value=>String(value||'').trim()).filter(Boolean).join('\n');
        if(!compact&&saveCopyText){
          const copy=document.createElement('button');
          copy.type='button';copy.className='smart-save-copy';copy.textContent='Скопировать';
          copy.setAttribute('aria-label','Скопировать сохранение');
          copy.addEventListener('click',async event=>{
            event.preventDefault();event.stopPropagation();
            if(copy.disabled)return;
            copy.disabled=true;
            const success=await copySmartSaveText(saveCopyText);
            copy.textContent=success?'Скопировано':'Выделите текст долгим нажатием';
            try{if(success)tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
            setTimeout(()=>{if(copy.isConnected){copy.textContent='Скопировать';copy.disabled=false}},2200);
          });
          body.appendChild(copy);
        }
        const ownSave=String(item?.actor||'')===String(currentActor||'');
        card.appendChild(body);
        if(ownSave){
          const del=document.createElement('button');del.type='button';del.className='smart-save-delete';del.setAttribute('aria-label','Удалить сохранение');del.setAttribute('title','Удалить');del.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg>';
          del.addEventListener('click',async event=>{
            event.preventDefault();event.stopPropagation();
            if(!await smartSaveConfirm('Удалить «'+String(item?.title||'это сохранение')+'»?')) return;
            const previous=[...smartSavesState];
            smartSavesState=smartSavesState.filter(row=>String(row?.id||'')!==String(item?.id||''));
            renderSmartSaves();
            try{tg?.HapticFeedback?.impactOccurred?.('light')}catch(_){}
            try{
              const data=await smartSavesRequest('remove',{id:item.id});
              const removed=data?.item||item;
              smartSavesState=Array.isArray(data.items)?data.items:smartSavesState;
              renderSmartSaves();
              showUndoSnackbar('Сохранение удалено',async()=>{
                const restored=await smartSavesRequest('restore',{item:removed});
                smartSavesState=Array.isArray(restored.items)?restored.items:previous;
                renderSmartSaves();
              },5000);
            }catch(_){
              smartSavesState=previous;
              renderSmartSaves();
              try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
            }
          });
          card.appendChild(del);
        }
        return card;
      }
      function renderSmartSaves(){
        const home=document.getElementById('smartSavesHomeList'),homeEmpty=document.getElementById('smartSavesHomeEmpty'),page=document.getElementById('smartSavesPageList'),pageEmpty=document.getElementById('smartSavesPageEmpty');
        const rows=[...smartSavesState].sort((a,b)=>(Date.parse(b?.createdAt)||0)-(Date.parse(a?.createdAt)||0));
        if(home){home.replaceChildren();rows.slice(0,3).forEach(item=>home.appendChild(smartSaveCard(item,{compact:true})));if(homeEmpty)homeEmpty.hidden=rows.length>0;const more=document.getElementById('smartSavesHomeMore');if(more)more.hidden=rows.length===0}
        if(page){
          page.replaceChildren();
          const pageRows=smartSavesFilter==='all'?rows:rows.filter(item=>String(item?.actor||'')===smartSavesFilter);
          const groups=new Map();pageRows.forEach(item=>{const key=String(item?.category||'Другое');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item)});
          groups.forEach((items,category)=>{const section=document.createElement('section');section.className='smart-saves-category-block';const head=document.createElement('div');head.className='smart-saves-category-head';const strong=document.createElement('strong'),count=document.createElement('span');strong.textContent=category;count.textContent=String(items.length);head.append(strong,count);section.appendChild(head);const list=document.createElement('div');list.className='smart-saves-category-list';items.forEach(item=>list.appendChild(smartSaveCard(item)));section.appendChild(list);page.appendChild(section)});
          document.querySelectorAll('[data-smart-saves-filter]').forEach(button=>button.setAttribute('aria-pressed',button.dataset.smartSavesFilter===smartSavesFilter?'true':'false'));
          if(pageEmpty){pageEmpty.hidden=pageRows.length>0;pageEmpty.textContent=smartSavesFilter==='all'?'Здесь пока пусто.':'У '+smartSavesFilter+(smartSavesFilter==='Диана'?'ы':'а')+' сохранений пока нет.'}
        }
      }
      async function loadSmartSaves({silent=false}={}){
        if(smartSavesLoadPromise)return smartSavesLoadPromise;
        smartSavesLoadPromise=(async()=>{try{const data=await smartSavesRequest('list');smartSavesState=Array.isArray(data.items)?data.items:[];renderSmartSaves();return smartSavesState}catch(error){if(!silent)console.warn('RUDI_SMART_SAVES_UI_WARN',String(error?.message||error));return smartSavesState}finally{smartSavesLoadPromise=null}})();return smartSavesLoadPromise;
      }

