      function malePsychologyFactFromConfig(config,dateKey=todayState().key){
        const section=config?.malePsychology;
        const facts=Array.isArray(section?.facts)?section.facts:[];
        const startDate=/^\d{4}-\d{2}-\d{2}$/.test(String(section?.startDate||''))?String(section.startDate):'2026-09-23';
        const start=Date.parse(startDate+'T00:00:00.000Z');
        const current=Date.parse(String(dateKey||'')+'T00:00:00.000Z');
        if(!Number.isFinite(start)||!Number.isFinite(current)) return null;
        const sequence=Math.floor((current-start)/DAY)+1;
        if(sequence<1) return null;
        const fact=facts
          .map((row,index)=>({...row,sequence:Math.max(1,Math.trunc(Number(row?.sequence||index+1)))}))
          .find((row)=>row.sequence===sequence);
        if(!fact) return null;
        const sourceUrl=String(fact.sourceUrl||'').trim();
        if(!/^https:\/\/pubmed\.ncbi\.nlm\.nih\.gov\/\d+\/?$/i.test(sourceUrl)) return null;
        return {
          id:String(fact.id||'').trim(),
          sequence,
          title:String(fact.title||'').trim(),
          text:String(fact.text||'').trim(),
          sourceLabel:String(fact.sourceLabel||'PubMed').trim(),
          sourceUrl,
          dateKey:String(dateKey||''),
          disclaimer:String(section?.disclaimer||'Это данные о средних групповых закономерностях. Они не описывают каждого мужчину.')
        };
      }

      function renderMalePsychologyFact(fact){
        currentMalePsychologyFact=fact&&typeof fact==='object'?fact:null;
        const card=document.getElementById('malePsychologyFact');
        if(!card) return;
        const id=String(fact?.id||'').trim();
        const title=String(fact?.title||'').trim();
        const text=String(fact?.text||'').trim();
        const sourceUrl=String(fact?.sourceUrl||'').trim();
        if(!id||!title||!text||!/^https:\/\/pubmed\.ncbi\.nlm\.nih\.gov\/\d+\/?$/i.test(sourceUrl)){
          card.hidden=true;
          return;
        }
        const titleNode=document.getElementById('malePsychologyFactTitle');
        const textNode=document.getElementById('malePsychologyFactText');
        const source=document.getElementById('malePsychologyFactSource');
        const disclaimer=document.getElementById('malePsychologyFactDisclaimer');
        if(titleNode) titleNode.textContent=title;
        if(textNode) textNode.textContent=text;
        if(source){
          source.href=sourceUrl;
          source.textContent=String(fact?.sourceLabel||'Открыть исследование в PubMed');
          if(source.dataset.bound!=='1'){
            source.dataset.bound='1';
            source.addEventListener('click',event=>{
              if(!tg?.openLink) return;
              event.preventDefault();
              try{tg.openLink(source.href)}catch(_){window.open(source.href,'_blank','noopener,noreferrer')}
            });
          }
        }
        if(disclaimer) disclaimer.textContent=String(fact?.disclaimer||'Это средняя групповая закономерность, а не описание каждого мужчины.');
        card.dataset.factId=id;
        card.hidden=false;
        restartRudiMotion(card,'rudi-data-refresh',360);
      }

      let malePsychologyLoadPromise=null;
      async function loadMalePsychologyFact(){
        if(!currentActor) return null;
        if(malePsychologyLoadPromise) return malePsychologyLoadPromise;
        malePsychologyLoadPromise=(async()=>{
          try{
            const config=await loadConfig();
            currentConfig=config;
            const fact=malePsychologyFactFromConfig(config);
            renderMalePsychologyFact(fact);
            return fact;
          }catch(error){
            console.warn('RUDI_MALE_PSYCHOLOGY_UI_WARN',String(error?.message||error));
            return null;
          }finally{
            malePsychologyLoadPromise=null;
          }
        })();
        return malePsychologyLoadPromise;
      }

      function homeSupplementEmoji(name){
        const value=String(name||'').toLowerCase().replace(/ё/g,'е');
        if(/креатин/.test(value)) return '🏋️';
        if(/теанин|l[-\s]?theanine/.test(value)) return '🍵';
        if(/витамин\s*d|d3|к2|k2/.test(value)) return '☀️';
        if(/магни/.test(value)) return '⚡';
        if(/омега|рыб/.test(value)) return '🐟';
        if(/желез/.test(value)) return '🩸';
        if(/цинк/.test(value)) return '🛡️';
        if(/мелатонин/.test(value)) return '🌙';
        if(/коллаген/.test(value)) return '🦴';
        if(/протеин|белок/.test(value)) return '🥛';
        if(/витамин\s*c|аскорб/.test(value)) return '🍊';
        if(/тирозин/.test(value)) return '🧠';
        return '💊';
      }

      function homeSupplementTime(value){
        const date=new Date(String(value||''));
        if(Number.isNaN(date.getTime())) return '';
        return new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}).format(date);
      }

      function renderHomeSupplementIntakes(actor,rows,progress={}){
        const list=document.getElementById(actor==='Диана'?'homeDianaSupplementIntakes':'homeRustamSupplementIntakes');
        if(!list) return;
        const values=Array.isArray(rows)?rows:[];
        const progressNode=document.getElementById(actor==='Диана'?'homeDianaSupplementProgress':'homeRustamSupplementProgress');
        const taken=Math.max(0,Math.round(Number(progress?.taken)||0));
        const total=Math.max(taken,Math.round(Number(progress?.total)||0));
        if(progressNode){
          progressNode.textContent=taken+'/'+total;
          progressNode.setAttribute('aria-label',taken+' из '+total+' принято');
        }
        list.replaceChildren();
        if(!values.length){
          const empty=document.createElement('div');
          empty.className='profile-supplement-intakes-empty';
          empty.textContent='Сегодня ещё ничего не отмечено';
          list.appendChild(empty);
          return;
        }
        for(const row of values){
          const item=document.createElement('div');
          item.className='profile-supplement-intake-row';
          const emoji=document.createElement('span');
          emoji.className='profile-supplement-intake-emoji';
          emoji.textContent=homeSupplementEmoji(row?.name);
          const copy=document.createElement('span');
          copy.className='profile-supplement-intake-copy';
          const name=document.createElement('span');
          name.className='profile-supplement-intake-name';
          name.textContent=String(row?.name||'БАД');
          const time=document.createElement('time');
          time.className='profile-supplement-intake-time';
          time.dateTime=String(row?.at||'');
          time.textContent=homeSupplementTime(row?.at);
          copy.append(name,time);
          const check=document.createElement('span');
          check.className='profile-supplement-intake-check';
          check.setAttribute('aria-hidden','true');
          check.textContent='✓';
          item.append(emoji,copy,check);
          list.appendChild(item);
        }
      }

      let supplementOverviewLoadPromise=null;
      async function loadSupplementIntakeOverview(options={}){
        if(!currentActor) return null;
        if(options.force) invalidateManagedRequests('supplement-overview');
        if(supplementOverviewLoadPromise) return supplementOverviewLoadPromise;
        supplementOverviewLoadPromise=(async()=>{
          try{
            const data=await managedJsonRequest('supplement-overview','/api/supplements',{
              body:{operation:'overview',initData:String(tg?.initData||'')},
              ttlMs:10*60*1000,
              timeoutMs:7000
            });
            if(!data?.ok) throw new Error(String(data?.error||'supplement-overview-failed'));
            renderHomeSupplementIntakes('Рустам',data.actors?.['Рустам'],data.progress?.['Рустам']);
            renderHomeSupplementIntakes('Диана',data.actors?.['Диана'],data.progress?.['Диана']);
            return data;
          }catch(error){
            if(!options.silent) console.warn('RUDI_SUPPLEMENT_OVERVIEW_UI_WARN',String(error?.message||error));
            return null;
          }finally{
            supplementOverviewLoadPromise=null;
          }
        })();
        return supplementOverviewLoadPromise;
      }

      document.addEventListener('rudi:supplement-intake-updated',()=>{
        invalidateManagedRequests('supplement-overview');
        loadSupplementIntakeOverview({silent:true});
      });

