        const settingsPage=settings.querySelector('#homeSettingsPanel');
        if(settingsPage){
          settingsPage.className='settings-page';
          settingsPage.dataset.appTabSection='settings';
          settingsPage.dataset.tabAvailable='1';
          settingsPage.setAttribute('aria-labelledby','settingsPageTitle');
          settingsPage.querySelector('.home-settings-title')?.remove();

          const settingsHead=document.createElement('div');
          settingsHead.className='settings-page-head';
          settingsHead.innerHTML=
            '<button id="settingsPageBack" class="settings-page-back" type="button" aria-label="Назад">'+
              '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg>'+
            '</button>'+
            '<h1 id="settingsPageTitle">Настройки</h1>'+
            '<span class="settings-page-head-spacer" aria-hidden="true"></span>';
          settingsPage.prepend(settingsHead);

          const shell=document.querySelector('.shell');
          const footer=shell?.querySelector('.footer');
          if(shell) shell.insertBefore(settingsPage,footer||null);
          settingsPage.hidden=currentAppTab!=='settings';
        }

        tools.append(notifications,settings);
        top.append(greeting,tools,dateHeading,moonPhase,sunEvent);

        const messageNew=document.createElement('button');
        messageNew.id='homeMessageNew';
        messageNew.className='home-message-new';
        messageNew.type='button';
        messageNew.textContent='💌 Новое послание';
        messageNew.hidden=true;
        profile.replaceChildren(top,messageNew);

        const cycleSummary=document.createElement('div');
        cycleSummary.id='homeCycleSummary';
        cycleSummary.className='home-cycle-summary';
        cycleSummary.hidden=true;
        const cycleStatus=document.createElement('div');
        cycleStatus.id='homeCycleStatus';
        cycleStatus.className='home-cycle-status';
        const cycleAdvice=document.createElement('div');
        cycleAdvice.id='homeCycleAdvice';
        cycleAdvice.className='home-cycle-advice';
        const cycleBrain=document.createElement('div');
        cycleBrain.id='homeCycleBrain';
        cycleBrain.className='home-cycle-insight';
        const cycleAppetite=document.createElement('div');
        cycleAppetite.id='homeCycleAppetite';
        cycleAppetite.className='home-cycle-insight';
        const cycleOpen=document.createElement('button');
        cycleOpen.id='homeCycleOpen';
        cycleOpen.className='home-cycle-open';
        cycleOpen.type='button';
        cycleOpen.textContent='Показать полностью';
        cycleOpen.hidden=currentActor!=='Диана';
        cycleSummary.append(cycleStatus,cycleAdvice,cycleBrain,cycleAppetite,cycleOpen);

        const makeProfileContactButton=(kind,actor)=>{
          const button=document.createElement('button');
          button.type='button';
          button.className='profile-contact-button is-'+kind;
          button.dataset.contactKind=kind;
          button.dataset.contactActor=actor;
          button.innerHTML=kind==='telegram'
            ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21.4 4.1 18.6 19c-.2 1.1-.8 1.4-1.7.9l-4.3-3.2-2.1 2c-.2.2-.4.4-.9.4l.3-4.4 8-7.2c.3-.3-.1-.5-.5-.2l-9.9 6.2-4.3-1.3c-.9-.3-.9-.9.2-1.3L20.2 4c.8-.3 1.4.2 1.2 1.1Z" fill="currentColor"/></svg>'
            : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7.2 3.5 4.5 5.2c-.8.5-1.1 1.5-.8 2.4 1.9 5.7 6.2 10 11.9 11.9.9.3 1.9 0 2.4-.8l1.7-2.7c.4-.7.2-1.6-.5-2l-3.1-1.8c-.7-.4-1.5-.2-2 .4l-1 1.3a13.3 13.3 0 0 1-4.9-4.9l1.3-1c.6-.5.8-1.3.4-2L8.2 3.9c-.2-.4-.6-.6-1-.4Z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';
          button.addEventListener('click',event=>{
            event.preventDefault();event.stopPropagation();
            openProfileContact(actor,kind);
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
          });
          return button;
        };

        const makePersonTile=(actor,identity)=>{
          const tile=document.createElement('section');
          const slug=actor==='Диана'?'diana':'rustam';
          tile.id=actor==='Диана'?'homeDianaTile':'homeRustamTile';
          tile.className='panel profile-person-card profile-'+slug+'-card';
          tile.dataset.appTabSection='home';
          tile.dataset.homeTile=slug;
          tile.setAttribute('aria-label',actor);

          const head=document.createElement('div');
          head.className='profile-person-head';
          const avatar=identity.querySelector('.avatar');
          if(avatar){
            const avatarWrap=document.createElement('div');
            avatarWrap.className='score-avatar-wrap';
            const moodBadge=avatar.querySelector('.avatar-mood-badge');
            avatar.parentNode.insertBefore(avatarWrap,avatar);
            avatarWrap.append(avatar);
            if(moodBadge){
              moodBadge.classList.remove('score-avatar-mood-badge','profile-card-mood-badge','avatar-mood-sticker');
              const nameRow=identity.querySelector('.profile-name-row');
              const nameElement=identity.querySelector(actor===currentActor?'#displayName':'#partnerHeaderName')||nameRow?.querySelector('.name');
              if(nameRow){
                if(nameElement&&nameElement.parentNode===nameRow) nameElement.insertAdjacentElement('afterend',moodBadge);
                else nameRow.appendChild(moodBadge);
              }
            }
          }
          head.appendChild(identity);
          if(actor!==currentActor){
            const actions=document.createElement('div');
            actions.className='profile-person-actions';
            const partnerFastingButton=document.createElement('button');
            partnerFastingButton.id='partnerFastingProfileButton';
            partnerFastingButton.className='fasting-profile-button partner-mood-value partner-fasting-button';
            partnerFastingButton.type='button';
            partnerFastingButton.hidden=true;
            partnerFastingButton.setAttribute('aria-label','Голодание партнёра');
            partnerFastingButton.innerHTML='<span class="mood-emoji" aria-hidden="true">🍽️</span><span id="partnerFastingElapsed" class="fasting-profile-elapsed" aria-hidden="true" hidden></span>';
            partnerFastingButton.addEventListener('click',event=>{
              event.preventDefault();
              event.stopPropagation();
              showPartnerFastingGoal(partnerFastingButton);
              try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
            });
            actions.append(partnerFastingButton,makeProfileContactButton('telegram',actor),makeProfileContactButton('phone',actor));
            head.appendChild(actions);
          }
          const energy=document.createElement('div');
          energy.className='profile-energy-strip';
          energy.dataset.energyActor=actor;
          energy.setAttribute('role','img');
          energy.setAttribute('aria-label',actor+': ориентировочная энергия по распорядку');
          energy.innerHTML=
            '<div class="profile-energy-label"><span>⚡ Энергия</span><span class="profile-energy-phase"></span></div>'+
            '<div class="profile-energy-plot">'+
              '<svg class="profile-energy-svg" viewBox="0 0 640 40" preserveAspectRatio="none" aria-hidden="true"></svg>'+
              '<span class="profile-energy-now" aria-hidden="true"></span>'+
            '</div>'+
            '<div class="profile-energy-times" aria-hidden="true"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>24:00</span></div>';
          tile.append(energy,head);

          const details=document.createElement('div');
          details.id=actor==='Диана'?'homeDianaDetails':'homeRustamDetails';
          details.className='profile-person-details';
          tile.appendChild(details);
          return {tile,details};
        };

        const selfActor=currentActor==='Диана'?'Диана':'Рустам';
        const partnerActor=selfActor==='Диана'?'Рустам':'Диана';
        const selfCard=makePersonTile(selfActor,selfIdentity);
        const partnerCard=makePersonTile(partnerActor,partnerIdentity);
        const rustamCard=selfActor==='Рустам'?selfCard:partnerCard;
        const dianaCard=selfActor==='Диана'?selfCard:partnerCard;

        // Desktop browsers can place layout-management layers above the moved profile identity.
        // Keep the personal-profile hit area reliable even when the name itself is not the event target.
        const bindSelfProfileDesktopHitArea=()=>{
          const card=selfCard?.tile;
          const name=card?.querySelector?.('#displayName');
          if(!card||!name||card.dataset.personalProfileDesktopBound==='1') return;
          card.dataset.personalProfileDesktopBound='1';
          const openPersonalProfile=()=>window.RudiSupplementApp?.open?.();
          card.addEventListener('click',event=>{
            if(event.defaultPrevented) return;
            const target=event.target;
            if(target?.closest?.('button,a,input,select,textarea')&&!target?.closest?.('#displayName')) return;
            const rect=name.getBoundingClientRect();
            const x=Number(event.clientX),y=Number(event.clientY);
            if(Number.isFinite(x)&&Number.isFinite(y)&&x>=rect.left&&x<=rect.right&&y>=rect.top&&y<=rect.bottom){
              event.preventDefault();
              openPersonalProfile();
            }
          });
        };
        bindSelfProfileDesktopHitArea();

        const rhythmAdvice=document.createElement('div');
        rhythmAdvice.id='rustamRhythmAdvice';
        rhythmAdvice.className='rhythm-advice rustam-rhythm-advice';
        rhythmAdvice.style.setProperty('color','#eef2ff','important');
        rhythmAdvice.style.setProperty('-webkit-text-fill-color','#eef2ff','important');
        rhythmAdvice.style.setProperty('opacity','1','important');
        const currentRhythm=rustamRhythmStatus();
