      function readBlockStates(){
        try{
          const value=JSON.parse(localStorage.getItem(blockStateStorageKey())||'{}');
          return value&&typeof value==='object'&&!Array.isArray(value)?value:{};
        }catch(_){return {}}
      }

      function getBlockCollapsed(key,fallback=false){
        const states=readBlockStates();
        return Object.prototype.hasOwnProperty.call(states,key)?Boolean(states[key]):Boolean(fallback);
      }

      function setBlockCollapsed(key,collapsed){
        try{
          const states=readBlockStates();
          states[key]=Boolean(collapsed);
          localStorage.setItem(blockStateStorageKey(),JSON.stringify(states));
          markUiPreferencesChanged({blockStates:{[key]:Boolean(collapsed)}});
        }catch(_){}
      }

      function collapseButton(label){
        const button=document.createElement('button');
        button.type='button';
        button.className='block-collapse-button';
        button.setAttribute('aria-label',label);
        button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="m8 10 4 4 4-4"/></svg>';
        return button;
      }

      function wrapCollapseBody(section,selectors){
        const nodes=selectors.map(selector=>section.querySelector(selector)).filter(Boolean);
        if(!nodes.length) return null;
        const wrapper=document.createElement('div');
        wrapper.className='rudi-collapse-body';
        const inner=document.createElement('div');
        inner.className='rudi-collapse-body-inner';
        nodes[0].parentNode.insertBefore(wrapper,nodes[0]);
        wrapper.appendChild(inner);
        nodes.forEach(node=>inner.appendChild(node));
        return wrapper;
      }

      function addHeaderCollapseButton(section,host,button){
        if(host.classList.contains('profile-person-head')){
          let actions=host.querySelector(':scope > .profile-person-actions');
          if(!actions){
            actions=document.createElement('div');
            actions.className='profile-person-actions';
            host.appendChild(actions);
          }
          actions.appendChild(button);
          return;
        }
        if(host.classList.contains('car-head')){
          const copy=host.querySelector('.car-head-copy');
          const title=copy?.querySelector('h2');
          if(copy&&title){
            let row=copy.querySelector('.car-head-title-row');
            if(!row){
              row=document.createElement('div');
              row.className='car-head-title-row';
              title.parentNode.insertBefore(row,title);
              row.appendChild(title);
            }
            row.appendChild(button);
            return;
          }
        }
        if(host.classList.contains('section-heading')||host.classList.contains('partner-head')||host.classList.contains('smart-home-head')){
          let actions=host.querySelector(':scope > .block-head-actions');
          if(!actions){
            actions=document.createElement('div');
            actions.className='block-head-actions';
            const children=Array.from(host.children).slice(1);
            children.forEach(child=>actions.appendChild(child));
            host.appendChild(actions);
          }
          actions.appendChild(button);
          return;
        }
        host.appendChild(button);
      }

      function setupPersistentCollapsible({selector,key,bodySelectors,hostSelector,defaultCollapsed=false,resetCollapsedOnInit=false,persist=true}){
        const section=document.querySelector(selector);
        if(!section||section.dataset.collapseReady==='1') return;
        const body=wrapCollapseBody(section,bodySelectors);
        const host=section.querySelector(hostSelector);
        if(!body||!host) return;
        section.dataset.collapseReady='1';
        section.dataset.collapseKey=key;
        section.classList.add('rudi-collapsible');
        const button=collapseButton('Свернуть или развернуть блок');
        addHeaderCollapseButton(section,host,button);
        const titleTrigger=key.startsWith('profile-')
          ?host.querySelector('#displayName,#partnerHeaderName')
          :key==='smart-home'?host.querySelector('#smartHomeTitle')
          :key==='daily-question'?host.querySelector('#dailyQuestionTitle')
          :null;
        if(titleTrigger){
          titleTrigger.setAttribute('role','button');
          titleTrigger.tabIndex=0;
          titleTrigger.setAttribute('aria-controls','rudiCollapseBody-'+key);
          body.id='rudiCollapseBody-'+key;
        }

        const apply=collapsed=>{
          section.classList.toggle('is-collapsed',collapsed);
          button.setAttribute('aria-expanded',collapsed?'false':'true');
          titleTrigger?.setAttribute('aria-expanded',collapsed?'false':'true');
          body.setAttribute('aria-hidden',collapsed?'true':'false');
        };
        apply(!persist||resetCollapsedOnInit?Boolean(defaultCollapsed):getBlockCollapsed(key,defaultCollapsed));
        const toggleCollapsed=()=>{
          const collapsed=!section.classList.contains('is-collapsed');
          apply(collapsed);
          if(persist) setBlockCollapsed(key,collapsed);
          try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
        };
        button.addEventListener('click',toggleCollapsed);
        if(titleTrigger){
          titleTrigger.addEventListener('click',event=>{
            if(document.body.classList.contains('home-layout-editing'))return;
            event.preventDefault();
            event.stopPropagation();
            toggleCollapsed();
          });
          titleTrigger.addEventListener('keydown',event=>{
            if(event.key!=='Enter'&&event.key!==' ')return;
            event.preventDefault();
            event.stopPropagation();
            toggleCollapsed();
          });
        }
        if(key==='partner'){
          section.querySelector('#partnerEditButton')?.addEventListener('click',()=>{
            if(section.classList.contains('is-collapsed')){
              apply(false);
              if(persist) setBlockCollapsed(key,false);
            }
          });
        }
      }

      function ensureSmartSavesAlwaysExpanded(){
        const section=document.getElementById('smartSavesHomeTile');
        if(!section)return;
        section.classList.remove('is-collapsed','rudi-collapsible');
        delete section.dataset.collapseReady;
        delete section.dataset.collapseKey;
        section.querySelector('.smart-saves-home-head .block-collapse-button')?.remove();
        section.querySelectorAll('.rudi-collapse-body').forEach(wrapper=>{
          const inner=wrapper.querySelector(':scope > .rudi-collapse-body-inner');
          if(inner){
            const parent=wrapper.parentNode;
            while(inner.firstChild)parent.insertBefore(inner.firstChild,wrapper);
          }
          wrapper.remove();
        });
        try{
          const states=readBlockStates();
          if(Object.prototype.hasOwnProperty.call(states,'smart-saves-home')){
            delete states['smart-saves-home'];
            localStorage.setItem(blockStateStorageKey(),JSON.stringify(states));
          }
        }catch(_){}
      }

