      async function refreshAppDataNow({showButton=true}={}){
        const button=showButton?document.getElementById('settingsRefreshNow'):null;
        const original=button?.textContent||'Обновить сейчас';
        if(button){button.disabled=true;button.textContent='Обновляю…'}
        try{
          manualRefreshRequested=true;
          await refreshAfterResume();
          if(currentAppTab!=='home'){
            await Promise.allSettled([
              window.RUDI_CAR?.refresh?.(),
              window.RUDI_SMART_HOME?.refresh?.(),
              window.RUDI_SAVES?.load?.(),
              (currentConfig?.weather?loadWeather(currentConfig.weather):Promise.resolve())
            ]);
          }
          markDataSyncNow();
          if(button) button.textContent='Обновлено';
          setTimeout(()=>{if(button&&button.textContent==='Обновлено') button.textContent=original},900);
        }finally{
          if(button) button.disabled=false;
        }
      }

      async function clearLocalRuntimeCache(){
        const button=document.getElementById('settingsClearCache');
        const status=document.getElementById('settingsCacheStatus');
        if(button?.disabled) return;
        if(button) button.disabled=true;
        if(status) status.textContent='Очищаю временные файлы…';
        try{
          if('caches' in window){
            const keys=await caches.keys();
            await Promise.all(keys.filter(key=>String(key).startsWith('rudi-shell-')).map(key=>caches.delete(key)));
          }
          const localCacheMatchers=[
            /^rudi:market-ticker-cache:/,
            /^rudi-profile-cache-v1$/,
            /^rudi-config-cache-v1$/,
            /^rudi-recipe-cache-v1-/,
            /^rudi:date-ideas:v1:/
          ];
          const remove=[];
          for(let index=0;index<localStorage.length;index+=1){
            const key=String(localStorage.key(index)||'');
            if(localCacheMatchers.some(pattern=>pattern.test(key))) remove.push(key);
          }
          remove.forEach(key=>{try{localStorage.removeItem(key)}catch(_){}});
          if(status) status.textContent='Кэш очищен. Данные и настройки сохранены.';
          try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
        }catch(_){
          if(status) status.textContent='Не удалось полностью очистить кэш.';
          try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
        }finally{
          if(button) button.disabled=false;
        }
      }

      function updateContactSettingsUi(){
        const telegram=document.getElementById('settingsTelegramUsername');
        const phone=document.getElementById('settingsContactPhone');
        const status=document.getElementById('settingsContactStatus');
        if(!telegram&&!phone)return;
        const contact=ownProfileContact();
        if(telegram&&document.activeElement!==telegram)telegram.value=contact.telegram||'';
        if(phone&&document.activeElement!==phone)phone.value=contact.phone||'';
        if(status&&!status.dataset.persist)status.textContent='';
      }

      async function saveContactSettings(){
        const telegram=document.getElementById('settingsTelegramUsername');
        const phone=document.getElementById('settingsContactPhone');
        const button=document.getElementById('settingsContactSave');
        const status=document.getElementById('settingsContactStatus');
        if(!telegram||!phone||!currentActor)return;
        const username=normalizeContactTelegram(telegram.value);
        const normalizedPhone=normalizeContactPhone(phone.value);
        if(!username){
          if(status){status.textContent='Укажи Telegram-ник.';status.dataset.persist='1'}
          telegram.focus({preventScroll:true});return;
        }
        if(!/^\+\d{10,15}$/u.test(normalizedPhone)){
          if(status){status.textContent='Проверь номер телефона.';status.dataset.persist='1'}
          phone.focus({preventScroll:true});return;
        }
        if(button){button.disabled=true;button.textContent='Сохраняю…'}
        try{
          localStorage.setItem(contactTelegramStorageKey(),username);
          localStorage.setItem(contactPhoneStorageKey(),normalizedPhone);
          telegram.value=username;phone.value=normalizedPhone;
          markUiPreferencesChanged({syncSchemaVersion:9,contactTelegramUsername:username,contactPhone:normalizedPhone});
          const saved=await flushUiPreferencesToServer();
          if(!saved)throw new Error('contact-save-failed');
          await refreshStateBackup().catch(()=>{});
          syncProfileContactButtons();
          if(status){status.textContent='Сохранено';status.dataset.persist='1'}
          try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
        }catch(_){
          if(status){status.textContent='Не удалось сохранить.';status.dataset.persist='1'}
          try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
        }finally{
          if(button){button.disabled=false;button.textContent='Сохранить'}
          setTimeout(()=>{if(status){status.textContent='';delete status.dataset.persist}},1800);
        }
      }

      async function changePinFromSettings(){
        const current=document.getElementById('settingsCurrentPin');
        const next=document.getElementById('settingsNewPin');
        const repeat=document.getElementById('settingsNewPinRepeat');
        const button=document.getElementById('settingsPinSave');
        const status=document.getElementById('settingsPinStatus');
        if(!current||!next||!repeat||!button)return;
        const currentPin=String(current.value||'').trim();
        const newPin=String(next.value||'').trim();
        const repeated=String(repeat.value||'').trim();
        if(!/^\d{6}$/.test(currentPin)||!/^\d{6}$/.test(newPin)){
          if(status)status.textContent='PIN должен состоять из 6 цифр.';
          return;
        }
        if(newPin!==repeated){
          if(status)status.textContent='Новый PIN не совпадает.';
          return;
        }
        button.disabled=true;
        button.textContent='Сохраняю…';
        if(status)status.textContent='';
        try{
          await browserAuthRequest('change-pin',{currentPin,newPin});
          current.value='';next.value='';repeat.value='';
          if(status)status.textContent='PIN изменён.';
          try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
        }catch(error){
          const code=String(error?.message||'');
          if(status)status.textContent=code==='rudi-pin-invalid'?'Неверный текущий PIN.':'Не удалось сменить PIN.';
          try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
        }finally{
          button.disabled=false;
          button.textContent='Сменить PIN';
        }
      }

