      function setMoodChoicesOpen(open){
        const choices=document.getElementById('moodChoices');
        const trigger=document.getElementById('moodCurrentButton');
        if(!choices||!trigger)return;
        const next=Boolean(open);
        choices.hidden=!next;
        choices.classList.toggle('is-open',next);
        trigger.setAttribute('aria-expanded',next?'true':'false');
        trigger.classList.toggle('is-open',next);
        const prompt=document.getElementById('moodPrompt');
        if(prompt)prompt.hidden=next||Boolean(trigger.dataset.mood);
      }

      let moodReasonTimer=0;
      const MOOD_REASONS=[
        ['work','💼','Работа'],
        ['food','🍽️','Еда'],
        ['relationship','❤️','Отношения'],
        ['money','💰','Деньги'],
        ['health','🫶','Здоровье'],
        ['sport','🏃','Спорт'],
        ['sleep','😴','Сон'],
        ['other','✍️','Свой ответ']
      ];
      function setMoodReasonPromptBusy(box,busy){
        box?.querySelectorAll('button,input').forEach(item=>{item.disabled=Boolean(busy)});
      }
      function ensureMoodReasonPrompt(){
        let box=document.getElementById('moodReasonPrompt');if(box)return box;
        const own=document.getElementById(currentActor==='Диана'?'homeDianaTile':'homeRustamTile');if(!own)return null;
        box=document.createElement('div');box.id='moodReasonPrompt';box.className='mood-reason-prompt';box.hidden=true;
        box.innerHTML='<div class="mood-reason-title">Что повлияло?</div><div class="mood-reason-options"></div><form class="mood-reason-custom" hidden><input class="mood-reason-custom-input" type="text" maxlength="160" autocomplete="off" enterkeyhint="done" placeholder="Напишите свой ответ"><button class="mood-reason-custom-save" type="submit">Сохранить</button></form><button class="mood-reason-skip" type="button">Пропустить</button>';
        const options=box.querySelector('.mood-reason-options');
        for(const [key,emoji,label] of MOOD_REASONS){const button=document.createElement('button');button.type='button';button.dataset.moodReason=key;button.innerHTML='<span>'+emoji+'</span><b>'+label+'</b>';options.append(button)}
        box.addEventListener('click',async event=>{
          const button=event.target.closest('[data-mood-reason]');if(!button)return;
          const reason=String(button.dataset.moodReason||'');
          if(reason==='other'){
            clearTimeout(moodReasonTimer);
            const form=box.querySelector('.mood-reason-custom'),input=box.querySelector('.mood-reason-custom-input');
            if(form)form.hidden=false;
            requestAnimationFrame(()=>input?.focus?.({preventScroll:true}));
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
            return;
          }
          setMoodReasonPromptBusy(box,true);
          try{await moodRequest('reason','',{reason});hideMoodReasonPrompt();try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}}
          catch(_){setMoodReasonPromptBusy(box,false);try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}}
        });
        box.querySelector('.mood-reason-custom').addEventListener('submit',async event=>{
          event.preventDefault();
          const input=box.querySelector('.mood-reason-custom-input'),reasonText=String(input?.value||'').trim();
          if(!reasonText){input?.focus?.();return}
          setMoodReasonPromptBusy(box,true);
          try{await moodRequest('reason','',{reason:'other',reasonText});hideMoodReasonPrompt();try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}}
          catch(_){setMoodReasonPromptBusy(box,false);input?.focus?.();try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}}
        });
        box.querySelector('.mood-reason-skip').addEventListener('click',hideMoodReasonPrompt);
        const details=own.querySelector('.profile-person-details');
        const host=details?.parentNode||own;
        if(box.parentNode!==host)host.insertBefore(box,details&&details.parentNode===host?details:null);
        else if(details&&details.parentNode===host&&box.nextSibling!==details)host.insertBefore(box,details);
        return box;
      }
      function hideMoodReasonPrompt(){clearTimeout(moodReasonTimer);const box=document.getElementById('moodReasonPrompt');if(box){const form=box.querySelector('.mood-reason-custom'),input=box.querySelector('.mood-reason-custom-input');input?.blur?.();if(input)input.value='';if(form)form.hidden=true;setMoodReasonPromptBusy(box,false);box.hidden=true}}
      function showMoodReasonPrompt(){
        const box=ensureMoodReasonPrompt();if(!box)return;
        const own=document.getElementById(currentActor==='Диана'?'homeDianaTile':'homeRustamTile');
        if(own?.classList.contains('is-collapsed')) own.querySelector('.block-collapse-button')?.click();
        clearTimeout(moodReasonTimer);
        box.hidden=false;
        box.scrollIntoView?.({block:'nearest',behavior:'smooth'});
        moodReasonTimer=setTimeout(hideMoodReasonPrompt,12000);
      }

      function bindMoodPickerControls(){
        const currentButton=document.getElementById('moodCurrentButton');
        if(currentButton&&currentButton.dataset.moodPickerBound!=='1'){
          currentButton.dataset.moodPickerBound='1';
          let moodLongPressTimer=0;
          let moodLongPressActivated=false;
          const cancelMoodLongPress=()=>{clearTimeout(moodLongPressTimer);moodLongPressTimer=0};
          currentButton.addEventListener('pointerdown',event=>{
            if(event.pointerType==='mouse'&&event.button!==0) return;
            moodLongPressActivated=false;
            cancelMoodLongPress();
            moodLongPressTimer=setTimeout(()=>{
              moodLongPressActivated=true;
              setMoodChoicesOpen(false);
              if(window.RUDI_MOOD_HISTORY?.open) window.RUDI_MOOD_HISTORY.open();
              else document.getElementById('moodHistoryButton')?.click();
              try{tg?.HapticFeedback?.impactOccurred?.('medium')}catch(_){}
            },600);
          });
          currentButton.addEventListener('pointerup',cancelMoodLongPress);
          currentButton.addEventListener('pointercancel',cancelMoodLongPress);
          currentButton.addEventListener('pointerleave',cancelMoodLongPress);
          currentButton.addEventListener('contextmenu',event=>event.preventDefault());
          currentButton.addEventListener('click',(event)=>{
            event.preventDefault();
            event.stopPropagation();
            if(moodLongPressActivated){moodLongPressActivated=false;return;}
            const choices=document.getElementById('moodChoices');
            setMoodChoicesOpen(Boolean(choices?.hidden));
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
          });
        }
        const prompt=document.getElementById('moodPrompt');
        if(prompt&&prompt.dataset.moodPickerBound!=='1'){
          prompt.dataset.moodPickerBound='1';
          prompt.setAttribute('role','button');
          prompt.tabIndex=0;
          const openPicker=(event)=>{
            event?.preventDefault?.();
            event?.stopPropagation?.();
            setMoodChoicesOpen(true);
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
          };
          prompt.addEventListener('click',openPicker);
          prompt.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' ')openPicker(event)});
        }

        moodButtons().forEach(button=>{
          if(button.dataset.moodPickerBound==='1')return;
          button.dataset.moodPickerBound='1';
          button.addEventListener('click',async(event)=>{
            event.preventDefault();
            event.stopPropagation();
            const mood=button.dataset.mood;
            const buttons=moodButtons();
            buttons.forEach(item=>item.disabled=true);
            selectOwnMood(mood);
            setMoodChoicesOpen(false);
            showMoodMessage(mood);
            try{
              const payload=await moodRequest('set',mood);
              renderDailyMood(payload);
              showMoodReasonPrompt();
              setTimeout(()=>loadActivityJournal({silent:true}),180);
              try{
                if(mood==='joy'||mood==='love') tg?.HapticFeedback?.notificationOccurred?.('success');
                else tg?.HapticFeedback?.selectionChanged?.();
              }catch(_){}
            }catch(_){
              await refreshDailyMood();
              try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
            }finally{
              buttons.forEach(item=>item.disabled=false);
            }
          });
        });
      }

      function selectOwnMood(value){
        const mood=String(value||'');
        const meta=MOOD_META[mood]||null;
        const trigger=document.getElementById('moodCurrentButton');
        const emoji=document.getElementById('moodCurrentEmoji');
        if(emoji)emoji.textContent=meta?.emoji||'🙂';
        if(trigger){
          trigger.dataset.mood=mood;
          trigger.hidden=false;
          trigger.classList.toggle('is-empty',!meta);
          trigger.setAttribute('aria-label',meta?'Текущее настроение: '+meta.label+'. Изменить':'Выбрать настроение');
          trigger.title=meta?.label||'Выбрать настроение';
        }
        moodButtons().forEach(button=>{
          const selected=button.dataset.mood===mood;
          button.classList.toggle('selected',selected);
          button.setAttribute('aria-pressed',selected?'true':'false');
          button.hidden=Boolean(meta&&selected);
        });
        const prompt=document.getElementById('moodPrompt');
        if(prompt)prompt.hidden=Boolean(meta);
      }

      const MOOD_REASON_META={
        work:['💼','Работа'],
        food:['🍽️','Еда'],
        relationship:['❤️','Отношения'],
        money:['💰','Деньги'],
        health:['🫶','Здоровье'],
        sport:['🏃','Спорт'],
        fatigue:['😩','Усталость'],
        sleep:['😴','Сон'],
        fasting:['🥣','Питание'],
        other:['✍️','Свой ответ']
      };

      function partnerMoodReasonText(entry){
        const samples=Array.isArray(entry?.samples)?entry.samples:[];
        const latest=[...samples].reverse().find(sample=>String(sample?.mood||'')===String(entry?.mood||''))||samples[samples.length-1]||null;
        const reason=String(latest?.reason||'').trim();
        const reasonText=String(latest?.reasonText||'').trim();
        const meta=MOOD_REASON_META[reason];
        const label=reason==='other'?reasonText:(meta?(meta[0]+' '+meta[1]):'');
        const stamp=String(latest?.updatedAt||entry?.updatedAt||'').trim();
        const timestamp=stamp?new Date(stamp):null;
        const time=timestamp&&Number.isFinite(timestamp.getTime())?new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(timestamp):'';
        return label&&time?label+' · '+time:(label||time);
      }

      let partnerMoodReasonTimer=0;
      function hidePartnerMoodReason(){
        clearTimeout(partnerMoodReasonTimer);
        document.getElementById('partnerMoodReasonPopover')?.remove();
      }
      function showPartnerMoodReason(holder){
        if(!holder||holder.hidden) return;
        const text=String(holder.dataset.moodReasonText||'').trim();
        if(!text)return;
        const existing=document.getElementById('partnerMoodReasonPopover');
        if(existing){existing.remove();if(existing.dataset.reasonText===text)return}
        const popover=document.createElement('div');
        popover.id='partnerMoodReasonPopover';
        popover.className='partner-mood-reason-popover';
        popover.dataset.reasonText=text;
        popover.textContent=text;
        document.body.appendChild(popover);
        const rect=holder.getBoundingClientRect();
        const width=Math.min(260,Math.max(150,popover.getBoundingClientRect().width||180));
        const left=Math.max(10,Math.min(window.innerWidth-width-10,rect.right-width));
        const top=Math.min(window.innerHeight-60,rect.bottom+8);
        popover.style.left=left+'px';
        popover.style.top=top+'px';
        clearTimeout(partnerMoodReasonTimer);
        partnerMoodReasonTimer=setTimeout(hidePartnerMoodReason,4200);
        try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
      }

      function renderPartnerMood(value,partner,entry=null){
        const label=document.getElementById('partnerMoodLabel');
        const holder=document.getElementById('partnerMoodValue');
        const empty=document.getElementById('partnerMoodEmpty');
        const mood=String(value||'');
        const normalizedMood=mood==='fear'?'boredom':mood;
        const visiblePartner=partnerProfileName||partner||'Партнёр';
        const hasMood=['sadness','boredom','neutral','fatigue','anger','joy','love'].includes(normalizedMood);
        if(label) label.textContent='';
        holder.dataset.mood=normalizedMood;
        holder.dataset.moodReasonText=partnerMoodReasonText(entry);
        holder.hidden=!hasMood;
        if(!hasMood) hidePartnerMoodReason();
        holder.querySelectorAll('[data-partner-mood]').forEach(icon=>{
          icon.hidden=icon.dataset.partnerMood!==normalizedMood;
        });
        if(empty) empty.hidden=true;
        holder.setAttribute('role','button');
        holder.tabIndex=hasMood?0:-1;
        holder.setAttribute(
          'aria-label',
          visiblePartner+': '+(
            mood==='sadness'?'грусть':(mood==='boredom'||mood==='fear')?'скука':mood==='neutral'?'нейтрально':mood==='fatigue'?'усталость':mood==='anger'?'злость':mood==='joy'?'радость':mood==='love'?'любовь':'настроение ещё не выбрано'
          )+'. Нажмите, чтобы увидеть подробности.'
        );
        if(holder.dataset.moodReasonBound!=='1'){
          holder.dataset.moodReasonBound='1';
          holder.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();showPartnerMoodReason(holder)});
          holder.addEventListener('keydown',event=>{if(!['Enter',' '].includes(event.key))return;event.preventDefault();showPartnerMoodReason(holder)});
        }
      }

      function renderDailyMood(payload){
        homeDashboardState.moods=payload||null;
        const mine=String(payload?.mine?.mood||'');
        const partnerMood=String(payload?.partnerMood?.mood||'');
        selectOwnMood(mine);
        renderPartnerMood(partnerMood,String(payload?.partner||''),payload?.partnerMood);
        renderHomeDashboard();
      }

      async function moodRequest(operation,mood='',extra={}){
        const backupContext=backupRequestContext();
        const response=await fetch('/api/mood',{
          method:'POST',
          headers:{'Content-Type':'application/json'},
          body:JSON.stringify({initData:tg?.initData||'',backupToken:backupContext.token,operation,mood,...(extra&&typeof extra==='object'?extra:{})}),
          cache:'no-store'
        });
        const payload=await response.json().catch(()=>({}));
        if(!response.ok) throw new Error(payload.error||'mood');
        if(payload.backupToken) await storeStateBackupToken(payload.backupToken,backupContext);
        return payload;
      }

      async function refreshDailyMood(){
        if(!currentActor) return;
        try{
          const payload=await moodRequest('get');
          currentMoodDateKey=String(payload?.date||todayState().key);
          renderDailyMood(payload);
        }catch(_){
          renderPartnerMood('',currentActor==='Рустам'?'Диана':'Рустам');
        }
      }

      function resetMoodForNewDay(){
        const nextKey=todayState().key;
        if(!currentMoodDateKey){
          currentMoodDateKey=nextKey;
          return false;
        }
        if(nextKey===currentMoodDateKey) return false;

        currentMoodDateKey=nextKey;
        clearTimeout(moodMessageTimer);
        const message=document.getElementById('moodMessage');
        if(message){
          message.classList.remove('show');
          message.textContent='';
          delete message.dataset.mood;
        }
        setMoodChoicesOpen(false);
        hideMoodReasonPrompt();
        selectOwnMood('');
        renderPartnerMood('',currentActor==='Рустам'?'Диана':'Рустам');
        refreshDailyMood();
        return true;
      }

      function showMoodMessage(mood){
        const message=document.getElementById('moodMessage');
        const messages=moodMessagesConfig||fallback.moodMessages;
        const pool=Array.isArray(messages?.[mood])&&messages[mood].length
          ?messages[mood]
          :fallback.moodMessages[mood];
        if(!message||!pool?.length) return;
        clearTimeout(moodMessageTimer);
        message.textContent=randomItem(pool);
        message.dataset.mood=mood;
        message.classList.remove('show');
        void message.offsetWidth;
        message.classList.add('show');
        moodMessageTimer=setTimeout(()=>{
          message.classList.remove('show');
          setTimeout(()=>{
            if(!message.classList.contains('show')){
              message.textContent='';
              delete message.dataset.mood;
            }
          },260);
        },7000);
      }

      function setupStreakAndMood(config){
        currentMoodDateKey=todayState().key;
        moodMessagesConfig=config?.moodMessages||fallback.moodMessages;
        renderPartnerMood('',currentActor==='Рустам'?'Диана':'Рустам');
        const prompt=document.getElementById('moodPrompt');
        if(prompt)prompt.hidden=false;

        bindMoodPickerControls();

        if(currentAppTab==='home'){
          ensureHomeBootstrap()
            .then(()=>refreshDailyMood())
            .catch(()=>refreshDailyMood());
        }
      }

      if(document.readyState==='loading'){
        document.addEventListener('DOMContentLoaded',bindMoodPickerControls,{once:true});
      }else{
        bindMoodPickerControls();
      }

      async function openCinemaPremieresTopic(){
        const button=document.getElementById('cinemaPremieresButton');
        if(!button||button.dataset.loading==='1') return;
        button.dataset.loading='1';
        button.disabled=true;
        try{
          const response=await fetch('/api/partner-message?rudiAction=cinema-topic-link',{
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({initData:tg?.initData||''}),
            cache:'no-store'
          });
          const payload=await response.json().catch(()=>({}));
          if(!response.ok||!payload.ok||!payload.url) throw new Error(payload.error||'cinema-topic-link');
          const url=String(payload.url);
          try{
            if(tg?.openTelegramLink) tg.openTelegramLink(url);
            else if(tg?.openLink) tg.openLink(url);
            else window.open(url,'_blank','noopener,noreferrer');
          }catch(_){
            window.open(url,'_blank','noopener,noreferrer');
          }
          try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
        }catch(_){
          button.classList.add('is-error');
          setTimeout(()=>button.classList.remove('is-error'),1200);
          try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
        }finally{
          button.dataset.loading='0';
          button.disabled=false;
        }
      }

      function setupCinemaPremieresButton(){
        const button=document.getElementById('cinemaPremieresButton');
        if(!button||button.dataset.bound==='1') return;
        button.dataset.bound='1';
        button.addEventListener('click',event=>{
          event.preventDefault();
          event.stopPropagation();
          openCinemaPremieresTopic();
        });
      }

      function feedSeenStorageKey(){
        return 'rudi-feed-seen-v1-'+(currentActor==='Диана'?'diana':'rustam');
      }

      function setFeedBadge(visible){
        const badge=document.getElementById('feedTabBadge');
        const fresh=document.getElementById('feedFreshBadge');
        if(badge) badge.hidden=!visible;
        if(fresh) fresh.hidden=!visible;
        queueAppIconBadgeSync();
      }

      function feedSeenVersion(){
        try{return String(localStorage.getItem(feedSeenStorageKey())||'')}catch(_){return ''}
      }

      function markFeedSeen(version){
        const value=String(version||'').trim();
        if(value){
          try{localStorage.setItem(feedSeenStorageKey(),value)}catch(_){}
        }
        setFeedBadge(false);
      }

      function feedDateKey(value){
        const date=value instanceof Date?value:new Date(value||Date.now());
        if(Number.isNaN(date.getTime())) return '';
        const parts=new Intl.DateTimeFormat('en-CA',{
          timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'
        }).formatToParts(date);
        const map=Object.fromEntries(parts.map(part=>[part.type,part.value]));
        return map.year+'-'+map.month+'-'+map.day;
      }

      function feedTimeLabel(value){
        const date=new Date(String(value||''));
        if(Number.isNaN(date.getTime())) return '';
        const time=new Intl.DateTimeFormat('ru-RU',{
          hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:TZ
        }).format(date);
        if(feedDateKey(date)===feedDateKey(new Date())) return 'Сегодня · '+time;
        const day=new Intl.DateTimeFormat('ru-RU',{
          day:'numeric',month:'long',timeZone:TZ
        }).format(date);
        return day+' · '+time;
      }

      function normalizeFeedSource(value){
        return String(value||'')
          .trim()
          .replace(/\\r\\n|\\n|\\r/g,'\n')
          .replace(/\r\n?/g,'\n')
          .replace(/\n{3,}/g,'\n\n');
      }

      function cleanFeedPartSource(value,name=''){
        const lines=normalizeFeedSource(value).split('\n');
        const filtered=[];
        for(let index=0;index<lines.length;index+=1){
          const line=lines[index];
          const plain=line.replace(/<[^>]*>/g,'').trim();
          if(index===0&&(
            (name==='concerts'&&/Поп и хип-хоп концерты/iu.test(plain))||
            (name==='standup'&&/Stage StandUp Club/iu.test(plain))||
            (name==='cinema'&&/Кинопремьеры/iu.test(plain))
          )) continue;
          filtered.push(line);
        }
        return filtered.join('\n').replace(/^\s+|\s+$/g,'').replace(/\n{3,}/g,'\n\n');
      }

      function normalizeFeedHtml(value,name=''){
        let raw=cleanFeedPartSource(value,name);
        if(name==='standup'||name==='cinema'){
          raw=raw.replace(/\n(?=\d+\.\s)/g,'\n\n');
        }
        return raw.replace(/\n/g,'<br>');
      }

      function sanitizeFeedHtml(value,name=''){
        const template=document.createElement('template');
        template.innerHTML=normalizeFeedHtml(value,name);
        const allowed=new Set(['B','STRONG','I','EM','A','BR','P','UL','OL','LI','SPAN']);
        for(const element of [...template.content.querySelectorAll('*')]){
          if(!allowed.has(element.tagName)){
            element.replaceWith(document.createTextNode(element.textContent||''));
            continue;
          }
          for(const attr of [...element.attributes]){
            if(element.tagName==='A'&&attr.name==='href') continue;
            element.removeAttribute(attr.name);
          }
          if(element.tagName==='A'){
            const href=String(element.getAttribute('href')||'').trim();
            if(!/^https?:\/\//i.test(href)){
              element.replaceWith(document.createTextNode(element.textContent||''));
              continue;
            }
            element.target='_blank';
            element.rel='noopener noreferrer';
          }
        }
        return template.content;
      }

      function feedDomIds(name){
        return {
          concerts:['feedConcertsBody','feedConcertsMeta','feedConcertsCard','feedConcertsNew'],
          standup:['feedStandupBody','feedStandupMeta','feedStandupCard','feedStandupNew'],
          cinema:['feedCinemaBody','feedCinemaMeta','feedCinemaCard','feedCinemaNew']
        }[name]||[];
      }

      function feedLineData(line){
        const template=document.createElement('template');
        template.innerHTML=String(line||'');
        const anchor=template.content.querySelector('a[href]');
        const href=String(anchor?.getAttribute('href')||'').trim();
        const text=String(template.content.textContent||'').replace(/\s+/g,' ').trim();
        return {text,href:/^https?:\/\//i.test(href)?href:''};
      }

      function cleanEventDetail(value){
        return String(value||'')
          .replace(/\s*\|\s*/g,' · ')
          .replace(/·\s*,/g,'· ')
          .replace(/\s+,/g,',')
          .replace(/\s{2,}/g,' ')
          .trim();
      }

      function parseFeedEventItems(value,name){
        const lines=normalizeFeedSource(value).split('\n');
        const items=[];
        let current=null;
        const push=()=>{
          if(current?.title) items.push(current);
          current=null;
        };
        for(const rawLine of lines){
          const row=feedLineData(rawLine);
          const text=row.text;
          if(!text) continue;
          if(
            /^(?:🎤\s*)?Поп и хип-хоп концерты$/iu.test(text)||
            /^(?:🎙\s*)?Stage StandUp Club$/iu.test(text)||
            /^📅/u.test(text)||
            /^Найдено событий\/сеансов/iu.test(text)
          ) continue;
          const numbered=text.match(/^\d+\.\s*(.+)$/u);
          if(numbered){
            push();
            current={title:numbered[1].trim(),details:[],href:''};
            continue;
          }
          if(!current) continue;
          if(row.href){
            current.href=row.href;
            continue;
          }
          if(/^(Подробнее|Официальная страница)\s*→?$/iu.test(text)) continue;
          current.details.push(cleanEventDetail(text));
        }
        push();
        return items;
      }

      function stripFeedEventDetailIcon(value){
        return String(value||'')
          .replace(/^[\s🎵🎶🎤🎙🕒⏰🕐📍🎟🎫💳🔞\uFE0F]+/u,'')
          .trim();
      }

      function feedEventDisplay(item,name){
        const result={time:'',place:'',meta:[]};
        const details=Array.isArray(item?.details)?item.details:[];
        for(const value of details){
          const original=cleanEventDetail(value);
          if(!original) continue;
          if(name==='standup'&&/(?:^|\s)18\+(?:$|\s|[·,|])/u.test(original)) continue;

          const isPlace=/^📍/u.test(original);
          const text=stripFeedEventDetailIcon(original);
          if(!text) continue;

          const time=text.match(/(?:^|\s)(\d{1,2}):(\d{2})(?:\s|$)/u);
          if(time&&!result.time){
            result.time=String(time[1]).padStart(2,'0')+':'+time[2];
            const rest=text.replace(time[0],' ').replace(/\s{2,}/g,' ').trim();
            if(rest) result.meta.push(rest);
            continue;
          }

          if(isPlace&&!result.place){
            result.place=text;
            continue;
          }

          if(
            !result.place
            &&!/(₽|руб(?:\.|лей|ля)?|от\s*\d)/iu.test(text)
            &&/(театр|клуб|дворец|зал|бар|центр|stage|levelup|ритмы|club|standup)/iu.test(text)
          ){
            result.place=text;
            continue;
          }

          result.meta.push(text);
        }
        result.meta=[...new Set(result.meta.filter(Boolean))];
        return result;
      }

      function feedReactionHash(value){
        let hash=2166136261;
        const text=String(value||'');
        for(let index=0;index<text.length;index+=1){
          hash^=text.charCodeAt(index);
          hash=Math.imul(hash,16777619);
        }
        return (hash>>>0).toString(36);
      }

      function feedItemReactionTarget(name,item,index=0){
        const title=String(item?.title||'').trim();
        const href=String(item?.href||item?.kinopoiskUrl||'').trim();
        const releaseDate=String(item?.releaseDate||'').trim();
        const details=Array.isArray(item?.details)?item.details.join('|'):'';
        const sources=Array.isArray(item?.sources)?item.sources.join('|'):'';
        const source=[name,title,href,releaseDate,details,sources,index].join('||');
        return {type:'feed',key:'item:'+String(name||'feed')+':'+feedReactionHash(source)};
      }

      function createFeedItemReaction(target,label){
        const hash=feedReactionHash(reactionTargetId(target));
        const buttonId='feedItemLike_'+hash;
        const namesId='feedItemLikedBy_'+hash;
        const strip=document.createElement('div');
        strip.className='reaction-strip feed-item-reaction';

        const button=document.createElement('button');
        button.id=buttonId;
        button.className='reaction-button';
        button.type='button';
        button.setAttribute('aria-label','Поставить лайк: '+String(label||'событие'));
        button.setAttribute('aria-pressed','false');
        button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.6 10.55 19.28C5.4 14.6 2 11.5 2 7.7 2 4.6 4.42 2.2 7.5 2.2c1.74 0 3.41.81 4.5 2.08A6.02 6.02 0 0 1 16.5 2.2C19.58 2.2 22 4.6 22 7.7c0 3.8-3.4 6.9-8.55 11.59L12 20.6Z"/></svg>';

        const names=document.createElement('span');
        names.id=namesId;
        names.className='reaction-names';
        strip.append(button,names);

        currentFeedReactionTargets.push(target);
        currentFeedReactionBindings.set(reactionTargetId(target),{buttonId,namesId});
        bindReactionElement(button,names,()=>target);
        return strip;
      }

      function resolveFeedEventHref(item,name){
        const href=String(item?.href||'').trim();
        if(name!=='standup') return href;
        if(/gostandup\.ru\/spb\/events\/[^/?#]+/i.test(href)) return href;
        const title=String(item?.title||'').trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е');
        const known=[
          [/лямур\s+с\s+нидалем/u,'https://gostandup.ru/spb/events/lyamur_s_nidalem'],
          [/комики\s+проездом/u,'https://gostandup.ru/spb/events/komiki_proezdom'],
          [/дневн[а-я]*\s+микрофон/u,'https://gostandup.ru/spb/events/dnevnoy_mikrofon'],
          [/(?:стендап\s+для\s+детей|семейное\s+комедийное\s+шоу\s+выходного\s+дня)/u,'https://gostandup.ru/spb/events/stendap_dlya_detey_v_sankt_peterburge']
        ];
        for(const [pattern,url] of known){
          if(pattern.test(title)) return url;
        }
        return href;
      }

      function renderFeedEventItems(body,items,name){
        const list=document.createElement('div');
        list.className='feed-event-list';
        items.forEach((item,index)=>{
          const view=feedEventDisplay(item,name);
          const eventHref=resolveFeedEventHref(item,name);
          const isLink=/^https?:\/\//i.test(eventHref);
          const card=document.createElement('article');
          card.className='feed-event-item'+(isLink?' feed-event-item-link':'');
          if(isLink){
            card.tabIndex=0;
            card.setAttribute('role','link');
            card.addEventListener('click',event=>{
              if(event.target?.closest?.('button,a')) return;
              if(tg?.openLink){
                try{tg.openLink(eventHref)}catch(_){window.open(eventHref,'_blank','noopener,noreferrer')}
              }else{
                window.open(eventHref,'_blank','noopener,noreferrer');
              }
            });
            card.addEventListener('keydown',event=>{
              if(event.key!=='Enter'&&event.key!==' ') return;
              event.preventDefault();
              if(tg?.openLink){
                try{tg.openLink(eventHref)}catch(_){window.open(eventHref,'_blank','noopener,noreferrer')}
              }else{
                window.open(eventHref,'_blank','noopener,noreferrer');
              }
            });
          }

          const time=document.createElement('time');
          time.className='feed-event-time';
          time.textContent=view.time||'—';
          if(view.time) time.dateTime=view.time;

          const copy=document.createElement('div');
          copy.className='feed-event-copy';

          const title=document.createElement('strong');
          title.className='feed-event-title';
          title.textContent=item.title;
          copy.appendChild(title);

          if(view.place){
            const place=document.createElement('div');
            place.className='feed-event-place';
            place.textContent=view.place;
            copy.appendChild(place);
          }

          if(view.meta.length){
            const meta=document.createElement('div');
            meta.className='feed-event-meta';
            meta.textContent=view.meta.join(' · ');
            copy.appendChild(meta);
          }

          const target=feedItemReactionTarget(name,item,index);
          copy.appendChild(createFeedItemReaction(target,item.title||'событие'));
          card.append(time,copy);

          if(isLink){
            const chevron=document.createElement('span');
            chevron.className='feed-event-chevron';
            chevron.setAttribute('aria-hidden','true');
            chevron.textContent='›';
            card.appendChild(chevron);
          }

          list.appendChild(card);
        });
        body.appendChild(list);
      }

      function cinemaPosterUrl(value){
        const url=String(value||'').trim();
        return /^https:\/\//i.test(url)?('/api/poster-proxy?url='+encodeURIComponent(url)):'';
      }

      function cinemaDateLabel(value){
        const date=String(value||'').trim();
        if(!/^\d{4}-\d{2}-\d{2}$/u.test(date)) return '';
        const parsed=new Date(date+'T12:00:00Z');
        if(Number.isNaN(parsed.getTime())) return '';
        return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',timeZone:TZ}).format(parsed);
      }

      function renderFeedCinemaItems(body,items){
        const track=document.createElement('div');
        track.className='feed-cinema-track';
        items.forEach((item,index)=>{
          const card=document.createElement('article');
          card.className='feed-movie-card';

          const posterWrap=document.createElement('div');
          posterWrap.className='feed-movie-poster';
          const poster=cinemaPosterUrl(item?.posterUrl);
          if(poster){
            const image=document.createElement('img');
            image.src=poster;
            image.alt='';
            image.loading='lazy';
            image.decoding='async';
            image.addEventListener('error',()=>posterWrap.classList.add('is-fallback'),{once:true});
            posterWrap.appendChild(image);
          }else{
            posterWrap.classList.add('is-fallback');
          }

          const copy=document.createElement('div');
          copy.className='feed-movie-copy';
          const title=document.createElement('strong');
          title.className='feed-movie-title';
          title.textContent=String(item?.title||'Фильм');
          const meta=document.createElement('div');
          meta.className='feed-movie-meta';
          const date=cinemaDateLabel(item?.releaseDate);
          const sources=(Array.isArray(item?.sources)?item.sources:[]).filter(Boolean).join(', ');
          meta.textContent=[date?('Премьера '+date):'',sources].filter(Boolean).join(' · ');
          copy.append(title,meta);

          const sourceUrl=(Array.isArray(item?.sourceUrls)?item.sourceUrls:[]).find(row=>/^https?:\/\//i.test(String(row?.url||'')))?.url;
          const href=String(sourceUrl||item?.kinopoiskUrl||'').trim();
          if(/^https?:\/\//i.test(href)){
            const link=document.createElement('a');
            link.className='feed-movie-link';
            link.href=href;
            link.target='_blank';
            link.rel='noopener noreferrer';
            link.textContent='Открыть →';
            copy.appendChild(link);
          }

          const target=feedItemReactionTarget('cinema',{...item,href},index);
          copy.appendChild(createFeedItemReaction(target,item?.title||'фильм'));
          card.append(posterWrap,copy);
          track.appendChild(card);
        });
        body.appendChild(track);
      }

      function parseLegacyCinemaItems(value){
        const lines=normalizeFeedSource(value).split('\n');
        const items=[];
        let current=null;
        const push=()=>{
          if(!current?.title) return;
          current.sources=current.sources.filter(Boolean);
          items.push(current);
          current=null;
        };
        for(const rawLine of lines){
          const row=feedLineData(rawLine);
          const text=row.text;
          if(!text) continue;
          if(/Кинопремьеры/iu.test(text)&&!/^\d+\./u.test(text)) continue;
          const numbered=text.match(/^\d+\.\s*(.+)$/u);
          if(numbered){
            push();
            current={
              title:numbered[1].trim(),
              posterUrl:'',
              releaseDate:'',
              sources:[],
              sourceUrls:[],
              kinopoiskUrl:row.href||''
            };
            continue;
          }
          if(!current) continue;
          if(row.href){
            if(!current.kinopoiskUrl) current.kinopoiskUrl=row.href;
            continue;
          }
          if(!/^(Подробнее|Открыть|Источник)\s*→?$/iu.test(text)){
            current.sources.push(cleanEventDetail(text));
          }
        }
        push();
        return items;
      }

      function feedSectionSeenStorageKey(){
        return 'rudi-feed-card-seen-v1-'+(currentActor==='Диана'?'diana':'rustam');
      }

      function readFeedSectionSeen(){
        try{
          const value=JSON.parse(localStorage.getItem(feedSectionSeenStorageKey())||'{}');
          return value&&typeof value==='object'?value:{};
        }catch(_){return {}}
      }

      function writeFeedSectionSeen(value){
        try{localStorage.setItem(feedSectionSeenStorageKey(),JSON.stringify(value||{}))}catch(_){}
      }

      let feedCardObserver=null;
      const feedCardSeenTimers=new Map();

      function markFeedCardSeen(name,version){
        if(!name||!version) return;
        const seen=readFeedSectionSeen();
        if(seen[name]===version) return;
        seen[name]=version;
        writeFeedSectionSeen(seen);
        const [, ,cardId,newId]=feedDomIds(name);
        document.getElementById(cardId)?.classList.remove('is-new');
        const badge=document.getElementById(newId);
        if(badge) badge.hidden=true;
      }

      function observeFeedCards(){
        feedCardObserver?.disconnect?.();
        for(const timer of feedCardSeenTimers.values()) clearTimeout(timer);
        feedCardSeenTimers.clear();
        if(typeof IntersectionObserver!=='function') return;
        feedCardObserver=new IntersectionObserver((entries)=>{
          for(const entry of entries){
            const card=entry.target;
            const name=String(card.dataset.feedCard||'');
            const version=String(card.dataset.feedVersion||'');
            if(entry.isIntersecting&&entry.intersectionRatio>=.55&&card.classList.contains('is-new')){
              if(feedCardSeenTimers.has(name)) continue;
              const timer=setTimeout(()=>{
                if(card.classList.contains('is-new')) markFeedCardSeen(name,version);
                feedCardSeenTimers.delete(name);
              },700);
              feedCardSeenTimers.set(name,timer);
            }else if(feedCardSeenTimers.has(name)){
              clearTimeout(feedCardSeenTimers.get(name));
              feedCardSeenTimers.delete(name);
            }
          }
        },{threshold:[.55]});
        document.querySelectorAll('.feed-card.is-new').forEach(card=>feedCardObserver.observe(card));
      }

      function setFeedCardFresh(name,section,hasContent,payload){
        const [, ,cardId,newId]=feedDomIds(name);
        const card=document.getElementById(cardId);
        const badge=document.getElementById(newId);
        if(!card) return;
        const version=name+':'+String(section?.updatedAt||payload?.date||payload?.version||'');
        card.dataset.feedVersion=version;
        const seen=readFeedSectionSeen();
        const fresh=Boolean(hasContent&&version&&seen[name]!==version);
        card.classList.toggle('is-new',fresh);
        if(badge) badge.hidden=!fresh;
      }

      function sectionMetaText(name,section){
        const label=feedTimeLabel(section?.updatedAt);
        if(!label) return name==='cinema'?'До следующей подборки':'Актуально';
        return name==='cinema'?'Подборка · '+label:label;
      }

      function eventEmptyText(name,value){
        const text=feedLineData(normalizeFeedSource(value).replace(/\n/g,' ')).text;
        return name==='concerts'
          ?/не найден|нет концертов/iu.test(text)
          :/не найден|нет событий/iu.test(text);
      }

      function renderFeedSection(name,section,partsOverride,payload){
        const [bodyId,metaId,cardId]=feedDomIds(name);
        const body=document.getElementById(bodyId);
        const meta=document.getElementById(metaId);
        const card=document.getElementById(cardId);
        if(!body) return {name,count:0,hasContent:false,firstTime:9999};
        body.replaceChildren();

        const parts=(Array.isArray(partsOverride)?partsOverride:Array.isArray(section?.parts)?section.parts:[]).filter(Boolean);
        const structuredItems=Array.isArray(section?.items)?section.items.filter(Boolean):[];
        const raw=String(parts[0]||'');
        let count=0;
        let hasContent=Boolean(parts.length||structuredItems.length);
        let firstTime=9999;

        if(name==='concerts'||name==='standup'){
          const items=raw?parseFeedEventItems(raw,name):[];
          count=items.length;
          for(const item of items){
            const time=item.details.map(value=>value.match(/(?:^|\s)(\d{1,2}):(\d{2})(?:\s|$)/u)).find(Boolean);
            if(time){
              const minutes=Number(time[1])*60+Number(time[2]);
              if(Number.isFinite(minutes)) firstTime=Math.min(firstTime,minutes);
            }
          }
          if(items.length){
            renderFeedEventItems(body,items,name);
          }else if(!raw||eventEmptyText(name,raw)){
            hasContent=false;
            const empty=document.createElement('div');
            empty.className='feed-empty';
            empty.textContent=name==='concerts'?'На сегодня концертов не найдено.':'На сегодня событий Stand Up не найдено.';
            body.appendChild(empty);
          }else{
            const part=document.createElement('div');
            part.className='feed-part';
            part.dataset.feedKind=name;
            part.appendChild(sanitizeFeedHtml(raw,name));
            body.appendChild(part);
          }
        }else if(name==='cinema'){
          const cinemaItems=structuredItems.length?structuredItems:parseLegacyCinemaItems(raw);
          if(cinemaItems.length){
            count=cinemaItems.length;
            renderFeedCinemaItems(body,cinemaItems);
          }else if(parts.length){
            count=parts.length;
            for(const value of parts){
              const part=document.createElement('div');
              part.className='feed-part';
              part.dataset.feedKind=name;
              part.appendChild(sanitizeFeedHtml(value,name));
              body.appendChild(part);
            }
          }else{
            hasContent=false;
            const empty=document.createElement('div');
            empty.className='feed-empty';
            empty.textContent='Подборка появится после первой публикации кинопремьер.';
            body.appendChild(empty);
          }
        }else if(parts.length){
          count=parts.length;
          for(const value of parts){
            const part=document.createElement('div');
            part.className='feed-part';
            part.dataset.feedKind=name;
            part.appendChild(sanitizeFeedHtml(value,name));
            body.appendChild(part);
          }
        }else{
          hasContent=false;
          const empty=document.createElement('div');
          empty.className='feed-empty';
          empty.textContent=name==='cinema'
            ?'Подборка появится после первой публикации кинопремьер.'
            :'Свежие материалы появятся после следующего обновления.';
          body.appendChild(empty);
        }

        if(meta) meta.textContent=hasContent?sectionMetaText(name,section):'Нет свежих данных';
        setFeedCardFresh(name,section,hasContent,payload);
        return {name,count,hasContent,firstTime};
      }

      function feedTodayCountLabel(name,count){
        if(name==='concerts'){
          const n=Math.abs(count)%100,m=n%10;
          const word=n>=11&&n<=14?'концертов':m===1?'концерт':m>=2&&m<=4?'концерта':'концертов';
          return '🎤 '+count+' '+word;
        }
        if(name==='standup') return '🎙 '+count+' Stand Up';
        if(name==='cinema') return '🎬 Кинопремьеры';
        return '';
      }

      function renderFeedToday(payload,results){
        const wrap=document.getElementById('feedToday');
        const links=document.getElementById('feedTodayLinks');
        const dateEl=document.getElementById('feedTodayDate');
        if(!wrap||!links) return;
        links.replaceChildren();
        const today=feedDateKey(new Date());
        const payloadToday=String(payload?.date||'')===today;
        const rows=[];
        for(const result of results){
          if(!result?.hasContent) continue;
          if((result.name==='concerts'||result.name==='standup')&&(!payloadToday||result.count<1)) continue;
          if(result.name==='cinema'&&feedDateKey(payload?.sections?.cinema?.updatedAt)!==today) continue;
          rows.push(result);
        }
        for(const result of rows){
          const button=document.createElement('button');
          button.type='button';
          button.className='feed-today-chip';
          button.textContent=feedTodayCountLabel(result.name,result.count);
          button.addEventListener('click',()=>{
            const [, ,cardId]=feedDomIds(result.name);
            document.getElementById(cardId)?.scrollIntoView({behavior:'smooth',block:'start'});
          });
          links.appendChild(button);
        }
        if(dateEl){
          dateEl.textContent=new Intl.DateTimeFormat('ru-RU',{
            day:'numeric',month:'long',timeZone:TZ
          }).format(new Date());
        }
        wrap.hidden=!rows.length;
      }

      function sortFeedCards(results){
        const grid=document.querySelector('.feed-grid');
        if(!grid) return;
        const byName=new Map(results.map(result=>[result.name,result]));
        const score=(name)=>{
          const result=byName.get(name)||{};
          if((name==='concerts'||name==='standup')&&result.hasContent&&result.count>0){
            return 100+(Number.isFinite(result.firstTime)?result.firstTime:999);
          }
          if(name==='cinema'&&result.hasContent) return 3000;
          return 4000+(name==='concerts'?1:name==='standup'?2:3);
        };
        ['concerts','standup','cinema']
          .sort((a,b)=>score(a)-score(b))
          .forEach(name=>{
            const [, ,cardId]=feedDomIds(name);
            const card=document.getElementById(cardId);
            if(card) grid.appendChild(card);
          });
      }

      function renderFeed(payload){
        const sections=payload?.sections&&typeof payload.sections==='object'?payload.sections:{};
        const eventParts=Array.isArray(sections.events?.parts)?sections.events.parts:[];
        currentFeedReactionTargets=[];
        currentFeedReactionBindings.clear();
        const results=[
          renderFeedSection('concerts',sections.events,eventParts[0]?[eventParts[0]]:[],payload),
          renderFeedSection('standup',sections.events,eventParts[1]?[eventParts[1]]:[],payload),
          renderFeedSection('cinema',sections.cinema,null,payload)
        ];

        homeDashboardState.feed=payload||null;
        homeDashboardState.feedResults=results;
        renderHomeDashboard();
        sortFeedCards(results);
        renderFeedToday(payload,results);
        animateRudiCollection(document.querySelector('.feed-grid'),'.feed-card',4);
        animateRudiCollection(document.getElementById('feedTodayLinks'),'.feed-today-chip',8);
        setTimeout(observeFeedCards,0);

        refreshFeedReactions();

        const updated=document.getElementById('feedUpdated');
        const status=document.getElementById('feedStatus');
        const updatedLabel=feedTimeLabel(payload?.updatedAt);
        if(updated) updated.textContent=updatedLabel?'Обновлено '+updatedLabel:'Свежая подборка RUDI';
        if(status) status.textContent=Object.keys(sections).length?'':'Лента заполнится после ближайшего обновления.';

        const version=String(payload?.version||'');
        const unseen=Boolean(version&&version!==feedSeenVersion());
        setFeedBadge(unseen&&currentAppTab!=='feed');
        if(currentAppTab==='feed') markFeedSeen(version);
      }

      async function loadFeed({silent=false}={}){
        if(!currentActor) return;
        const status=document.getElementById('feedStatus');
        if(status&&!silent) status.textContent='Обновляю Ленту…';
        try{
          const response=await fetch('/api/feed',{
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({initData:telegramInitData()}),
            cache:'no-store'
          });
          const payload=await response.json().catch(()=>({}));
          if(!response.ok||!payload.ok) throw new Error(payload.error||'feed-request-failed');
          renderFeed(payload);
        }catch(_){
          if(status) status.textContent='Не удалось обновить Ленту. Уже сохранённые актуальные материалы не удаляются из-за временного сбоя.';
          for(const name of ['concerts','standup','cinema']){
            const [bodyId]=feedDomIds(name);
            const body=document.getElementById(bodyId);
            if(body&&body.querySelector('.feed-skeleton')){
              body.replaceChildren();
              const empty=document.createElement('div');
              empty.className='feed-empty';
              empty.textContent='Временно недоступно';
              body.appendChild(empty);
            }
          }
        }
      }

      const PRODUCT_CATEGORY_ORDER=[
        'Мясо и рыба','Овощи и зелень','Фрукты и ягоды','Молочное и яйца',
        'Хлеб и выпечка','Бакалея','Сладкое и снеки','Напитки',
        'Заморозка','Для дома','Гигиена','Для Лулу','Другое'
      ];
      const PRODUCT_CATEGORY_EMOJI={
        'Мясо и рыба':'🥩','Овощи и зелень':'🥬','Фрукты и ягоды':'🍎',
        'Молочное и яйца':'🥛','Хлеб и выпечка':'🥖','Бакалея':'🌾',
        'Сладкое и снеки':'🍫','Напитки':'🥤','Заморозка':'❄️',
        'Для дома':'🧽','Гигиена':'🧴','Для Лулу':'🐾','Другое':'📦'
      };

      async function executeProductsRequest(operation,payload={},clientEpoch=productsMutationEpoch){
        const backupContext=backupRequestContext();
        const response=await fetch('/api/partner-message?rudiAction=products',{
          method:'POST',
          headers:{'Content-Type':'application/json'},
          body:JSON.stringify({initData:tg?.initData||'',backupToken:backupContext.token,operation,...payload}),
          cache:'no-store'
        });
        const data=await response.json().catch(()=>({}));
        if(!response.ok||!data.ok) throw new Error(data.error||'products-request-failed');
        data.__clientProductsOperation=operation;
        data.__clientProductsEpoch=clientEpoch;
        if(data.backupToken) await storeStateBackupToken(data.backupToken,backupContext);
        if(operation!=='list'){
          if(!data.backupToken) setTimeout(()=>refreshStateBackup(),250);
          setTimeout(()=>loadActivityJournal({silent:true}),320);
        }
        return data;
      }

      async function productsRequest(operation,payload={}){
        if(operation==='list'){
          const clientEpoch=productsMutationEpoch;
          await productsMutationChain.catch(()=>{});
          return executeProductsRequest(operation,payload,clientEpoch);
        }
        const clientEpoch=++productsMutationEpoch;
        const task=productsMutationChain.then(
          ()=>executeProductsRequest(operation,payload,clientEpoch),
          ()=>executeProductsRequest(operation,payload,clientEpoch)
        );
        productsMutationChain=task.then(()=>undefined,()=>undefined);
        return task;
      }

      function setProductsBadge(count){
        const badge=document.getElementById('productsTabBadge');
        if(!badge)return;
        const total=Math.max(0,Number(count)||0);
        const show=currentActor==='Рустам'&&total>10;
        badge.hidden=!show;
        badge.textContent=show?String(total):'';
      }

      function productAddedByLabel(value){
        const name=String(value||'').trim();
        if(!name) return '';
        if(name==='RUDI') return 'Добавлено ранее';
        const female=name==='Диана'||name==='Алиса';
        return (female?'Добавила ':'Добавил ')+name;
      }

      function productBoughtDay(item){
        const date=new Date(String(item?.boughtAt||''));
        if(Number.isNaN(date.getTime())){
          return {key:'unknown-'+String(item?.id||''),label:'Без даты'};
        }
        const parts=new Intl.DateTimeFormat('en-CA',{
          timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'
        }).formatToParts(date);
        const values=Object.fromEntries(parts.map(part=>[part.type,part.value]));
        return {
          key:values.year+'-'+values.month+'-'+values.day,
          label:new Intl.DateTimeFormat('ru-RU',{
            timeZone:TZ,day:'2-digit',month:'2-digit',year:'numeric'
          }).format(date)
        };
      }

      function groupProductHistory(history){
        const groups=[];
        const byDay=new Map();
        for(const item of Array.isArray(history)?history:[]){
          const day=productBoughtDay(item);
          let group=byDay.get(day.key);
          if(!group){
            group={key:day.key,label:day.label,items:[]};
            byDay.set(day.key,group);
            groups.push(group);
          }
          const text=String(item?.text||'').trim();
          if(text) group.items.push(text);
        }
        return groups;
      }

      function productsHistoryCollapsedStorageKey(){
        const actor=currentActor==='Диана'?'diana':currentActor==='Рустам'?'rustam':'shared';
        return 'rudi-products-history-collapsed-v1-'+actor;
      }

      function readProductsHistoryCollapsed(){
        let fallback=true;
        try{
          const stored=localStorage.getItem(productsHistoryCollapsedStorageKey());
          fallback=stored===null?true:stored==='1';
        }catch(_){}
        return uiViewState('products-history',fallback);
      }

      function setProductsHistoryCollapsed(collapsed,{persist=true}={}){
        const value=Boolean(collapsed);
        const section=document.querySelector('.products-history');
        const list=document.getElementById('productsHistory');
        const empty=document.getElementById('productsHistoryEmpty');
        const toggle=document.getElementById('productsHistoryToggle');
        const count=Number(toggle?.dataset.historyCount||0);
        section?.classList.toggle('is-collapsed',value);
        if(list) list.hidden=value;
        if(empty) empty.hidden=value||count>0;
        if(toggle){
          toggle.textContent=value?'Развернуть':'Свернуть';
          toggle.setAttribute('aria-expanded',value?'false':'true');
        }
        if(persist){
          try{localStorage.setItem(productsHistoryCollapsedStorageKey(),value?'1':'0')}catch(_){}
          setUiViewState('products-history',value);
        }
      }

      function productsRenderSignature(items,history){
        return JSON.stringify({
          items:(Array.isArray(items)?items:[]).map(item=>[
            String(item?.id||''),String(item?.text||''),Boolean(item?.checked),
            String(item?.addedBy||''),String(item?.category||''),String(item?.weeklyAmount||'')
          ]),
          history:(Array.isArray(history)?history:[]).map(item=>[
            String(item?.id||''),String(item?.text||''),String(item?.boughtAt||''),String(item?.boughtBy||'')
          ])
        });
      }

      async function copyProductText(text,button){
        let copied=false;
        try{
          await navigator.clipboard.writeText(String(text||''));
          copied=true;
        }catch(_){
          try{
            const area=document.createElement('textarea');
            area.value=String(text||'');
            area.setAttribute('readonly','');
            area.style.position='fixed';
            area.style.opacity='0';
            document.body.appendChild(area);
            area.select();
            copied=document.execCommand('copy');
            area.remove();
          }catch(_){}
        }
        if(copied){
          button?.classList.add('copied');
          setTimeout(()=>button?.classList.remove('copied'),700);
          try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
        }
      }

      function productIconButton(label,svg){
        const button=document.createElement('button');
        button.type='button';
        button.className='product-icon-action';
        button.setAttribute('aria-label',label);
        button.title=label;
        button.innerHTML=svg;
        return button;
      }

      function renderProducts(payload){
        const items=Array.isArray(payload?.items)?payload.items:[];
        const history=Array.isArray(payload?.history)?payload.history:[];
        const clientOperation=String(payload?.__clientProductsOperation||'');
        const clientEpoch=Number(payload?.__clientProductsEpoch||0);
        if(clientEpoch>0&&clientEpoch<productsMutationEpoch) return;
        const renderSignature=productsRenderSignature(items,history);
        const unchanged=renderSignature===latestProductsRenderSignature;
        latestProductsRenderSignature=renderSignature;
        const previousProductCount=homeDashboardState.productCount;
        homeDashboardState.productCount=items.length;
        if(previousProductCount!==items.length) renderHomeDashboard();
        const groups=document.getElementById('productsGroups');
        const empty=document.getElementById('productsEmpty');
        const status=document.getElementById('productsStatus');
        const clear=document.getElementById('productsClear');
        const boughtAll=document.getElementById('productsBought');
        const historyList=document.getElementById('productsHistory');
        const historyEmpty=document.getElementById('productsHistoryEmpty');
        const historyCount=document.getElementById('productsHistoryCount');
        if(!groups||!empty||!historyList) return;

        setProductsBadge(items.length);
        if(clear) clear.disabled=!items.length;
        if(boughtAll){
          boughtAll.textContent=currentActor==='Диана'?'Купила':'Купил';
          const checkedCount=items.filter(item=>Boolean(item.checked)).length;
          boughtAll.disabled=!items.length;
          boughtAll.dataset.checkedCount=String(checkedCount);
          boughtAll.classList.toggle('has-selection',checkedCount>0);
        }
        if(status){
          status.textContent=items.length
            ?items.length+' '+(items.length===1?'позиция':(items.length>=2&&items.length<=4?'позиции':'позиций'))
            :'';
          status.hidden=!items.length;
        }
        if(unchanged) return;

        groups.replaceChildren();
        const byCategory=new Map();
        for(const item of items){
          const category=String(item?.category||'Другое');
          if(!byCategory.has(category)) byCategory.set(category,[]);
          byCategory.get(category).push(item);
        }
        const ordered=[
          ...PRODUCT_CATEGORY_ORDER.filter(category=>byCategory.has(category)),
          ...[...byCategory.keys()].filter(category=>!PRODUCT_CATEGORY_ORDER.includes(category))
        ];

        for(const category of ordered){
          const section=document.createElement('section');
          section.className='product-category';
          const head=document.createElement('div');
          head.className='product-category-head';
          const title=document.createElement('strong');
          title.textContent=(PRODUCT_CATEGORY_EMOJI[category]||'📦')+' '+category;
          const count=document.createElement('span');
          count.textContent=String(byCategory.get(category).length);
          head.append(title,count);

          const list=document.createElement('div');
          list.className='product-list';
          for(const item of byCategory.get(category)){
            const row=document.createElement('div');
            row.className='product-item'+(item.checked?' is-checked':'');
            row.dataset.rudiItemId=String(item.id||'');

            const check=document.createElement('button');
            check.type='button';
            check.className='product-check';
            check.setAttribute('aria-label',item.checked?'Снять отметку':'Отметить');
            check.setAttribute('aria-pressed',item.checked?'true':'false');
            check.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m6 12 4 4 8-9"/></svg>';
            check.addEventListener('click',async()=>{
              if(check.disabled)return;
              const previous=Boolean(item.checked);
              const next=!previous;
              item.checked=next;
              row.classList.toggle('is-checked',next);
              check.setAttribute('aria-label',next?'Снять отметку':'Отметить');
              check.setAttribute('aria-pressed',next?'true':'false');
              const checkedIds=items.filter(row=>Boolean(row?.checked)).map(row=>String(row?.id||'')).filter(Boolean);
              if(boughtAll){
                boughtAll.dataset.checkedCount=String(checkedIds.length);
                boughtAll.classList.toggle('has-selection',checkedIds.length>0);
                boughtAll.disabled=!items.length;
              }
              check.disabled=true;
              try{
                await productsRequest('toggle',{id:item.id,checkedIds});
                try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
              }catch(_){
                item.checked=previous;
                row.classList.toggle('is-checked',previous);
                check.setAttribute('aria-label',previous?'Снять отметку':'Отметить');
                check.setAttribute('aria-pressed',previous?'true':'false');
                try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
              }finally{check.disabled=false}
            });

            const main=document.createElement('div');
            main.className='product-main';
            const text=document.createElement('div');
            text.className='product-text';
            text.textContent=String(item.text||'');
            const amount=document.createElement('small');
            amount.className='product-weekly-amount';
            const weeklyAmount=String(item.weeklyAmount||'').trim();
            amount.textContent=weeklyAmount?'На неделю для двоих: ~'+weeklyAmount:'';
            amount.hidden=!weeklyAmount;
            const meta=document.createElement('small');
            meta.className='product-added-by';
            meta.textContent=productAddedByLabel(item.addedBy);
            main.append(text,amount,meta);

            const actions=document.createElement('div');
            actions.className='product-actions';
            const copy=productIconButton('Копировать','<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="8" y="8" width="11" height="11" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/></svg>');
            copy.addEventListener('click',()=>copyProductText(item.text,copy));

            const remove=productIconButton('Удалить','<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M9 7V4h6v3M7 7l1 13h8l1-13M10 11v5M14 11v5"/></svg>');
            remove.classList.add('danger');
            remove.addEventListener('click',async()=>{
              if(remove.disabled) return;
              remove.disabled=true;
              const parent=row.parentNode;
              const nextSibling=row.nextSibling;
              row.remove();
              try{tg?.HapticFeedback?.impactOccurred?.('light')}catch(_){}
              try{
                const data=await productsRequest('remove',{id:item.id});
                renderProducts(data);
                const removed=data?.removedItem||item;
                showUndoSnackbar('Удалено',async()=>{
                  const restored=await productsRequest('restore',{item:removed});
                  renderProducts(restored);
                });
              }catch(_){
                if(parent&&row.parentNode!==parent) parent.insertBefore(row,nextSibling&&nextSibling.parentNode===parent?nextSibling:null);
                remove.disabled=false;
                try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
              }
            });

            actions.append(copy,remove);
            row.append(check,main,actions);
            list.appendChild(row);
          }
          section.append(head,list);
          groups.appendChild(section);
        }

        empty.hidden=items.length>0;
        historyList.replaceChildren();
        if(historyCount) historyCount.textContent=history.length?String(history.length):'';
        const historyToggle=document.getElementById('productsHistoryToggle');
        if(historyToggle) historyToggle.dataset.historyCount=String(history.length);
        for(const group of groupProductHistory(history)){
          const row=document.createElement('div');
          row.className='product-history-item';
          const date=document.createElement('strong');
          date.className='product-history-date';
          date.textContent=group.label;
          const separator=document.createElement('span');
          separator.className='product-history-separator';
          separator.textContent=' · ';
          const itemsText=document.createElement('span');
          itemsText.className='product-history-items';
          itemsText.textContent=group.items.join(', ');
          row.append(date,separator,itemsText);
          historyList.appendChild(row);
        }
        setProductsHistoryCollapsed(readProductsHistoryCollapsed(),{persist:false});
        animateRudiCollection(groups,'.product-category',7);
        animateRudiCollection(groups,'.product-item',14);
        animateRudiCollection(historyList,'.product-history-item',10);
        if(currentAppTab==='products'){
          const route=routeFromLocation();
          focusDeepLinkedItem('products',route.item);
        }
      }

      function productsRefreshDelay(){
        if(document.visibilityState!=='visible'||currentAppTab!=='products') return 60000;
        return 15000;
      }

      function scheduleProductsRefresh(delay=productsRefreshDelay()){
        clearTimeout(productsRefreshTimer);
        productsRefreshTimer=setTimeout(async()=>{
          if(currentActor&&document.visibilityState==='visible'&&currentAppTab==='products'){
            await loadProducts({silent:true});
          }
          scheduleProductsRefresh();
        },Math.max(5000,Number(delay)||productsRefreshDelay()));
      }

      async function loadProducts({silent=false}={}){
        if(!currentActor) return;
        if(productsLoadPromise) return productsLoadPromise;

        const status=document.getElementById('productsStatus');
        if(status&&!silent){
          status.hidden=false;
          status.textContent='Обновляю список…';
        }

        productsLoadPromise=(async()=>{
          try{
            const data=await productsRequest('list');
            renderProducts(data);
            if(Array.isArray(data?.items)&&data.items.length){
              hideProductsRecovery();
            }else{
              checkProductsRecovery();
            }
            return data;
          }catch(_){
            if(status&&!silent){
              status.hidden=false;
              status.textContent='Не удалось обновить список';
            }
            return null;
          }
        })();

        try{
          return await productsLoadPromise;
        }finally{
          productsLoadPromise=null;
        }
      }

      function confirmProductsClear(){
        return new Promise(resolve=>{
          try{
            if(tg?.showConfirm){
              tg.showConfirm('Очистить весь список продуктов?',value=>resolve(Boolean(value)));
              return;
            }
          }catch(_){}
          resolve(window.confirm('Очистить весь список продуктов?'));
        });
      }


      let fastingState=null;
      let fastingTicker=0;
      let fastingHomeTicker=0;
      let fastingOverviewState={'Рустам':null,'Диана':null};
      let selectedFastingGoal=16;
      let fastingReturnTab='products';

      function fastingPad(value){
        return String(Math.max(0,Math.floor(value))).padStart(2,'0');
      }

      function fastingDurationLabel(minutes){
        const total=Math.max(0,Math.round(Number(minutes)||0));
        const hours=Math.floor(total/60);
        const mins=total%60;
        if(!hours) return mins+' мин';
        if(!mins) return hours+' ч';
        return hours+' ч '+mins+' мин';
      }

      function fastingDateTimeLabel(value){
        const date=new Date(String(value||''));
        if(Number.isNaN(date.getTime())) return '—';
        return new Intl.DateTimeFormat('ru-RU',{
          day:'numeric',
          month:'short',
          hour:'2-digit',
          minute:'2-digit',
          hourCycle:'h23'
        }).format(date).replace('.','');
      }

      function fastingMinutesInYear(row,year){
        const startMs=Date.parse(String(row?.startedAt||''));
        if(!Number.isFinite(startMs)) return 0;

        let endMs=Date.parse(String(row?.endedAt||''));
        if(!Number.isFinite(endMs)){
          const durationMinutes=Math.max(0,Number(row?.durationMinutes)||0);
          if(!durationMinutes) return 0;
          endMs=startMs+durationMinutes*60*1000;
        }
        if(endMs<=startMs) return 0;

        const targetYear=Number(year);
        if(!Number.isFinite(targetYear)) return 0;
        const yearStart=new Date(targetYear,0,1).getTime();
        const yearEnd=new Date(targetYear+1,0,1).getTime();
        const overlapStart=Math.max(startMs,yearStart);
        const overlapEnd=Math.min(endMs,yearEnd);
        if(overlapEnd<=overlapStart) return 0;
        return (overlapEnd-overlapStart)/(60*1000);
      }

      function fastingHistoryCollapsedStorageKey(){
        const actor=currentActor==='Диана'?'diana':currentActor==='Рустам'?'rustam':'shared';
        return 'rudi-fasting-history-collapsed-v2-'+actor;
      }

      function readFastingHistoryCollapsed(){
        let fallback=true;
        try{
          const stored=localStorage.getItem(fastingHistoryCollapsedStorageKey());
          fallback=stored===null?true:stored==='1';
        }catch(_){}
        return uiViewState('fasting-history',fallback);
      }

      function setFastingHistoryCollapsed(collapsed,{persist=true}={}){
        const value=Boolean(collapsed);
        const card=document.querySelector('.fasting-history-card');
        const history=document.getElementById('fastingHistory');
        const empty=document.getElementById('fastingHistoryEmpty');
        const toggle=document.getElementById('fastingHistoryToggle');
        const count=Number(toggle?.dataset.historyCount||0);
        card?.classList.toggle('is-collapsed',value);
        if(history) history.hidden=value;
        if(empty) empty.hidden=value||count>0;
        if(toggle){
          toggle.setAttribute('aria-expanded',value?'false':'true');
          toggle.setAttribute('aria-label',value?'Развернуть историю':'Свернуть историю');
          toggle.title=value?'Развернуть историю':'Свернуть историю';
        }
        if(persist){
          try{localStorage.setItem(fastingHistoryCollapsedStorageKey(),value?'1':'0')}catch(_){}
          setUiViewState('fasting-history',value);
        }
      }

      function fastingLocalInputValue(date=new Date()){
        const pad=value=>String(value).padStart(2,'0');
        return date.getFullYear()+'-'+pad(date.getMonth()+1)+'-'+pad(date.getDate())+'T'+pad(date.getHours())+':'+pad(date.getMinutes());
      }


      function fastingHoursWord(hours){
        const value=Math.max(0,Math.floor(Number(hours)||0));
        const mod100=value%100;
        const mod10=value%10;
        if(mod100>=11&&mod100<=14) return 'часов';
        if(mod10===1) return 'час';
        if(mod10>=2&&mod10<=4) return 'часа';
        return 'часов';
      }

      function fastingHomeLabel(active,firstPerson=false){
        if(!active?.startedAt) return '';
        const started=Date.parse(String(active.startedAt||''));
        if(!Number.isFinite(started)) return '';
        const elapsed=Math.max(0,Date.now()-started);
        const hours=Math.floor(elapsed/3600000);
        const verb=firstPerson?'Голодаю':'Голодает';
        return hours<1 ? '🍽️ '+verb+' меньше часа' : '🍽️ '+verb+' '+hours+' '+fastingHoursWord(hours);
      }

      function renderFastingProfileOutline(active,partner=false){
        const button=document.getElementById(partner?'partnerFastingProfileButton':'fastingProfileButton');
        if(!button)return;
        const startMs=Date.parse(String(active?.startedAt||''));
        const activeNow=Number.isFinite(startMs);
        const elapsedNode=button.querySelector(partner?'#partnerFastingElapsed':'#fastingProfileElapsed');
        const hours=activeNow?Math.floor(Math.max(0,Date.now()-startMs)/3600000):0;
        if(partner){
          button.hidden=!activeNow;
          if(!activeNow)hidePartnerFastingGoal();
        }
        if(elapsedNode){
          elapsedNode.textContent=activeNow?hours+' ч':'';
          elapsedNode.hidden=!activeNow;
        }
        const goalHours=Number(active?.goalHours);
        const running=activeNow&&Number.isFinite(goalHours)&&goalHours>0;
        const reached=running&&Date.now()-startMs>=goalHours*3600000;
        button.dataset.fastingComplete=reached?'1':'0';
        if(partner)button.dataset.fastingGoalHours=running?String(goalHours):'';
        button.dataset.fastingActive=running?'1':'0';
        let svg=button.querySelector('.rudi-fasting-progress-outline');
        if(!running){
          if(svg)svg.hidden=true;
          button.setAttribute('aria-label',partner?'Голодание партнёра '+hours+' ч':(activeNow?'Голодание '+hours+' ч. Открыть трекер голодания':'Открыть трекер голодания'));
          return;
        }
        if(!svg){
          const ns='http://www.w3.org/2000/svg';
          svg=document.createElementNS(ns,'svg');
          svg.classList.add('rudi-fasting-progress-outline');
          svg.setAttribute('viewBox','0 0 100 100');
          svg.setAttribute('aria-hidden','true');
          svg.setAttribute('focusable','false');
          for(const className of ['rudi-fasting-progress-track','rudi-fasting-progress-value']){
            const path=document.createElementNS(ns,'path');
            path.classList.add(className);
            path.setAttribute('d','M50 3 H71 C85.36 3 97 14.64 97 29 V71 C97 85.36 85.36 97 71 97 H29 C14.64 97 3 85.36 3 71 V29 C3 14.64 14.64 3 29 3 H50');
            svg.appendChild(path);
          }
          button.appendChild(svg);
        }
        svg.hidden=false;
        const percent=Math.min(100,Math.max(0,(Date.now()-startMs)/(goalHours*3600000)*100));
        const total=168+52*Math.PI;
        svg.querySelector('.rudi-fasting-progress-value').style.strokeDasharray=(total*percent/100)+' '+total;
        button.setAttribute('aria-label',partner?'Голодание партнёра '+hours+' ч · '+Math.round(percent)+'% от цели. Показать цель':('Голодание '+hours+' ч · '+Math.round(percent)+'% от цели. Открыть трекер голодания'));
      }
      let partnerFastingGoalTimer=0;
      function hidePartnerFastingGoal(){
        clearTimeout(partnerFastingGoalTimer);
        partnerFastingGoalTimer=0;
        document.getElementById('partnerFastingGoalPopover')?.remove();
      }
      function showPartnerFastingGoal(button){
        if(!button||button.hidden)return;
        const goal=Number(button.dataset.fastingGoalHours);
        if(!Number.isFinite(goal)||goal<=0)return;
        const goalText='Цель голодания: '+String(goal).replace('.',',')+' ч';
        const existing=document.getElementById('partnerFastingGoalPopover');
        if(existing){
          const same=existing.textContent===goalText;
          hidePartnerFastingGoal();
          if(same)return;
        }
        const popup=document.createElement('div');
        popup.id='partnerFastingGoalPopover';
        popup.className='partner-fasting-goal-popover';
        popup.setAttribute('role','status');
        popup.textContent=goalText;
        document.body.appendChild(popup);
        const anchor=button.getBoundingClientRect();
        const box=popup.getBoundingClientRect();
        const width=Math.max(150,box.width||180);
        popup.style.left=Math.max(10,Math.min(window.innerWidth-width-10,anchor.left+anchor.width/2-width/2))+'px';
        const above=anchor.top-box.height-10;
        popup.style.top=(above>=10?above:Math.max(10,Math.min(window.innerHeight-box.height-10,anchor.bottom+24)))+'px';
        partnerFastingGoalTimer=setTimeout(hidePartnerFastingGoal,4000);
      }

      function renderFastingHomeStatus(overview=fastingOverviewState){
        const activeOf=entry=>{
          const active=entry&&Object.prototype.hasOwnProperty.call(entry,'active')?entry.active:entry;
          return active&&Number.isFinite(Date.parse(String(active.startedAt||'')))?active:null;
        };
        fastingOverviewState={
          'Рустам':activeOf(overview?.['Рустам']),
          'Диана':activeOf(overview?.['Диана']),
        };

        const selfActor=currentActor==='Диана'?'Диана':'Рустам';
        renderFastingProfileOutline(fastingOverviewState[selfActor]);
        const partnerActor=selfActor==='Рустам'?'Диана':'Рустам';
        renderFastingProfileOutline(fastingOverviewState[partnerActor],true);
      }

      function updateOwnFastingOverview(active){
        const actor=currentActor==='Диана'?'Диана':'Рустам';
        fastingOverviewState={
          ...fastingOverviewState,
          [actor]:active||null,
        };
        renderFastingHomeStatus(fastingOverviewState);
      }

      let fastingOverviewLoadPromise=null;
      async function loadFastingOverview(){
        if(!currentActor) return null;
        if(fastingOverviewLoadPromise) return fastingOverviewLoadPromise;
        fastingOverviewLoadPromise=(async()=>{
          try{
            const data=await fastingRequest('overview');
            renderFastingHomeStatus(data.fastingOverview||{});
            return data.fastingOverview||{};
          }catch(_){
            renderFastingHomeStatus(fastingOverviewState);
            return null;
          }
        })().finally(()=>{fastingOverviewLoadPromise=null});
        return fastingOverviewLoadPromise;
      }

      function startFastingHomeTicker(){
        clearInterval(fastingHomeTicker);
        renderFastingHomeStatus(fastingOverviewState);
        fastingHomeTicker=setInterval(()=>renderFastingHomeStatus(fastingOverviewState),60*1000);
      }

      const FASTING_REWARD_TIERS=Object.freeze([
        {hours:12,stars:0.5},
        {hours:14,stars:1},
        {hours:16,stars:1.5},
        {hours:18,stars:2},
        {hours:24,stars:3},
        {hours:32,stars:4},
        {hours:40,stars:5}
      ]);

      function fastingRewardStarsForHours(elapsedHours){
        const hours=Math.max(0,Number(elapsedHours)||0);
        let reward=0;
        for(const tier of FASTING_REWARD_TIERS){
          if(hours<tier.hours) break;
          reward=tier.stars;
        }
        return reward;
      }

      function fastingNextReward(elapsedHours){
        const hours=Math.max(0,Number(elapsedHours)||0);
        const next=FASTING_REWARD_TIERS.find(tier=>hours<tier.hours);
        if(!next) return null;
        return {
          ...next,
          remainingMinutes:Math.max(1,Math.ceil((next.hours-hours)*60))
        };
      }

      function fastingStage(elapsedHours){
        const hours=Math.max(0,Number(elapsedHours)||0);
        if(hours<4){
          return {
            label:'После еды',
            title:'Пищеварительная фаза',
            description:'Организм ещё активно использует энергию из последнего приёма пищи. Инсулин обычно выше, чем позже во время голодания.',
            feeling:'Обычно самочувствие привычное; голод может ещё не ощущаться.',
            action:'Пейте воду по жажде и сохраняйте обычный спокойный режим.'
          };
        }
        if(hours<12){
          return {
            label:'4–12 часов',
            title:'Постабсорбтивная фаза',
            description:'Инсулин постепенно снижается, а печень всё больше поддерживает уровень глюкозы за счёт запасов гликогена.',
            feeling:'Может появиться голод, желание перекусить, лёгкая раздражительность или колебания энергии.',
            action:'Вода, несладкий чай или кофе без добавок могут помочь. Умеренная активность обычно переносится нормально.'
          };
        }
        if(hours<18){
          return {
            label:'12–18 часов',
            title:'Переход к жирам',
            description:'Использование гликогена продолжается, а доля энергии из жиров постепенно растёт. Кетоны могут начать повышаться.',
            feeling:'Голод может приходить волнами; у части людей энергия выравнивается, у других появляется слабость или зябкость.',
            action:'Не форсируйте интенсивную нагрузку. Следите за водой и самочувствием; при выраженной слабости лучше закончить голодание.'
          };
        }
        if(hours<24){
          return {
            label:'18–24 часа',
            title:'Больше жиров и кетонов',
            description:'Организм обычно сильнее опирается на жиры, а образование кетонов становится заметнее. Скорость перехода у всех разная.',
            feeling:'Возможны более заметный голод, усталость, головная боль или снижение концентрации, хотя некоторые чувствуют себя стабильно.',
            action:'Выбирайте спокойную нагрузку и регулярно оценивайте самочувствие. При головокружении, дрожи или выраженной слабости прекратите голодание.'
          };
        }
        return {
          label:'24+ часов',
          title:'Продолжительное голодание',
          description:'Зависимость от жиров и кетонов обычно продолжает расти. На этом сроке особенно важно ориентироваться на самочувствие.',
          feeling:'На длительном голодании переносимость сильно различается; возможны слабость, головная боль, зябкость и снижение работоспособности.',
          action:'Не продолжайте через плохое самочувствие. При выраженной слабости, спутанности, обмороке или стойком головокружении прекратите голодание и при необходимости обратитесь за медицинской помощью.'
        };
      }

      async function fastingRequest(operation='state',payload={}){
        const response=await fetch('/api/partner-message?rudiAction=fasting',{
          method:'POST',
          headers:{'Content-Type':'application/json'},
          body:JSON.stringify({
            initData:telegramInitData(),
            operation,
            ...payload
          }),
          cache:'no-store'
        });
        const data=await response.json().catch(()=>({}));
        if(!response.ok||!data.ok){
          const error=new Error(data.error||'fasting-request-failed');
          error.status=response.status;
          throw error;
        }
        return data;
      }

      function fastingErrorText(error){
        const code=String(error?.message||error||'');
        if(code==='fasting-already-active') return 'Голодание уже запущено';
        if(code==='fasting-not-active') return 'Активного голодания уже нет';
        if(code==='fasting-start-future') return 'Время начала не может быть в будущем';
        if(code==='fasting-start-too-old') return 'Укажи время начала не более чем 30 дней назад';
        if(code==='fasting-start-invalid') return 'Проверь время начала';
        if(code==='fasting-goal-invalid') return 'Выбери цель 12, 14, 16, 18 или 24 часа';
        return 'Не удалось обновить трекер';
      }

      function renderFastingTicker(){
        const active=fastingState?.active;
        if(!active) return;

        const startMs=Date.parse(String(active.startedAt||''));
        if(!Number.isFinite(startMs)) return;

        const elapsedMs=Math.max(0,Date.now()-startMs);
        const elapsedSeconds=Math.floor(elapsedMs/1000);
        const hours=Math.floor(elapsedSeconds/3600);
        const minutes=Math.floor((elapsedSeconds%3600)/60);
        const seconds=elapsedSeconds%60;
        const elapsedHours=elapsedMs/3600000;
        const stage=fastingStage(elapsedHours);
        const goalHours=Math.max(1,Number(active.goalHours)||16);
        const goalProgress=Math.min(100,Math.max(0,(elapsedHours/goalHours)*100));

        const elapsed=document.getElementById('fastingElapsed');
        const badge=document.getElementById('fastingStageBadge');
        const title=document.getElementById('fastingStageTitle');
        const description=document.getElementById('fastingStageDescription');
        const feeling=document.getElementById('fastingStageFeeling');
        const action=document.getElementById('fastingStageAction');
        const bar=document.getElementById('fastingProgressBar');
        const goalState=document.getElementById('fastingGoalState');
        const rewardValue=document.getElementById('fastingRewardValue');
        const nextRewardValue=document.getElementById('fastingNextRewardValue');
        const nextRewardCountdown=document.getElementById('fastingNextRewardCountdown');
        const nextReward=fastingNextReward(elapsedHours);

        if(elapsed) elapsed.textContent=fastingPad(hours)+':'+fastingPad(minutes)+':'+fastingPad(seconds);
        if(rewardValue) rewardValue.textContent=String(fastingRewardStarsForHours(elapsedHours)).replace('.',',');
        if(nextRewardValue) nextRewardValue.textContent=nextReward?String(nextReward.stars).replace('.',','):'5';
        if(nextRewardCountdown) nextRewardCountdown.textContent=nextReward
          ?'через '+fastingDurationLabel(nextReward.remainingMinutes)
          :'максимальная награда достигнута';
        if(badge) badge.textContent=stage.label;
        if(title) title.textContent=stage.title;
        if(description) description.textContent=stage.description;
        if(feeling) feeling.textContent=stage.feeling;
        if(action) action.textContent=stage.action;
        if(bar) bar.style.width=goalProgress+'%';
        renderFastingProfileOutline(active);

        if(goalState){
          const goalReached=elapsedHours>=goalHours;
          goalState.textContent=goalReached
            ? 'Цель достигнута'
            : 'До цели '+fastingDurationLabel(Math.ceil(goalHours*60-elapsedMs/60000));
          goalState.classList.toggle('is-reached',goalReached);
        }
      }

      function renderFasting(payload){
        fastingState=payload&&typeof payload==='object'
          ?payload
          :{active:null,history:[],stats:{}};

        const active=fastingState.active||null;
        const activeCard=document.getElementById('fastingActiveCard');
        const startCard=document.getElementById('fastingStartCard');

        if(activeCard) activeCard.hidden=!active;
        if(startCard) startCard.hidden=Boolean(active);

        const actor=document.getElementById('fastingActorLabel');
        if(actor) actor.textContent=currentActor?'Личная история · '+currentActor:'Личная история';

        if(active){
          const started=document.getElementById('fastingStartedLabel');
          const goal=document.getElementById('fastingGoalLabel');
          if(started) started.textContent=fastingDateTimeLabel(active.startedAt);
          if(goal) goal.textContent=String(active.goalHours||16)+' ч';

          clearInterval(fastingTicker);
          renderFastingTicker();
          fastingTicker=setInterval(renderFastingTicker,1000);
        }else{
          clearInterval(fastingTicker);
          fastingTicker=0;
          renderFastingProfileOutline(null);
          const input=document.getElementById('fastingStartAt');
          if(input&&!input.value) input.value=fastingLocalInputValue();
        }

        const stats=fastingState.stats||{};
        const count=document.getElementById('fastingStatCount');
        const average=document.getElementById('fastingStatAverage');
        const longest=document.getElementById('fastingStatLongest');
        if(count) count.textContent=String(Number(stats.completed)||0);
        if(average) average.textContent=Number(stats.completed)?fastingDurationLabel(stats.averageMinutes):'—';
        if(longest) longest.textContent=Number(stats.completed)?fastingDurationLabel(stats.longestMinutes):'—';

        const history=document.getElementById('fastingHistory');
        const empty=document.getElementById('fastingHistoryEmpty');
        const rows=Array.isArray(fastingState.history)?fastingState.history:[];
        const historyTitle=document.getElementById('fastingHistoryTitle');
        if(historyTitle){
          const currentYear=new Date().getFullYear();
          const totalMinutes=rows.reduce(
            (sum,row)=>sum+fastingMinutesInYear(row,currentYear),
            0
          );
          const totalHours=Math.round((totalMinutes/60)*10)/10;
          const hoursLabel=Number.isInteger(totalHours)?String(totalHours):String(totalHours).replace('.',',');
          const totalStars=rows.reduce((sum,row)=>{
            const ended=new Date(String(row?.endedAt||''));
            if(Number.isNaN(ended.getTime())||ended.getFullYear()!==currentYear) return sum;
            return sum+Math.max(0,Number(row?.earnedStars)||0);
          },0);
          const starsLabel=Number.isInteger(totalStars)?String(totalStars):String(totalStars).replace('.',',');
          historyTitle.textContent='История · '+hoursLabel+' ч · '+starsLabel+' ⭐ за '+currentYear;
        }

        if(history){
          history.replaceChildren();
          rows.forEach(row=>{
            const item=document.createElement('article');
            item.className='fasting-history-item';

            const copy=document.createElement('div');
            copy.className='fasting-history-copy';

            const duration=document.createElement('strong');
            duration.textContent=fastingDurationLabel(row.durationMinutes);

            const meta=document.createElement('span');
            meta.textContent=fastingDateTimeLabel(row.startedAt)+' → '+fastingDateTimeLabel(row.endedAt);

            const stars=document.createElement('span');
            stars.className='fasting-history-stars';
            const earnedStars=Math.max(0,Number(row?.earnedStars)||0);
            stars.textContent=(Number.isInteger(earnedStars)?String(earnedStars):String(earnedStars).replace('.',','))+' ⭐ получено';

            const goal=document.createElement('span');
            goal.className='fasting-history-goal'+(row.goalReached?' is-reached':'');
            goal.textContent=(row.goalReached?'✓ ':'')+String(row.goalHours||16)+' ч';

            copy.append(duration,meta,stars);
            item.append(copy,goal);
            history.appendChild(item);
          });
        }

        const historyToggle=document.getElementById('fastingHistoryToggle');
        if(historyToggle) historyToggle.dataset.historyCount=String(rows.length);
        setFastingHistoryCollapsed(readFastingHistoryCollapsed(),{persist:false});
      }

      async function loadFastingTracker({silent=false}={}){
        if(!currentActor) return null;
        const status=document.getElementById('fastingStatus');
        if(status&&!silent) status.textContent='Обновляю…';

        try{
          const data=await fastingRequest('state');
          renderFasting(data.fasting);
          if(status) status.textContent='';
          return data.fasting;
        }catch(error){
          if(status) status.textContent=fastingErrorText(error);
          return null;
        }
      }

      function setupFastingTracker(){
        const profileButton=document.getElementById('fastingProfileButton');
        const back=document.getElementById('fastingBackButton');
        const start=document.getElementById('fastingStartButton');
        const stop=document.getElementById('fastingStopButton');
        const input=document.getElementById('fastingStartAt');
        const status=document.getElementById('fastingStatus');
        const historyToggle=document.getElementById('fastingHistoryToggle');

        const navigateOwnFasting=()=>{
          fastingReturnTab='home';
          navigateToAppTab('fasting',{scroll:true});
          try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
        };
        profileButton?.addEventListener('click',navigateOwnFasting);

        historyToggle?.addEventListener('click',()=>{
          const card=document.querySelector('.fasting-history-card');
          const collapsed=card?.classList.contains('is-collapsed')??readFastingHistoryCollapsed();
          setFastingHistoryCollapsed(!collapsed);
          try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
        });

        if(input&&!input.value) input.value=fastingLocalInputValue();

        document.querySelectorAll('[data-fasting-goal]').forEach(button=>{
          const goalHours=Number(button.dataset.fastingGoal)||0;
          const rewardNode=button.querySelector('.fasting-goal-reward');
          if(rewardNode){
            const rewardStars=fastingRewardStarsForHours(goalHours);
            const rewardLabel=Number.isInteger(rewardStars)?String(rewardStars):String(rewardStars).replace('.',',');
            rewardNode.textContent=rewardLabel+' ⭐️';
          }
          button.addEventListener('click',()=>{
            selectedFastingGoal=Number(button.dataset.fastingGoal)||16;
            document.querySelectorAll('[data-fasting-goal]').forEach(row=>{
              row.setAttribute('aria-pressed',String(Number(row.dataset.fastingGoal)===selectedFastingGoal));
            });
            try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
          });
        });

        back?.addEventListener('click',()=>{
          navigateToAppTab(fastingReturnTab==='home'?'home':'products',{scroll:true});
        });

        start?.addEventListener('click',async()=>{
          if(start.disabled) return;

          const raw=String(input?.value||'').trim();
          const parsed=raw?new Date(raw):new Date();
          if(Number.isNaN(parsed.getTime())){
            if(status) status.textContent='Проверь время начала';
            return;
          }

          start.disabled=true;
          if(status) status.textContent='Запускаю…';

          try{
            const data=await fastingRequest('start',{
              startedAt:parsed.toISOString(),
              goalHours:selectedFastingGoal
            });
            renderFasting(data.fasting);
            updateOwnFastingOverview(data.fasting?.active||null);
            loadActivityJournal({silent:true}).catch(()=>{});
            if(status) status.textContent='';
            try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
          }catch(error){
            if(status) status.textContent=fastingErrorText(error);
            try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
          }finally{
            start.disabled=false;
          }
        });

        const stopConfirm=document.getElementById('fastingStopConfirm');
        const stopConfirmBackdrop=document.getElementById('fastingStopConfirmBackdrop');
        const stopConfirmNo=document.getElementById('fastingStopConfirmNo');
        const stopConfirmYes=document.getElementById('fastingStopConfirmYes');

        const setStopConfirmOpen=(open)=>{
          if(!stopConfirm) return;
          stopConfirm.hidden=!open;
          stopConfirm.setAttribute('aria-hidden',String(!open));
          document.body.classList.toggle('fasting-stop-confirm-open',open);
          if(open){
            requestAnimationFrame(()=>stopConfirm.classList.add('is-open'));
            setTimeout(()=>stopConfirmNo?.focus(),40);
          }else{
            stopConfirm.classList.remove('is-open');
            document.body.classList.remove('fasting-stop-confirm-open');
            stop?.focus?.();
          }
        };

        const finishFasting=async()=>{
          if(stop.disabled) return;
          stop.disabled=true;
          if(stopConfirmYes) stopConfirmYes.disabled=true;
          if(stopConfirmNo) stopConfirmNo.disabled=true;
          if(status) status.textContent='Сохраняю…';

          try{
            const data=await fastingRequest('stop');
            setStopConfirmOpen(false);
            renderFasting(data.fasting);
            updateOwnFastingOverview(null);
            loadActivityJournal({silent:true}).catch(()=>{});
            const earnedStars=Number(data.reward?.earnedStars||0);
            const requestedStars=Number(data.reward?.requestedStars||0);
            const savedToHistory=data.savedToHistory!==false;
            if(status){
              status.textContent=!savedToHistory
                ?'Голодание меньше часа · в историю не добавлено'
                :earnedStars>0
                  ?'Голодание сохранено · +'+earnedStars+'⭐'
                  :requestedStars>0
                    ?'Голодание сохранено · дневной лимит звёзд уже достигнут'
                    :'Голодание сохранено в истории';
            }
            try{tg?.HapticFeedback?.notificationOccurred?.('success')}catch(_){}
          }catch(error){
            if(status) status.textContent=fastingErrorText(error);
            try{tg?.HapticFeedback?.notificationOccurred?.('error')}catch(_){}
          }finally{
            stop.disabled=false;
            if(stopConfirmYes) stopConfirmYes.disabled=false;
            if(stopConfirmNo) stopConfirmNo.disabled=false;
          }
        };

        stop?.addEventListener('click',()=>{
          if(stop.disabled) return;
          setStopConfirmOpen(true);
          try{tg?.HapticFeedback?.selectionChanged?.()}catch(_){}
        });
        stopConfirmNo?.addEventListener('click',()=>setStopConfirmOpen(false));
        stopConfirmBackdrop?.addEventListener('click',()=>setStopConfirmOpen(false));
        stopConfirmYes?.addEventListener('click',finishFasting);
        document.addEventListener('keydown',(event)=>{
          if(event.key==='Escape'&&stopConfirm&&!stopConfirm.hidden) setStopConfirmOpen(false);
        });
      }

      let activeKitchenView='products';

      function setKitchenView(view,{scroll=false}={}){
        const next=['products','recipes','saves'].includes(String(view||''))?String(view):'products';
        activeKitchenView=next;
        document.querySelectorAll('[data-kitchen-view]').forEach(button=>{
          const active=button.dataset.kitchenView===next;
          button.setAttribute('aria-pressed',active?'true':'false');
          button.classList.toggle('is-active',active);
        });
        document.querySelectorAll('[data-kitchen-panel]').forEach(panel=>{
          const active=panel.dataset.kitchenPanel===next;
          panel.hidden=!active;
          panel.setAttribute('aria-hidden',active?'false':'true');
        });
        if(next==='saves'){
          const list=document.getElementById('savedRecipesList');
          if(!list?.children?.length) Promise.resolve(window.RUDI_SAVES?.load?.()).catch(()=>{});
        }
        if(scroll){
          const panel=document.querySelector('[data-kitchen-panel="'+next+'"]');
          requestAnimationFrame(()=>panel?.scrollIntoView({behavior:'smooth',block:'start'}));
        }
      }

